//! MiniMax H3 (Hailuo 3.0) audio-video DiT — packed-layout and schedule math.
//!
//! H3 denoises video (24ch, patch 1x2x2) and stereo audio (32ch, 40 Hz) latents
//! JOINTLY in one full-attention stream conditioned on Qwen3-VL-32B layer-50
//! hidden states. The packed sequence is
//!     [text | cond rows | audio | video]   (t2va / fl2va)
//!     [text | reference blocks | audio | video]  (ref2va)
//! and every row carries a 3D (t, h, w) position feeding a partial split-half
//! RoPE (rot_dim 96 of head_dim 128, 16 inverse frequencies per axis).
//!
//! This file is the WEIGHTLESS layer: the frame ladder, the canvas rule, the
//! dual sigma schedule, the position grids and the packed layout. It is pinned
//! by a hermetic test against `fixtures/minimax_h3_layout.json`, which is
//! generated by `tests/dump_minimax_h3_layout.py` calling ComfyUI's own
//! `comfy/ldm/minimax/model.py` — the golden values are the reference's output,
//! never a transcription of its formulas.
//!
//! Three things here are easy to get subtly wrong and produce a model that runs
//! and generates the WRONG video rather than erroring:
//!   1. Frame counts live on a 17k+5 ladder (5, 22, 39, 56, ... 124 ... 362).
//!      Not LTX's 8N+1. The VAE folds 17 source frames into 5 latent frames.
//!   2. Position coordinates are AREA-NORMALIZED, not raw indices: each axis is
//!      a half-open linspace over (1-ratio)/2 .. (1+ratio)/2 scaled by 32, with
//!      ratio = dim / sqrt(h*w). Aspect ratio therefore moves every position.
//!   3. Temporal spans cycle FRAME_PER_TOKEN (1,4,4,4,4) * 5/3, so latent frame
//!      k covers 1 or 4 source frames depending on k % 5 — the grid is NOT
//!      uniformly spaced.

const std = @import("std");
const mlx = @import("mlx.zig");
const model_mod = @import("model.zig");
const log = @import("log.zig");
const mage_flow = @import("mage_flow.zig");
/// Runtime LoRA adapters, shared with the image/LTX backends — ONE loader for
/// every adapter format we accept, Turbo included.
const lora_mod = @import("lora.zig");
const gen_sse = @import("gen_sse.zig");
/// Vision presentation math (grids, adaLN tags, mRoPE), pinned against
/// ComfyUI's own output by `fixtures/minimax_h3_vision.json`.
pub const h3v = @import("minimax_h3_vision.zig");
pub const audio_mod = @import("minimax_h3_audio.zig");

const Weights = model_mod.Weights;
const S = mlx.mlx_stream;
/// Dense-or-quantized linear, shared with mage_flow.zig so the bf16 releases and
/// our affine-quantized mirrors load through ONE geometry solve.
const MfLinear = mage_flow.MfLinear;

// ── Constants (asserted against the reference in the fixture test) ───────────

/// Source frames represented by latent frame k, cycling on k % 5. The VAE is
/// f16t4d24 on average but NOT uniform: 1 + 4*4 = 17 frames per 5 latents.
pub const FRAME_PER_TOKEN = [5]u32{ 1, 4, 4, 4, 4 };
pub const FRAME_RESCALE: f64 = 5.0 / 3.0;
pub const VISUAL_COND_TIMESTEP: f64 = 0.999;
pub const AUDIO_COND_TIMESTEP: f64 = 1.0;

pub const CANVAS_MULTIPLE: u32 = 32;
pub const BASE_SHORT_EDGE: u32 = 768;
pub const MAX_PIXELS: u32 = 768 * 1344;
pub const FPS: u32 = 24;
pub const AUDIO_LATENT_FPS: u32 = 40;

/// Defaults from the checkpoint's `model_index.json` `sigma_shift_scales`.
pub const SIGMA_SHIFT_VIDEO: f64 = 12.0;
pub const SIGMA_SHIFT_AUDIO: f64 = 3.0;

/// Spatial compression: VAE 16x, then the DiT's 2x2 patch → 32x effective.
pub const VAE_SPATIAL: u32 = 16;
pub const PATCH_H: u32 = 2;
pub const PATCH_W: u32 = 2;

// ── Frame ladder ────────────────────────────────────────────────────────────

/// Snap UP to the model's 17k+5 grid. 40 -> 56, 200 -> 209, 363 -> 379.
pub fn alignFrameCount(n: u32) u32 {
    var v = n;
    while (v % 17 != 5) v += 1;
    return v;
}

/// Snap DOWN to the same ladder, with the model's 5-frame floor. A ref2va
/// reference video is TRIMMED rather than padded — the reference node drops
/// frames off the end (`while n % 17 != 5: n -= 1`) because inventing frames
/// for a reference would condition on content the user never supplied.
pub fn alignRefFrameCount(n: u32) u32 {
    if (n < 5) return 0; // below the floor: not a usable reference
    var v = n;
    while (v % 17 != 5) v -= 1;
    return v;
}

/// Latent frames for an aligned source-frame count.
pub fn videoLatentT(frame_count: u32) u32 {
    if (frame_count <= 5) return 2;
    return ((frame_count - 5) / 17) * 5 + 2;
}

pub const TemporalShape = struct { frame_count: u32, latent_t: u32, audio_t: u32 };

/// Aligned frame count + its latent-frame and audio-latent counts.
pub fn temporalShape(length: u32) TemporalShape {
    const frame_count = alignFrameCount(@max(5, length));
    const fc: f64 = @floatFromInt(frame_count);
    // audio_t = round(frame_count / 24 * 40) = round(frame_count * 5 / 3). The
    // reference uses Python's banker's rounding, but frame_count*5/3 can only
    // have fraction 0, 1/3 or 2/3 — never exactly 1/2 — so the two agree and
    // plain rounding is safe here. adaptCanvas is NOT so lucky; see below.
    const audio_t = @round(fc / @as(f64, @floatFromInt(FPS)) * @as(f64, @floatFromInt(AUDIO_LATENT_FPS)));
    return .{
        .frame_count = frame_count,
        .latent_t = videoLatentT(frame_count),
        .audio_t = @intFromFloat(audio_t),
    };
}

// ── Canvas ──────────────────────────────────────────────────────────────────

pub const Canvas = struct { w: u32, h: u32 };

/// 768-short-edge canvas under the 768*1344 area cap, each axis rounded to 32.
/// Note this UPSCALES a small input (640x480 -> 1024x768): it normalizes to the
/// model's native short edge. Applied to ref2va REFERENCE videos only — the
/// target canvas comes straight from the request.
pub fn adaptCanvas(w: u32, h: u32) Canvas {
    const fw: f64 = @floatFromInt(w);
    const fh: f64 = @floatFromInt(h);
    const ratio = fw / fh;
    const base: f64 = @floatFromInt(BASE_SHORT_EDGE);
    var nom_w: f64 = if (ratio >= 1.0) base * ratio else base;
    var nom_h: f64 = if (ratio >= 1.0) base else base / ratio;

    const cap: f64 = @floatFromInt(MAX_PIXELS);
    if (nom_w * nom_h > cap) {
        const s = @sqrt(cap / (nom_w * nom_h));
        nom_w *= s;
        nom_h *= s;
    }
    const m: f64 = @floatFromInt(CANVAS_MULTIPLE);
    return .{
        .w = @max(CANVAS_MULTIPLE, @as(u32, @intFromFloat(roundHalfEven(nom_w / m) * m))),
        .h = @max(CANVAS_MULTIPLE, @as(u32, @intFromFloat(roundHalfEven(nom_h / m) * m))),
    };
}

/// ref2va reference-image sizing. `match` scales (DOWN only) to the
/// generation's pixel AREA; `max` scales to a 2048 short edge for identity
/// fidelity. Reference tokens ride through EVERY sampling step, so `max` is
/// several times slower — that is a user-facing fact, not an implementation
/// detail, and the request docs say so.
pub const RefImageSizing = enum { match, max };
pub const REF_IMAGE_SHORT_EDGE: u32 = 2048;

fn snap32(v: f64) u32 {
    const m: f64 = @floatFromInt(CANVAS_MULTIPLE);
    const r = roundHalfEven(v / m) * m;
    return @max(CANVAS_MULTIPLE, @as(u32, @intFromFloat(r)));
}

/// The canvas a reference IMAGE is resized to before it is VAE-encoded and fed
/// to the vision tower. Never upscales (`min(1.0, …)`) — inventing detail for
/// a reference is worse than giving the model fewer tokens.
pub fn refImageCanvas(w: u32, h: u32, gen_w: u32, gen_h: u32, mode: RefImageSizing) Canvas {
    const fw: f64 = @floatFromInt(w);
    const fh: f64 = @floatFromInt(h);
    const scale = switch (mode) {
        .match => @min(1.0, @sqrt((@as(f64, @floatFromInt(gen_w)) * @as(f64, @floatFromInt(gen_h))) / (fw * fh))),
        .max => @min(1.0, @as(f64, @floatFromInt(REF_IMAGE_SHORT_EDGE)) / @as(f64, @floatFromInt(@min(w, h)))),
    };
    return .{ .w = snap32(fw * scale), .h = snap32(fh * scale) };
}

/// The canvas a reference VIDEO is resized to. `adaptCanvas` normalizes to the
/// model's 768 short edge, which UPSCALES a small clip; the reference node
/// declines that and falls back to plain /32 rounding, so a reference video is
/// never enlarged.
pub fn refVideoCanvas(w: u32, h: u32) Canvas {
    const c = adaptCanvas(w, h);
    if (w * h < c.w * c.h) {
        return .{ .w = snap32(@floatFromInt(w)), .h = snap32(@floatFromInt(h)) };
    }
    return c;
}

// ── ref2va request resolution ───────────────────────────────────────────────
//
// Turning a request's reference list into the block list `PackedLayout` wants
// is pure arithmetic, and it is where the ORDER and the ORDINALS are decided —
// both of which are a contract with the checkpoint, since the prompt addresses
// references as `<Picture i>` / `<Video k>` / `<Audio j>`. Kept separate from
// any decoding so it can be tested without pixels.

pub const MAX_REF_IMAGES: usize = 9;
pub const MAX_REF_VIDEOS: usize = 3;
pub const MAX_REF_AUDIOS: usize = 3;
/// MiniMax's own limit is 12 files ACROSS all types, which the three per-type
/// caps do not express — they sum to 15, so a set can clear every one of them
/// and still be a set the model was never given.
pub const MAX_REF_TOTAL: usize = 12;
/// The reference node's floor: below 5 frames (~0.2 s at 24 fps) there is not
/// one latent frame to condition on.
pub const MIN_REF_VIDEO_FRAMES: u32 = 5;

/// Why a reference set cannot be served. Every arm is a NAMED 400 — a silently
/// dropped reference is worse than a refusal, because the generation succeeds
/// and simply ignores what the user asked it to follow.
pub const RefReject = enum {
    too_many_images,
    too_many_videos,
    too_many_audios,
    too_many_refs,
    video_too_short,
    empty_video,

    pub fn message(self: RefReject) []const u8 {
        return switch (self) {
            .too_many_images => "too many reference images ('ref_images' takes at most 9)",
            .too_many_videos => "too many reference videos ('ref_videos' takes at most 3)",
            .too_many_audios => "too many reference audios ('ref_audios' takes at most 3)",
            .too_many_refs => "too many references: at most 12 files across 'ref_images', 'ref_videos' and 'ref_audios' combined",
            .video_too_short => "a reference video needs at least 5 frames (~0.2s at 24 fps)",
            .empty_video => "a 'ref_videos' entry has no frames",
        };
    }
};

/// One reference as the REQUEST describes it, before anything is decoded.
pub const RefInput = struct {
    kind: enum { image, video, audio },
    /// image / video: the supplied pixel dimensions.
    w: u32 = 0,
    h: u32 = 0,
    /// video: how many source frames were supplied (at 24 fps).
    frames: u32 = 0,
    /// audio (standalone, or a video's soundtrack): samples AT THE VAE's
    /// 32 kHz rate, i.e. after any resample.
    audio_samples: u32 = 0,
    /// video only: index into the request's `ref_video_audios`, if one was
    /// supplied for this video.
    soundtrack_samples: ?u32 = null,
};

/// A reference resolved to everything the layout, the presentation and the
/// encoders need.
pub const ResolvedRef = struct {
    kind: enum { image, video, audio },
    /// 1-based and PER TYPE: the prompt says `<Picture 2>` for the second
    /// image even if a video came between them.
    ordinal: u32,
    /// Index back into the request's own per-type list, so the caller can find
    /// the bytes it must decode.
    src_index: usize,
    canvas: Canvas = .{ .w = 0, .h = 0 },
    /// video: frames after snapping DOWN to the 17k+5 ladder.
    frames: u32 = 0,
    latent_t: u32 = 0,
    latent_h: u32 = 0,
    latent_w: u32 = 0,
    /// Latent audio frames: a video's soundtrack or a standalone audio.
    audio_t: u32 = 0,
    /// The `<Audio j>` ordinal a video's soundtrack takes — a soundtrack is
    /// LABELLED like a standalone audio and shares its counter.
    audio_ordinal: u32 = 0,
};

/// The DiT block a resolved reference becomes. `resolveRefs` builds its own
/// `blocks` through this, so the generation path can go ref -> block without a
/// second mapping that could drift from it.
pub fn refBlockFor(r: ResolvedRef) RefBlock {
    return switch (r.kind) {
        .image => .{ .kind = .image, .latent_h = r.latent_h, .latent_w = r.latent_w },
        .audio => .{ .kind = .audio, .audio_t = r.audio_t },
        .video => .{
            .kind = .video,
            .latent_t = r.latent_t,
            .latent_h = r.latent_h,
            .latent_w = r.latent_w,
            .audio_t = r.audio_t,
        },
    };
}

pub const RefResolution = struct {
    allocator: std.mem.Allocator,
    refs: []ResolvedRef,
    blocks: []RefBlock,

    pub fn deinit(self: *RefResolution) void {
        self.allocator.free(self.refs);
        self.allocator.free(self.blocks);
    }
};

/// Latent audio frames for a sample count — the encoder right-pads to a whole
/// frame, so this rounds UP.
fn audioLatentFrames(samples: u32) u32 {
    const hop: u32 = 800; // minimax_h3_audio.HOP_LENGTH
    return (samples + hop - 1) / hop;
}

/// Resolve a request's references into presentation order and DiT blocks.
///
/// The order is FIXED by the reference node and is not a preference: images,
/// then videos (each soundtrack's `<Audio j>` label emitted immediately before
/// its `<Video k>`), then standalone audio. Ordinals are 1-based per type, and
/// a video's soundtrack consumes an `<Audio j>` ordinal — so a request with one
/// soundtracked video and one standalone audio has `<Audio 1>` on the
/// soundtrack and `<Audio 2>` standalone, not the other way round.
pub fn resolveRefs(
    allocator: std.mem.Allocator,
    images: []const RefInput,
    videos: []const RefInput,
    audios: []const RefInput,
    gen_w: u32,
    gen_h: u32,
    mode: RefImageSizing,
) !union(enum) { ok: RefResolution, reject: RefReject } {
    // Per-type first: "too many images" is more actionable than "too many
    // files" when it is one list that is over.
    if (images.len > MAX_REF_IMAGES) return .{ .reject = .too_many_images };
    if (videos.len > MAX_REF_VIDEOS) return .{ .reject = .too_many_videos };
    if (audios.len > MAX_REF_AUDIOS) return .{ .reject = .too_many_audios };
    if (images.len + videos.len + audios.len > MAX_REF_TOTAL) return .{ .reject = .too_many_refs };
    for (videos) |v| {
        if (v.frames == 0) return .{ .reject = .empty_video };
        if (v.frames < MIN_REF_VIDEO_FRAMES) return .{ .reject = .video_too_short };
    }

    var refs: std.ArrayList(ResolvedRef) = .empty;
    errdefer refs.deinit(allocator);
    var blocks: std.ArrayList(RefBlock) = .empty;
    errdefer blocks.deinit(allocator);

    var n_img: u32 = 0;
    var n_vid: u32 = 0;
    var n_aud: u32 = 0;

    for (images, 0..) |img, i| {
        n_img += 1;
        const c = refImageCanvas(img.w, img.h, gen_w, gen_h, mode);
        const r: ResolvedRef = .{
            .kind = .image,
            .ordinal = n_img,
            .src_index = i,
            .canvas = c,
            .latent_h = c.h / VAE_SPATIAL,
            .latent_w = c.w / VAE_SPATIAL,
        };
        try refs.append(allocator, r);
        try blocks.append(allocator, refBlockFor(r));
    }

    for (videos, 0..) |vid, i| {
        n_vid += 1;
        const c = refVideoCanvas(vid.w, vid.h);
        const aligned = alignRefFrameCount(vid.frames);
        if (aligned == 0) return .{ .reject = .video_too_short };
        var audio_t: u32 = 0;
        var audio_ord: u32 = 0;
        if (vid.soundtrack_samples) |smp| {
            audio_t = audioLatentFrames(smp);
            n_aud += 1;
            audio_ord = n_aud;
        }
        const r: ResolvedRef = .{
            .kind = .video,
            .ordinal = n_vid,
            .src_index = i,
            .canvas = c,
            .frames = aligned,
            .latent_t = videoLatentT(aligned),
            .latent_h = c.h / VAE_SPATIAL,
            .latent_w = c.w / VAE_SPATIAL,
            .audio_t = audio_t,
            .audio_ordinal = audio_ord,
        };
        try refs.append(allocator, r);
        try blocks.append(allocator, refBlockFor(r));
    }

    for (audios, 0..) |aud, i| {
        n_aud += 1;
        const r: ResolvedRef = .{
            .kind = .audio,
            .ordinal = n_aud,
            .src_index = i,
            .audio_t = audioLatentFrames(aud.audio_samples),
            .audio_ordinal = n_aud,
        };
        try refs.append(allocator, r);
        try blocks.append(allocator, refBlockFor(r));
    }

    return .{ .ok = .{
        .allocator = allocator,
        .refs = try refs.toOwnedSlice(allocator),
        .blocks = try blocks.toOwnedSlice(allocator),
    } };
}

/// Source-frame indices Qwen sees for a reference video: every 12th frame, i.e.
/// 2 fps out of 24. The DiT sees ALL the frames through the VAE; the vision
/// tower sees this subsample with timestamps, which is what the `<T.T seconds>`
/// labels count.
pub fn qwenFrameStride() u32 {
    return FPS / 2;
}

pub fn qwenSampledFrames(aligned_frames: u32) u32 {
    const stride = qwenFrameStride();
    return (aligned_frames + stride - 1) / stride;
}

/// Python's `round`, i.e. half-to-even — NOT Zig's `@round`, which rounds half
/// away from zero. `nom_w / 32` can land exactly on .5 (a 1360-wide nominal
/// canvas gives 42.5), and there the two disagree by a whole 32-pixel step.
/// Inputs here are non-negative, which is what keeps this simple.
fn roundHalfEven(x: f64) f64 {
    const fl = @floor(x);
    const frac = x - fl;
    if (frac > 0.5) return fl + 1;
    if (frac < 0.5) return fl;
    return if (@mod(fl, 2.0) == 0.0) fl else fl + 1;
}

// ── Dual sigma schedule ─────────────────────────────────────────────────────

/// Map a sigma from one shifted schedule to another through the shared base
/// grid: invert sigma = s*b/(1+(s-1)*b), then re-apply the other shift.
pub fn timeShiftSigma(sigma: f64, from_shift: f64, to_shift: f64) f64 {
    const base = shiftToBase(sigma, from_shift);
    return to_shift * base / (1.0 + (to_shift - 1.0) * base);
}

/// Invert sigma = shift*b / (1 + (shift-1)*b) back to the shared base grid.
fn shiftToBase(sigma: f64, shift: f64) f64 {
    return sigma / (shift + sigma * (1.0 - shift));
}

/// d(sigma_to)/d(sigma_from) at the same base-grid point. The audio velocity is
/// scaled by this so the flat ODE the sampler integrates on the VIDEO schedule
/// equals the audio stream's true ODE on its own. Getting it wrong desyncs the
/// soundtrack instead of erroring.
pub fn timeShiftSlope(sigma: f64, from_shift: f64, to_shift: f64) f64 {
    const base = shiftToBase(sigma, from_shift);
    const num = 1.0 + (from_shift - 1.0) * base;
    const den = 1.0 + (to_shift - 1.0) * base;
    return (to_shift * num * num) / (from_shift * den * den);
}

// ── Position grids ──────────────────────────────────────────────────────────

/// Area-normalized coordinates along one spatial axis: n = dim/patch values of
/// (arange(n) * ratio/n + (1-ratio)/2) * 32, ratio = dim / sqrt(area).
/// Caller owns the returned slice.
pub fn axisFromSqrtArea(allocator: std.mem.Allocator, dim: u32, patch: u32, sqrt_area: f64) ![]f64 {
    const n = dim / patch;
    const out = try allocator.alloc(f64, n);
    errdefer allocator.free(out);
    const ratio = @as(f64, @floatFromInt(dim)) / sqrt_area;
    const step = ratio / @as(f64, @floatFromInt(n));
    const start = (1.0 - ratio) / 2.0;
    for (out, 0..) |*v, i| v.* = (@as(f64, @floatFromInt(i)) * step + start) * 32.0;
    return out;
}

/// Temporal span of latent frame k, in the grid's units.
pub fn videoTSpan(k: usize) f64 {
    return FRAME_RESCALE * @as(f64, @floatFromInt(FRAME_PER_TOKEN[k % FRAME_PER_TOKEN.len]));
}

/// Exclusive cumulative sum of the first n spans, offset by `origin`.
/// Caller owns the returned slice.
pub fn videoTGrid(allocator: std.mem.Allocator, n: u32, origin: f64) ![]f64 {
    const out = try allocator.alloc(f64, n);
    errdefer allocator.free(out);
    var acc: f64 = origin;
    for (out, 0..) |*v, i| {
        v.* = acc;
        acc += videoTSpan(i);
    }
    return out;
}

// ── Packed layout ───────────────────────────────────────────────────────────

pub const SegmentKind = enum {
    text,
    cond,
    ref_img,
    ref_audio,
    audio,
    video,

    pub fn fromString(s: []const u8) ?SegmentKind {
        inline for (@typeInfo(SegmentKind).@"enum".field_names) |n| {
            if (std.mem.eql(u8, s, n)) return @field(SegmentKind, n);
        }
        return null;
    }

    /// Which embedding stream feeds this segment's rows.
    pub fn stream(self: SegmentKind) enum { text, video, audio } {
        return switch (self) {
            .text => .text,
            .cond, .ref_img, .video => .video,
            .ref_audio, .audio => .audio,
        };
    }

    /// AdaLN modality tag. Three modalities: video 0, text 1, audio 2. The mod
    /// row is `t_row * 3 + tag`, so a wrong tag silently modulates a stream with
    /// another stream's statistics.
    pub fn modalityTag(self: SegmentKind) u32 {
        return switch (self) {
            .video, .cond, .ref_img => 0,
            .text => 1,
            .audio, .ref_audio => 2,
        };
    }
};

pub const Segment = struct { start: u32, end: u32, kind: SegmentKind };

/// Where a keyframe is anchored in the SOURCE frame timeline. Only the first
/// and last frames are anchorable — the reference raises on anything else, and
/// so do we (an interior anchor has no defined temporal coordinate).
pub const KeyframeAnchor = enum { first, last };

/// One ref2va reference block, in REQUEST order. The reference orders them
/// images → videos → standalone audio, and a video's soundtrack packs
/// immediately BEFORE its own video rows (sharing the block's cursor origin),
/// which is why a soundtracked video is one block and not two.
pub const RefBlock = struct {
    kind: enum { image, audio, video },
    /// image / video: the block's OWN latent grid, which need not match the
    /// target's — every reference carries its own aspect.
    latent_h: u32 = 0,
    latent_w: u32 = 0,
    /// video only.
    latent_t: u32 = 0,
    /// Audio latent frames: a video block's soundtrack, or a standalone audio.
    /// Zero means the block contributes no audio rows at all.
    audio_t: u32 = 0,
};

/// Static packed-sequence structure for one shape + conditioning signature.
///
/// Layout is `[text | cond... | audio | video]`, and the target audio/video are
/// ALWAYS the last two segments — the final layer slices them by that promise.
pub const PackedLayout = struct {
    allocator: std.mem.Allocator,
    seq_len: u32,
    segments: []Segment,
    /// [seq_len * 3] row-major (t, h, w). f64 because the reference builds the
    /// grid in float64 and only casts to f32 when computing RoPE angles;
    /// accumulating the temporal cumsum in f32 drifts at long durations.
    position_ids: []f64,
    /// Per video-stream row, in packed order: true = a target row that gets
    /// denoised, false = a condition row that is re-injected every step.
    img_update: []bool,
    audio_update: []bool,
    /// AdaLN modality tag per TEXT row, or empty for a uniform text span.
    /// BORROWED from the encoded prompt — the layout does not free it, and it
    /// must outlive the layout. Non-empty only when the presentation spliced
    /// vision blocks into the prompt, which is the one case where the text
    /// segment is NOT uniform in modality.
    text_tags: []const u8 = &.{},
    text_len: u32,
    latent_t: u32,
    latent_h: u32,
    latent_w: u32,
    audio_t: u32,

    pub fn init(
        allocator: std.mem.Allocator,
        text_len: u32,
        latent_t: u32,
        latent_h: u32,
        latent_w: u32,
        audio_t: u32,
        keyframes: []const KeyframeAnchor,
        frame_count: u32,
    ) !PackedLayout {
        return initFull(allocator, text_len, latent_t, latent_h, latent_w, audio_t, keyframes, frame_count, &.{});
    }

    pub fn initFull(
        allocator: std.mem.Allocator,
        text_len: u32,
        latent_t: u32,
        latent_h: u32,
        latent_w: u32,
        audio_t: u32,
        keyframes: []const KeyframeAnchor,
        frame_count: u32,
        refs: []const RefBlock,
    ) !PackedLayout {
        const area = @sqrt(@as(f64, @floatFromInt(latent_h)) * @as(f64, @floatFromInt(latent_w)));
        const h_axis = try axisFromSqrtArea(allocator, latent_h, PATCH_H, area);
        defer allocator.free(h_axis);
        const w_axis = try axisFromSqrtArea(allocator, latent_w, PATCH_W, area);
        defer allocator.free(w_axis);
        const frame_rows: u32 = @intCast(h_axis.len * w_axis.len);

        const n_cond: u32 = @intCast(keyframes.len);
        const n_audio_rows = audio_t * 2;
        const n_video_rows = latent_t * frame_rows;

        // Reference rows, counted before anything is allocated so the row
        // budgets cannot disagree with what the loop below writes.
        var ref_img_rows: u32 = 0;
        var ref_audio_rows: u32 = 0;
        var ref_segments: u32 = 0;
        for (refs) |b| {
            switch (b.kind) {
                .image => {
                    ref_img_rows += refFrameRows(b);
                    ref_segments += 1;
                },
                .audio => {
                    if (b.audio_t > 0) {
                        ref_audio_rows += b.audio_t * 2;
                        ref_segments += 1;
                    }
                },
                .video => {
                    if (b.audio_t > 0) {
                        ref_audio_rows += b.audio_t * 2;
                        ref_segments += 1;
                    }
                    ref_img_rows += b.latent_t * refFrameRows(b);
                    ref_segments += 1;
                },
            }
        }

        const seq_len = text_len + n_cond * frame_rows + ref_img_rows + ref_audio_rows + n_audio_rows + n_video_rows;

        var segments = try std.ArrayList(Segment).initCapacity(allocator, 3 + n_cond + ref_segments);
        errdefer segments.deinit(allocator);
        const position_ids = try allocator.alloc(f64, @as(usize, seq_len) * 3);
        errdefer allocator.free(position_ids);
        const img_update = try allocator.alloc(bool, n_cond * frame_rows + ref_img_rows + n_video_rows);
        errdefer allocator.free(img_update);
        const audio_update = try allocator.alloc(bool, ref_audio_rows + n_audio_rows);
        errdefer allocator.free(audio_update);

        @memset(position_ids, 0);

        var row: u32 = 0;
        var img_row: u32 = 0;
        var audio_row: u32 = 0;

        // text: t = 0..text_len-1, h = w = 0
        try segments.append(allocator, .{ .start = 0, .end = text_len, .kind = .text });
        for (0..text_len) |i| position_ids[(row + i) * 3] = @floatFromInt(i);
        row += text_len;

        // The cursor the target streams share. Without refs it stays at
        // text_len; the ref2va branch advances it per reference block.
        var cursor: f64 = @floatFromInt(text_len);

        // fl2va keyframe condition rows, sharing the target spatial grid.
        for (keyframes) |anchor| {
            const cond_t: f64 = switch (anchor) {
                .first => cursor,
                // The last keyframe sits at the START of the final latent
                // frame's span, i.e. one FRAME_RESCALE unit back from the end.
                .last => blk: {
                    var spans: f64 = 0;
                    for (0..latent_t) |k| spans += videoTSpan(k);
                    break :blk cursor + spans - FRAME_RESCALE;
                },
            };
            try segments.append(allocator, .{ .start = row, .end = row + frame_rows, .kind = .cond });
            writeFrameGrid(position_ids, row, cond_t, h_axis, w_axis);
            for (0..frame_rows) |_| {
                img_update[img_row] = false; // condition rows are never denoised
                img_row += 1;
            }
            row += frame_rows;
        }
        _ = frame_count; // only the anchor matters; kept for call-site symmetry

        // ref2va blocks, in request order. Each ADVANCES THE CURSOR by its own
        // amount, so the target streams start after everything the references
        // occupy — a wrong advance overlaps a reference with the target in
        // position space and the model conditions on a smear.
        const target_w_low = w_axis[0];
        const target_w_high = w_axis[w_axis.len - 1];
        for (refs) |b| {
            switch (b.kind) {
                .image => {
                    var g = try RefGrid.init(allocator, b);
                    defer g.deinit(allocator);
                    try segments.append(allocator, .{ .start = row, .end = row + g.rows, .kind = .ref_img });
                    writeFrameGrid(position_ids, row, cursor, g.h_axis, g.w_axis);
                    for (0..g.rows) |_| {
                        img_update[img_row] = false;
                        img_row += 1;
                    }
                    row += g.rows;
                    cursor += 1.0;
                },
                .audio => {
                    if (b.audio_t > 0) {
                        const n = b.audio_t * 2;
                        try segments.append(allocator, .{ .start = row, .end = row + n, .kind = .ref_audio });
                        // A STANDALONE audio has no grid of its own, so it is
                        // pinned to the TARGET's w extremes.
                        writeAudioGrid(position_ids, row, cursor, b.audio_t, target_w_low, target_w_high);
                        for (0..n) |_| {
                            audio_update[audio_row] = false;
                            audio_row += 1;
                        }
                        row += n;
                    }
                    cursor += @floatFromInt(b.audio_t);
                },
                .video => {
                    var g = try RefGrid.init(allocator, b);
                    defer g.deinit(allocator);
                    if (b.audio_t > 0) {
                        const n = b.audio_t * 2;
                        try segments.append(allocator, .{ .start = row, .end = row + n, .kind = .ref_audio });
                        // A soundtrack takes ITS OWN video's w extremes, not
                        // the target's — the two differ whenever the reference
                        // has a different aspect.
                        writeAudioGrid(position_ids, row, cursor, b.audio_t, g.w_axis[0], g.w_axis[g.w_axis.len - 1]);
                        for (0..n) |_| {
                            audio_update[audio_row] = false;
                            audio_row += 1;
                        }
                        row += n;
                    }
                    const n_rows = b.latent_t * g.rows;
                    try segments.append(allocator, .{ .start = row, .end = row + n_rows, .kind = .ref_img });
                    const rt_grid = try videoTGrid(allocator, b.latent_t, cursor);
                    defer allocator.free(rt_grid);
                    for (rt_grid, 0..) |tv, f| {
                        writeFrameGrid(position_ids, row + @as(u32, @intCast(f)) * g.rows, tv, g.h_axis, g.w_axis);
                    }
                    for (0..n_rows) |_| {
                        img_update[img_row] = false;
                        img_row += 1;
                    }
                    row += n_rows;
                    var spans: f64 = 0;
                    for (0..b.latent_t) |k| spans += videoTSpan(k);
                    cursor += @max(@as(f64, @floatFromInt(b.audio_t)), spans);
                },
            }
        }

        // Target audio, then target video — always the last two segments.
        try segments.append(allocator, .{ .start = row, .end = row + n_audio_rows, .kind = .audio });
        writeAudioGrid(position_ids, row, cursor, audio_t, target_w_low, target_w_high);
        for (0..n_audio_rows) |_| {
            audio_update[audio_row] = true;
            audio_row += 1;
        }
        row += n_audio_rows;

        try segments.append(allocator, .{ .start = row, .end = row + n_video_rows, .kind = .video });
        const t_grid = try videoTGrid(allocator, latent_t, cursor);
        defer allocator.free(t_grid);
        for (t_grid, 0..) |tv, f| {
            writeFrameGrid(position_ids, row + @as(u32, @intCast(f)) * frame_rows, tv, h_axis, w_axis);
        }
        for (0..n_video_rows) |_| {
            img_update[img_row] = true;
            img_row += 1;
        }
        row += n_video_rows;

        std.debug.assert(row == seq_len);
        std.debug.assert(img_row == img_update.len);
        std.debug.assert(audio_row == audio_update.len);
        return .{
            .allocator = allocator,
            .seq_len = seq_len,
            .segments = try segments.toOwnedSlice(allocator),
            .position_ids = position_ids,
            .img_update = img_update,
            .audio_update = audio_update,
            .text_len = text_len,
            .latent_t = latent_t,
            .latent_h = latent_h,
            .latent_w = latent_w,
            .audio_t = audio_t,
        };
    }

    pub fn deinit(self: *PackedLayout) void {
        self.allocator.free(self.segments);
        self.allocator.free(self.position_ids);
        self.allocator.free(self.img_update);
        self.allocator.free(self.audio_update);
        self.* = undefined;
    }

    /// The target video segment — the final layer's slice. Last segment by
    /// construction.
    pub fn videoSegment(self: *const PackedLayout) Segment {
        return self.segments[self.segments.len - 1];
    }

    /// The target audio segment — second to last by construction.
    pub fn audioSegment(self: *const PackedLayout) Segment {
        return self.segments[self.segments.len - 2];
    }
};

/// Rows one latent frame of a reference block contributes.
fn refFrameRows(b: RefBlock) u32 {
    return (b.latent_h / PATCH_H) * (b.latent_w / PATCH_W);
}

/// A reference block's OWN area-normalized position axes. Every reference keeps
/// its own aspect, so it cannot borrow the target's grid — the coordinates are
/// normalized over each block's own extent.
const RefGrid = struct {
    h_axis: []f64,
    w_axis: []f64,
    rows: u32,

    fn init(allocator: std.mem.Allocator, b: RefBlock) !RefGrid {
        const area = @sqrt(@as(f64, @floatFromInt(b.latent_h)) * @as(f64, @floatFromInt(b.latent_w)));
        const h = try axisFromSqrtArea(allocator, b.latent_h, PATCH_H, area);
        errdefer allocator.free(h);
        const w = try axisFromSqrtArea(allocator, b.latent_w, PATCH_W, area);
        return .{ .h_axis = h, .w_axis = w, .rows = @intCast(h.len * w.len) };
    }

    fn deinit(self: *RefGrid, allocator: std.mem.Allocator) void {
        allocator.free(self.h_axis);
        allocator.free(self.w_axis);
    }
};

/// One latent frame's rows: t fixed, (h, w) the row-major meshgrid of the axes.
fn writeFrameGrid(pos: []f64, row: u32, t: f64, h_axis: []const f64, w_axis: []const f64) void {
    var i: usize = row;
    for (h_axis) |hv| {
        for (w_axis) |wv| {
            pos[i * 3 + 0] = t;
            pos[i * 3 + 1] = hv;
            pos[i * 3 + 2] = wv;
            i += 1;
        }
    }
}

/// Stereo audio rows, CHANNEL-MAJOR: t advances per latent step, h stays 0, and
/// w is pinned to the spatial grid's two extremes so the two channels occupy
/// distinct positions rather than colliding.
fn writeAudioGrid(pos: []f64, row: u32, cursor: f64, audio_t: u32, w_low: f64, w_high: f64) void {
    for (0..audio_t) |i| {
        const t = cursor + @as(f64, @floatFromInt(i));
        const a = (row + i) * 3;
        pos[a + 0] = t;
        pos[a + 1] = 0;
        pos[a + 2] = w_low;
        const b = (row + audio_t + i) * 3;
        pos[b + 0] = t;
        pos[b + 1] = 0;
        pos[b + 2] = w_high;
    }
}

// ── mlx primitives (file-local, mirroring krea.zig / mage_flow.zig style) ───

inline fn addA(a: mlx.mlx_array, b: mlx.mlx_array, s: S) !mlx.mlx_array {
    var o = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_add(&o, a, b, s));
    return o;
}
inline fn subA(a: mlx.mlx_array, b: mlx.mlx_array, s: S) !mlx.mlx_array {
    var o = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_subtract(&o, a, b, s));
    return o;
}
inline fn mulA(a: mlx.mlx_array, b: mlx.mlx_array, s: S) !mlx.mlx_array {
    var o = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_multiply(&o, a, b, s));
    return o;
}
inline fn reshape(x: mlx.mlx_array, shape: []const c_int, s: S) !mlx.mlx_array {
    var o = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_reshape(&o, x, shape.ptr, shape.len, s));
    return o;
}
inline fn transpose(x: mlx.mlx_array, axes: []const c_int, s: S) !mlx.mlx_array {
    var o = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_transpose_axes(&o, x, axes.ptr, axes.len, s));
    return o;
}
inline fn astype(x: mlx.mlx_array, dt: mlx.mlx_dtype, s: S) !mlx.mlx_array {
    var o = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_astype(&o, x, dt, s));
    return o;
}
inline fn contig(x: mlx.mlx_array, s: S) !mlx.mlx_array {
    var o = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_contiguous(&o, x, false, s));
    return o;
}
fn concat(arrs: []const mlx.mlx_array, axis: c_int, s: S) !mlx.mlx_array {
    const vec = mlx.mlx_vector_array_new();
    defer _ = mlx.mlx_vector_array_free(vec);
    for (arrs) |a| _ = mlx.mlx_vector_array_append_value(vec, a);
    var o = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_concatenate_axis(&o, vec, axis, s));
    return o;
}
fn splitEqual(x: mlx.mlx_array, n: usize, axis: c_int, out: []mlx.mlx_array, s: S) !void {
    var vec = mlx.mlx_vector_array_new();
    defer _ = mlx.mlx_vector_array_free(vec);
    try mlx.check(mlx.mlx_split(&vec, x, @intCast(n), axis, s));
    for (0..n) |i| {
        var o = mlx.mlx_array_new();
        try mlx.check(mlx.mlx_vector_array_get(&o, vec, i));
        out[i] = o;
    }
}
/// Slice `[lo, hi)` on axis 0 of a 2-D array, materialized.
fn sliceRows(x: mlx.mlx_array, lo: c_int, hi: c_int, s: S) !mlx.mlx_array {
    const shp = mlx.getShape(x);
    var start = [_]c_int{ lo, 0 };
    var stop = [_]c_int{ hi, @intCast(shp[1]) };
    var step = [_]c_int{ 1, 1 };
    var o = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(o);
    try mlx.check(mlx.mlx_slice(&o, x, &start, 2, &stop, 2, &step, 2, s));
    return contig(o, s);
}
/// Slice `[lo, hi)` on axis 0 of an array of any rank, materialized.
fn sliceAxis0(x: mlx.mlx_array, lo: c_int, hi: c_int, s: S) !mlx.mlx_array {
    const shp = mlx.getShape(x);
    var start: [8]c_int = @splat(0);
    var stop: [8]c_int = undefined;
    var step: [8]c_int = @splat(1);
    for (shp, 0..) |d, i| stop[i] = @intCast(d);
    start[0] = lo;
    stop[0] = hi;
    var o = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(o);
    try mlx.check(mlx.mlx_slice(&o, x, &start, shp.len, &stop, shp.len, &step, shp.len, s));
    return contig(o, s);
}
/// Slice the last axis of a 4-D array, materialized.
fn sliceLast4(x: mlx.mlx_array, lo: c_int, hi: c_int, s: S) !mlx.mlx_array {
    const shp = mlx.getShape(x);
    var start = [_]c_int{ 0, 0, 0, lo };
    var stop = [_]c_int{ @intCast(shp[0]), @intCast(shp[1]), @intCast(shp[2]), hi };
    var step = [_]c_int{ 1, 1, 1, 1 };
    var o = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(o);
    try mlx.check(mlx.mlx_slice(&o, x, &start, 4, &stop, 4, &step, 4, s));
    return contig(o, s);
}
fn rmsNormLast(x: mlx.mlx_array, w: mlx.mlx_array, eps: f32, s: S) !mlx.mlx_array {
    var o = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_fast_rms_norm(&o, x, w, eps, s));
    return o;
}
fn siluA(x: mlx.mlx_array, s: S) !mlx.mlx_array {
    var o = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_sigmoid(&o, x, s));
    defer _ = mlx.mlx_array_free(o);
    return mulA(x, o, s);
}
fn scalarLike(v: f32, like: mlx.mlx_array, s: S) !mlx.mlx_array {
    const c = mlx.mlx_array_new_float(v);
    defer _ = mlx.mlx_array_free(c);
    return astype(c, mlx.mlx_array_dtype(like), s);
}
fn ownWeight(w: *const Weights, key: []const u8) !mlx.mlx_array {
    const a = w.get(key) orelse {
        log.err("[minimax-h3] MISSING WEIGHT: {s}\n", .{key});
        return error.MissingMiniMaxH3Weight;
    };
    var o = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_array_set(&o, a));
    return o;
}
fn ownWeightAs(w: *const Weights, a: std.mem.Allocator, prefix: []const u8, suffix: []const u8, dt: mlx.mlx_dtype, s: S) !mlx.mlx_array {
    const key = try std.fmt.allocPrint(a, "{s}{s}", .{ prefix, suffix });
    defer a.free(key);
    const raw = try ownWeight(w, key);
    defer _ = mlx.mlx_array_free(raw);
    return astype(raw, dt, s);
}
/// Dense linear stored [out, in]; used only for the checkpoint's fp32 islands,
/// which are small and never quantized.
fn denseLinear(x: mlx.mlx_array, w: mlx.mlx_array, bias: ?mlx.mlx_array, s: S) !mlx.mlx_array {
    const wt = try transpose(w, &[_]c_int{ 1, 0 }, s);
    defer _ = mlx.mlx_array_free(wt);
    const wc = try contig(wt, s);
    defer _ = mlx.mlx_array_free(wc);
    var o = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_matmul(&o, x, wc, s));
    if (bias) |b| {
        defer _ = mlx.mlx_array_free(o);
        return addA(o, b, s);
    }
    return o;
}

// ── Model config ────────────────────────────────────────────────────────────

pub const Config = struct {
    hidden_size: u32 = 5376,
    num_layers: u32 = 50,
    token_refiner_num_layers: u32 = 2,
    num_attention_heads: u32 = 56,
    attention_head_dim: u32 = 128,
    ffn_hidden_size: u32 = 14336,
    latents_dim: u32 = 24,
    audio_latents_dim: u32 = 32,
    text_dim: u32 = 5120,
    timestep_input_dim: u32 = 256,
    time_embed_hidden_size: u32 = 5376,
    time_embed_dim: u32 = 2688,
    rope_inv_freq_len: u32 = 16,
    norm_eps: f32 = 1e-5,
    qk_norm_eps: f32 = 1e-5,
    final_norm_eps: f32 = 1e-5,

    pub fn innerDim(self: Config) u32 {
        return self.num_attention_heads * self.attention_head_dim;
    }
    /// Rotary width: 3 axes x inv_freq_len, doubled by the split-half pairing.
    /// 96 of head_dim 128 — the remaining 32 dims per head pass through.
    pub fn rotDim(self: Config) u32 {
        return self.rope_inv_freq_len * 3 * 2;
    }
    pub fn videoPatchDim(self: Config) u32 {
        return self.latents_dim * PATCH_H * PATCH_W;
    }
};

// ── Weights ─────────────────────────────────────────────────────────────────

/// The low-rank adapters attached to ONE linear, applied at RUN TIME:
/// `y = base(x) + Σᵢ scaleᵢ·(x @ Aᵀᵢ) @ Bᵀᵢ`. Never folded into the base
/// weight — the reference node is explicit that merging rounds the delta away
/// in bf16 and requantizes it away on quantized bases, and both our packs are
/// quantized.
///
/// Non-owning, exactly like flux/krea: the arrays belong to the `lora.Stack`
/// the generation holds, which outlives the model. The Turbo LoRA is simply
/// the first file in that stack — it IS a LoRA, so it gets no private path.
const LoraSlot = struct {
    refs: [lora_mod.MAX_LORAS]lora_mod.Ref = undefined,
    count: u8 = 0,

    fn set(self: *LoraSlot, refs: []const lora_mod.Ref) void {
        self.count = @intCast(refs.len);
        @memcpy(self.refs[0..refs.len], refs);
    }
    fn active(self: *const LoraSlot) []const lora_mod.Ref {
        return self.refs[0..self.count];
    }
};

/// `y + Σ deltas` when anything is attached; `y` unchanged otherwise.
/// Consumes `y` either way, so call sites stay one-line.
fn loraAdd(y: mlx.mlx_array, x: mlx.mlx_array, slot: LoraSlot, s: S) !mlx.mlx_array {
    if (slot.count == 0) return y;
    defer _ = mlx.mlx_array_free(y);
    const d = try lora_mod.deltaSum(x, slot.active(), s);
    defer _ = mlx.mlx_array_free(d);
    return addA(y, d, s);
}

const AttnW = struct {
    qkv: MfLinear,
    q_norm: mlx.mlx_array,
    k_norm: mlx.mlx_array,
    out: MfLinear,
    qkv_lora: LoraSlot = .{},
    out_lora: LoraSlot = .{},

    fn load(w: *const Weights, a: std.mem.Allocator, prefix: []const u8, cfg: Config, dt: mlx.mlx_dtype, s: S) !AttnW {
        const qkv_p = try std.fmt.allocPrint(a, "{s}.qkv_proj", .{prefix});
        defer a.free(qkv_p);
        const out_p = try std.fmt.allocPrint(a, "{s}.out_proj", .{prefix});
        defer a.free(out_p);
        var r: AttnW = .{
            .qkv = try MfLinear.load(w, a, qkv_p, cfg.hidden_size, dt, s),
            .q_norm = try ownWeightAs(w, a, prefix, ".q_norm.weight", dt, s),
            .k_norm = try ownWeightAs(w, a, prefix, ".k_norm.weight", dt, s),
            .out = try MfLinear.load(w, a, out_p, cfg.innerDim(), dt, s),
        };
        errdefer r.deinit();
        return r;
    }
    fn deinit(self: *AttnW) void {
        self.qkv.deinit();
        _ = mlx.mlx_array_free(self.q_norm);
        _ = mlx.mlx_array_free(self.k_norm);
        self.out.deinit();
    }
};

const MlpW = struct {
    fc1: MfLinear, // [2*ffn, hidden] — gate and up FUSED
    fc2: MfLinear,
    fc1_lora: LoraSlot = .{},
    fc2_lora: LoraSlot = .{},

    fn load(w: *const Weights, a: std.mem.Allocator, prefix: []const u8, cfg: Config, dt: mlx.mlx_dtype, s: S) !MlpW {
        const p1 = try std.fmt.allocPrint(a, "{s}.fc1", .{prefix});
        defer a.free(p1);
        const p2 = try std.fmt.allocPrint(a, "{s}.fc2", .{prefix});
        defer a.free(p2);
        var r: MlpW = .{
            .fc1 = try MfLinear.load(w, a, p1, cfg.hidden_size, dt, s),
            .fc2 = try MfLinear.load(w, a, p2, cfg.ffn_hidden_size, dt, s),
        };
        errdefer r.deinit();
        return r;
    }
    fn deinit(self: *MlpW) void {
        self.fc1.deinit();
        self.fc2.deinit();
    }
};

const AdalnW = struct {
    linear: MfLinear,
    bias: mlx.mlx_array,
    /// 6 for a DiT block (shift/scale/gate x msa/mlp), 2 for the final layer.
    expand: u32,
    /// 3 for a DiT block (video/text/audio), 1 for the final layer.
    modalities: u32,
    /// Turbo delta on the projection. Input is silu(t_emb) — exactly what the
    /// reference node re-injects on pruned bases — so hooking `forward` covers
    /// BOTH the precompute path and the per-step MINIMAX_H3_ADALN_PRECOMPUTE=0
    /// path, and the pair is freed with the weight after precompute.
    lora: LoraSlot = .{},

    fn load(w: *const Weights, a: std.mem.Allocator, prefix: []const u8, cfg: Config, expand: u32, modalities: u32, dt: mlx.mlx_dtype, s: S) !AdalnW {
        const p = try std.fmt.allocPrint(a, "{s}.linear", .{prefix});
        defer a.free(p);
        var r: AdalnW = .{
            .linear = try MfLinear.load(w, a, p, cfg.time_embed_dim, dt, s),
            .bias = try ownWeightAs(w, a, prefix, ".linear.bias", dt, s),
            .expand = expand,
            .modalities = modalities,
        };
        errdefer r.deinit();
        return r;
    }
    fn deinit(self: *AdalnW) void {
        self.linear.deinit();
        _ = mlx.mlx_array_free(self.bias);
    }

    /// t_emb [M, time_embed_dim] -> `expand` arrays of [M*modalities, hidden].
    /// Row `t_row * modalities + tag` is the modulation for that timestep and
    /// stream, which is what `SegmentKind.modalityTag` indexes.
    fn forward(self: *const AdalnW, t_emb: mlx.mlx_array, cfg: Config, apply_silu: bool, out: []mlx.mlx_array, s: S) !void {
        std.debug.assert(out.len == self.expand);
        const inp = if (apply_silu) try siluA(t_emb, s) else try contig(t_emb, s);
        defer _ = mlx.mlx_array_free(inp);
        const y_base = try self.linear.forward(inp, self.bias, s);
        const y = try loraAdd(y_base, inp, self.lora, s);
        defer _ = mlx.mlx_array_free(y);
        const m: c_int = @intCast(mlx.getShape(y)[0]);
        const rows = m * @as(c_int, @intCast(self.modalities));
        const cols = @as(c_int, @intCast(self.expand * cfg.hidden_size));
        const v = try reshape(y, &[_]c_int{ rows, cols }, s);
        defer _ = mlx.mlx_array_free(v);
        try splitEqual(v, self.expand, 1, out, s);
    }
};

const BlockW = struct {
    norm1: mlx.mlx_array,
    norm2: mlx.mlx_array,
    attn: AttnW,
    mlp: MlpW,
    /// Null after AdaLN precompute has folded this block's modulation into
    /// `Model.adaln_tables` and released the 260M-param weight.
    adaln: ?AdalnW,

    fn load(w: *const Weights, a: std.mem.Allocator, idx: u32, cfg: Config, dt: mlx.mlx_dtype, s: S) !BlockW {
        const pfx = try std.fmt.allocPrint(a, "blocks.{d}", .{idx});
        defer a.free(pfx);
        const attn_p = try std.fmt.allocPrint(a, "{s}.attn", .{pfx});
        defer a.free(attn_p);
        const mlp_p = try std.fmt.allocPrint(a, "{s}.mlp", .{pfx});
        defer a.free(mlp_p);
        const adaln_p = try std.fmt.allocPrint(a, "{s}.adaln_proj", .{pfx});
        defer a.free(adaln_p);
        var r: BlockW = .{
            .norm1 = try ownWeightAs(w, a, pfx, ".norm1.weight", dt, s),
            .norm2 = try ownWeightAs(w, a, pfx, ".norm2.weight", dt, s),
            .attn = try AttnW.load(w, a, attn_p, cfg, dt, s),
            .mlp = try MlpW.load(w, a, mlp_p, cfg, dt, s),
            .adaln = try AdalnW.load(w, a, adaln_p, cfg, 6, 3, dt, s),
        };
        errdefer r.deinit();
        return r;
    }
    fn deinit(self: *BlockW) void {
        _ = mlx.mlx_array_free(self.norm1);
        _ = mlx.mlx_array_free(self.norm2);
        self.attn.deinit();
        self.mlp.deinit();
        if (self.adaln) |*ad| ad.deinit();
    }
};

const RefinerBlockW = struct {
    norm1: mlx.mlx_array,
    norm2: mlx.mlx_array,
    attn: AttnW,
    mlp: MlpW,

    fn load(w: *const Weights, a: std.mem.Allocator, idx: u32, cfg: Config, dt: mlx.mlx_dtype, s: S) !RefinerBlockW {
        const pfx = try std.fmt.allocPrint(a, "token_refiner.blocks.{d}", .{idx});
        defer a.free(pfx);
        const attn_p = try std.fmt.allocPrint(a, "{s}.attn", .{pfx});
        defer a.free(attn_p);
        const mlp_p = try std.fmt.allocPrint(a, "{s}.mlp", .{pfx});
        defer a.free(mlp_p);
        var r: RefinerBlockW = .{
            .norm1 = try ownWeightAs(w, a, pfx, ".norm1.weight", dt, s),
            .norm2 = try ownWeightAs(w, a, pfx, ".norm2.weight", dt, s),
            .attn = try AttnW.load(w, a, attn_p, cfg, dt, s),
            .mlp = try MlpW.load(w, a, mlp_p, cfg, dt, s),
        };
        errdefer r.deinit();
        return r;
    }
    fn deinit(self: *RefinerBlockW) void {
        _ = mlx.mlx_array_free(self.norm1);
        _ = mlx.mlx_array_free(self.norm2);
        self.attn.deinit();
        self.mlp.deinit();
    }
};

// ── Attention ───────────────────────────────────────────────────────────────

/// Precomputed rotary tables for one packed layout. cos/sin are [S, rot/2].
pub const RopeTables = struct {
    cos: mlx.mlx_array,
    sin: mlx.mlx_array,

    pub fn deinit(self: *RopeTables) void {
        _ = mlx.mlx_array_free(self.cos);
        _ = mlx.mlx_array_free(self.sin);
    }
};

/// Build cos/sin from the layout's [S,3] positions and the checkpoint's
/// inv_freq [16]. Angles are concat(t*inv, h*inv, w*inv) = 48 values, and the
/// split-half pairing rotates dim i against dim i+48.
pub fn buildRope(
    allocator: std.mem.Allocator,
    layout: *const PackedLayout,
    inv_freq: mlx.mlx_array,
    dt: mlx.mlx_dtype,
    s: S,
) !RopeTables {
    const n = layout.seq_len;
    const nf = mlx.getShape(inv_freq)[0]; // 16
    const half: usize = @as(usize, @intCast(nf)) * 3; // 48

    // Positions ride to the GPU as f32. The reference builds the grid in f64
    // and casts here, so this cast is the reference's, not a shortcut.
    const pos_f32 = try allocator.alloc(f32, @as(usize, n) * 3);
    defer allocator.free(pos_f32);
    for (layout.position_ids, 0..) |v, i| pos_f32[i] = @floatCast(v);

    const shape = [_]c_int{ @intCast(n), 3, 1 };
    const pos = mlx.mlx_array_new_data(pos_f32.ptr, &shape, 3, mlx.mlx_dtype.float32);
    defer _ = mlx.mlx_array_free(pos);

    const inv_shape = [_]c_int{ 1, 1, @intCast(nf) };
    const inv3 = try reshape(inv_freq, &inv_shape, s);
    defer _ = mlx.mlx_array_free(inv3);
    const inv_f32 = try astype(inv3, mlx.mlx_dtype.float32, s);
    defer _ = mlx.mlx_array_free(inv_f32);

    // [S,3,1] * [1,1,16] -> [S,3,16] -> [S,48], axis order t,h,w
    const per_axis = try mulA(pos, inv_f32, s);
    defer _ = mlx.mlx_array_free(per_axis);
    const ang = try reshape(per_axis, &[_]c_int{ @intCast(n), @intCast(half) }, s);
    defer _ = mlx.mlx_array_free(ang);

    var c = mlx.mlx_array_new();
    errdefer _ = mlx.mlx_array_free(c);
    try mlx.check(mlx.mlx_cos(&c, ang, s));
    var sn = mlx.mlx_array_new();
    errdefer _ = mlx.mlx_array_free(sn);
    try mlx.check(mlx.mlx_sin(&sn, ang, s));

    // Broadcast slot for [1, S, 1, half] against q/k [1, S, H, head_dim].
    const bshape = [_]c_int{ 1, @intCast(n), 1, @intCast(half) };
    const cb = try reshape(c, &bshape, s);
    _ = mlx.mlx_array_free(c);
    errdefer _ = mlx.mlx_array_free(cb);
    const sb = try reshape(sn, &bshape, s);
    _ = mlx.mlx_array_free(sn);
    errdefer _ = mlx.mlx_array_free(sb);

    const cd = try astype(cb, dt, s);
    _ = mlx.mlx_array_free(cb);
    errdefer _ = mlx.mlx_array_free(cd);
    const sd = try astype(sb, dt, s);
    _ = mlx.mlx_array_free(sb);
    return .{ .cos = cd, .sin = sd };
}

/// Partial split-half rotary on [1, S, H, head_dim]: dims [0,48) pair with
/// [48,96); dims [96,128) pass through UNROTATED. Getting the pass-through
/// wrong (rotating the full head) is silent — the model still runs.
pub fn applyRopePub(x: mlx.mlx_array, rope: RopeTables, half: c_int, head_dim: c_int, s: S) !mlx.mlx_array {
    const x1 = try sliceLast4(x, 0, half, s);
    defer _ = mlx.mlx_array_free(x1);
    const x2 = try sliceLast4(x, half, half * 2, s);
    defer _ = mlx.mlx_array_free(x2);

    const a1 = try mulA(x1, rope.cos, s);
    defer _ = mlx.mlx_array_free(a1);
    const a2 = try mulA(x2, rope.sin, s);
    defer _ = mlx.mlx_array_free(a2);
    var o1 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(o1);
    try mlx.check(mlx.mlx_subtract(&o1, a1, a2, s));

    const b1 = try mulA(x1, rope.sin, s);
    defer _ = mlx.mlx_array_free(b1);
    const b2 = try mulA(x2, rope.cos, s);
    defer _ = mlx.mlx_array_free(b2);
    const o2 = try addA(b1, b2, s);
    defer _ = mlx.mlx_array_free(o2);

    if (half * 2 == head_dim) return concat(&[_]mlx.mlx_array{ o1, o2 }, 3, s);
    const tail = try sliceLast4(x, half * 2, head_dim, s);
    defer _ = mlx.mlx_array_free(tail);
    return concat(&[_]mlx.mlx_array{ o1, o2, tail }, 3, s);
}

/// Sparse attention core over post-rope [1, H, S, hd] q/k/v.
///
/// Strip queries (rows [0, video_start)) keep FULL attention; video queries
/// attend to their pattern's video keys PLUS the strip, via batched SDPA with
/// the frame/stripe axis folded into the batch dim. Key order inside a
/// subset differs from the dense order — softmax is permutation-invariant
/// over keys up to fp rounding, which is inside the sanctioned class.
fn sparseAttend(q: mlx.mlx_array, k: mlx.mlx_array, v: mlx.mlx_array, spec: SparseSpec, scale: f32, s: S) !mlx.mlx_array {
    const shp = mlx.getShape(q);
    const nh = shp[1];
    const seq = shp[2];
    const hd = shp[3];
    const g: c_int = @intCast(spec.video_start);
    const t: c_int = @intCast(spec.t);
    const f: c_int = @intCast(spec.f);
    std.debug.assert(g + t * f == seq);
    const null_a = mlx.mlx_array{ .ctx = null };

    // Strip queries: full attention over every key.
    const qg = try sliceAxis4(q, 2, 0, g, s);
    defer _ = mlx.mlx_array_free(qg);
    var og = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(og);
    try mlx.check(mlx.mlx_fast_scaled_dot_product_attention(&og, qg, k, v, scale, "", null_a, null_a, false, s));

    // Video split + strip keys.
    const qv = try sliceAxis4(q, 2, g, seq, s);
    defer _ = mlx.mlx_array_free(qv);
    const kv = try sliceAxis4(k, 2, g, seq, s);
    defer _ = mlx.mlx_array_free(kv);
    const vv = try sliceAxis4(v, 2, g, seq, s);
    defer _ = mlx.mlx_array_free(vv);
    const kg = try sliceAxis4(k, 2, 0, g, s);
    defer _ = mlx.mlx_array_free(kg);
    const vg = try sliceAxis4(v, 2, 0, g, s);
    defer _ = mlx.mlx_array_free(vg);

    // [1,H,Sv,hd] -> [B, H, L, hd] with the pattern axis folded into batch:
    // spatial B=t, L=f (perm keeps (t) outermost); temporal B=f, L=t.
    const fold = struct {
        fn go(x: mlx.mlx_array, nh_: c_int, t_: c_int, f_: c_int, hd_: c_int, mode: SparseMode, s_: S) !mlx.mlx_array {
            const r = try reshape(x, &[_]c_int{ nh_, t_, f_, hd_ }, s_);
            defer _ = mlx.mlx_array_free(r);
            const perm: [4]c_int = if (mode == .spatial) .{ 1, 0, 2, 3 } else .{ 2, 0, 1, 3 };
            const tr = try transpose(r, &perm, s_);
            defer _ = mlx.mlx_array_free(tr);
            return contig(tr, s_);
        }
    }.go;
    const qb = try fold(qv, nh, t, f, hd, spec.mode, s);
    defer _ = mlx.mlx_array_free(qb);
    const kb = try fold(kv, nh, t, f, hd, spec.mode, s);
    defer _ = mlx.mlx_array_free(kb);
    const vb = try fold(vv, nh, t, f, hd, spec.mode, s);
    defer _ = mlx.mlx_array_free(vb);

    // Strip keys broadcast to every batch element and appended to the keys.
    const nb: c_int = if (spec.mode == .spatial) t else f;
    const bshape = [_]c_int{ nb, nh, g, hd };
    const bc = struct {
        fn go(x: mlx.mlx_array, shape: []const c_int, s_: S) !mlx.mlx_array {
            const r3 = try reshape(x, &[_]c_int{ 1, shape[1], shape[2], shape[3] }, s_);
            defer _ = mlx.mlx_array_free(r3);
            var b = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(b);
            try mlx.check(mlx.mlx_broadcast_to(&b, r3, shape.ptr, shape.len, s_));
            return contig(b, s_);
        }
    }.go;
    const kgb = try bc(kg, &bshape, s);
    defer _ = mlx.mlx_array_free(kgb);
    const vgb = try bc(vg, &bshape, s);
    defer _ = mlx.mlx_array_free(vgb);
    const kcat = try concat(&[_]mlx.mlx_array{ kb, kgb }, 2, s);
    defer _ = mlx.mlx_array_free(kcat);
    const vcat = try concat(&[_]mlx.mlx_array{ vb, vgb }, 2, s);
    defer _ = mlx.mlx_array_free(vcat);

    var ob = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(ob);
    try mlx.check(mlx.mlx_fast_scaled_dot_product_attention(&ob, qb, kcat, vcat, scale, "", null_a, null_a, false, s));

    // Unfold back to [1, H, Sv, hd] in packed row order.
    const inv_perm: [4]c_int = if (spec.mode == .spatial) .{ 1, 0, 2, 3 } else .{ 1, 2, 0, 3 };
    const otr = try transpose(ob, &inv_perm, s);
    defer _ = mlx.mlx_array_free(otr);
    const oc = try contig(otr, s);
    defer _ = mlx.mlx_array_free(oc);
    const ov = try reshape(oc, &[_]c_int{ 1, nh, t * f, hd }, s);
    defer _ = mlx.mlx_array_free(ov);

    return concat(&[_]mlx.mlx_array{ og, ov }, 2, s);
}

/// sliceAxis for the fixed 4-D case (keeps the [1,H,·,hd] shape).
fn sliceAxis4(x: mlx.mlx_array, axis: usize, lo: c_int, hi: c_int, s: S) !mlx.mlx_array {
    const shp = mlx.getShape(x);
    var start = [_]c_int{ 0, 0, 0, 0 };
    var stop = [_]c_int{ shp[0], shp[1], shp[2], shp[3] };
    const step = [_]c_int{ 1, 1, 1, 1 };
    start[axis] = lo;
    stop[axis] = hi;
    var o = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(o);
    try mlx.check(mlx.mlx_slice(&o, x, &start, 4, &stop, 4, &step, 4, s));
    return contig(o, s);
}

/// x [S, hidden] -> [S, hidden]. Full bidirectional attention (no mask): this
/// is a diffusion transformer, every token sees every other.
///
/// `ablate` is `.none` everywhere except the profile ladder; `.sdpa` passes v
/// through in place of the attention output (same shape, projections intact).
fn attnForward(aw: *const AttnW, x: mlx.mlx_array, cfg: Config, rope: ?RopeTables, ablate: Ablate, sparse: ?SparseSpec, s: S) !mlx.mlx_array {
    const n: c_int = @intCast(mlx.getShape(x)[0]);
    const h: c_int = @intCast(cfg.num_attention_heads);
    const hd: c_int = @intCast(cfg.attention_head_dim);
    const half: c_int = @intCast(cfg.rotDim() / 2);

    const qkv_base = try aw.qkv.forward(x, null, s);
    const qkv = try loraAdd(qkv_base, x, aw.qkv_lora, s);
    defer _ = mlx.mlx_array_free(qkv);
    var parts: [3]mlx.mlx_array = undefined;
    try splitEqual(qkv, 3, 1, &parts, s);
    defer for (&parts) |*p| {
        _ = mlx.mlx_array_free(p.*);
    };

    var qkvn: [3]mlx.mlx_array = undefined;
    var built: usize = 0;
    errdefer for (qkvn[0..built]) |p| {
        _ = mlx.mlx_array_free(p);
    };
    for (0..3) |i| {
        // [S, inner] -> [1, S, H, hd]
        const v4 = try reshape(parts[i], &[_]c_int{ 1, n, h, hd }, s);
        if (i == 2) {
            qkvn[i] = v4;
            built += 1;
            continue;
        }
        defer _ = mlx.mlx_array_free(v4);
        // Per-head RMSNorm over head_dim, THEN rope — that order is the
        // reference's fused kernel, and swapping it changes the result.
        const nw = if (i == 0) aw.q_norm else aw.k_norm;
        const normed = try rmsNormLast(v4, nw, cfg.qk_norm_eps, s);
        if (rope) |rp| {
            defer _ = mlx.mlx_array_free(normed);
    qkvn[i] = try applyRopePub(normed, rp, half, hd, s);
        } else {
            qkvn[i] = normed;
        }
        built += 1;
    }
    defer for (&qkvn) |*p| {
        _ = mlx.mlx_array_free(p.*);
    };

    // [1,S,H,hd] -> [1,H,S,hd] for SDPA
    var t: [3]mlx.mlx_array = undefined;
    for (0..3) |i| {
        const tr = try transpose(qkvn[i], &[_]c_int{ 0, 2, 1, 3 }, s);
        defer _ = mlx.mlx_array_free(tr);
        t[i] = try contig(tr, s);
    }
    defer for (&t) |*p| {
        _ = mlx.mlx_array_free(p.*);
    };

    const scale: f32 = 1.0 / @sqrt(@as(f32, @floatFromInt(cfg.attention_head_dim)));
    var attn: mlx.mlx_array = undefined;
    if (ablate == .sdpa) {
        attn = try contig(t[2], s);
    } else if (ablate == .sdpa_dep) {
        const sum_qk = try addA(t[0], t[1], s);
        defer _ = mlx.mlx_array_free(sum_qk);
        const sum3 = try addA(sum_qk, t[2], s);
        defer _ = mlx.mlx_array_free(sum3);
        const third = try scalarLike(1.0 / 3.0, sum3, s);
        defer _ = mlx.mlx_array_free(third);
        attn = try mulA(sum3, third, s);
    } else if (sparse != null and sparse.?.mode != .dense) {
        attn = try sparseAttend(t[0], t[1], t[2], sparse.?, scale, s);
    } else {
        var o = mlx.mlx_array_new();
        errdefer _ = mlx.mlx_array_free(o);
        const null_a = mlx.mlx_array{ .ctx = null };
        try mlx.check(mlx.mlx_fast_scaled_dot_product_attention(&o, t[0], t[1], t[2], scale, "", null_a, null_a, false, s));
        attn = o;
    }
    defer _ = mlx.mlx_array_free(attn);

    // [1,H,S,hd] -> [S, inner]
    const back = try transpose(attn, &[_]c_int{ 0, 2, 1, 3 }, s);
    defer _ = mlx.mlx_array_free(back);
    const bc = try contig(back, s);
    defer _ = mlx.mlx_array_free(bc);
    const flat = try reshape(bc, &[_]c_int{ n, h * hd }, s);
    defer _ = mlx.mlx_array_free(flat);
    const out_base = try aw.out.forward(flat, null, s);
    return loraAdd(out_base, flat, aw.out_lora, s);
}

/// fc1 emits gate and up FUSED as [S, 2*ffn]; SwiGLU is silu(gate) * up.
fn mlpForward(mw: *const MlpW, x: mlx.mlx_array, s: S) !mlx.mlx_array {
    const y_base = try mw.fc1.forward(x, null, s);
    const y = try loraAdd(y_base, x, mw.fc1_lora, s);
    defer _ = mlx.mlx_array_free(y);
    var halves: [2]mlx.mlx_array = undefined;
    try splitEqual(y, 2, 1, &halves, s);
    defer for (&halves) |*p| {
        _ = mlx.mlx_array_free(p.*);
    };
    const g = try siluA(halves[0], s);
    defer _ = mlx.mlx_array_free(g);
    const act = try mulA(g, halves[1], s);
    defer _ = mlx.mlx_array_free(act);
    const o_base = try mw.fc2.forward(act, null, s);
    return loraAdd(o_base, act, mw.fc2_lora, s);
}

// ── Modulation over packed segments ─────────────────────────────────────────

/// A contiguous run of rows sharing one AdaLN modulation row.
pub const ModRun = struct { start: u32, end: u32, mod_row: u32 };

/// `h[a:b] = h[a:b] * (1 + scale[row]) + shift[row]`, applied per run.
///
/// Done by slicing rather than gathering: a gather would materialize
/// [S, hidden] per modulation tensor (81 MB each at the dev shape, six per
/// block), while the runs number a handful.
fn modScaleShift(h: mlx.mlx_array, shift: mlx.mlx_array, scale: mlx.mlx_array, runs: []const ModRun, a: std.mem.Allocator, s: S) !mlx.mlx_array {
    var pieces = try a.alloc(mlx.mlx_array, runs.len);
    defer a.free(pieces);
    var built: usize = 0;
    errdefer for (pieces[0..built]) |p| {
        _ = mlx.mlx_array_free(p);
    };
    const one = try scalarLike(1.0, h, s);
    defer _ = mlx.mlx_array_free(one);

    for (runs, 0..) |r, i| {
        const seg = try sliceRows(h, @intCast(r.start), @intCast(r.end), s);
        defer _ = mlx.mlx_array_free(seg);
        const sc = try sliceRows(scale, @intCast(r.mod_row), @intCast(r.mod_row + 1), s);
        defer _ = mlx.mlx_array_free(sc);
        const sh = try sliceRows(shift, @intCast(r.mod_row), @intCast(r.mod_row + 1), s);
        defer _ = mlx.mlx_array_free(sh);
        const sc1 = try addA(sc, one, s);
        defer _ = mlx.mlx_array_free(sc1);
        const m = try mulA(seg, sc1, s);
        defer _ = mlx.mlx_array_free(m);
        pieces[i] = try addA(m, sh, s);
        built += 1;
    }
    defer for (pieces) |p| {
        _ = mlx.mlx_array_free(p);
    };
    return concat(pieces, 0, s);
}

/// `x[a:b] += other[a:b] * gate[row]`, applied per run.
fn modGate(x: mlx.mlx_array, gate: mlx.mlx_array, other: mlx.mlx_array, runs: []const ModRun, a: std.mem.Allocator, s: S) !mlx.mlx_array {
    var pieces = try a.alloc(mlx.mlx_array, runs.len);
    defer a.free(pieces);
    var built: usize = 0;
    errdefer for (pieces[0..built]) |p| {
        _ = mlx.mlx_array_free(p);
    };
    for (runs, 0..) |r, i| {
        const xs = try sliceRows(x, @intCast(r.start), @intCast(r.end), s);
        defer _ = mlx.mlx_array_free(xs);
        const os = try sliceRows(other, @intCast(r.start), @intCast(r.end), s);
        defer _ = mlx.mlx_array_free(os);
        const g = try sliceRows(gate, @intCast(r.mod_row), @intCast(r.mod_row + 1), s);
        defer _ = mlx.mlx_array_free(g);
        const m = try mulA(os, g, s);
        defer _ = mlx.mlx_array_free(m);
        pieces[i] = try addA(xs, m, s);
        built += 1;
    }
    defer for (pieces) |p| {
        _ = mlx.mlx_array_free(p);
    };
    return concat(pieces, 0, s);
}

// ── Timestep rows ───────────────────────────────────────────────────────────

pub const MAX_UNIQUE_T = 4;

/// The distinct timesteps a forward needs, and the per-run modulation rows.
///
/// The reference derives these analytically rather than carrying a per-token
/// timestep tensor: text and video ride the video timestep, audio rides its own
/// shifted one, and condition rows pin near 1 (they are re-injected clean every
/// step, never denoised).
pub const TimestepPlan = struct {
    unique_t: [MAX_UNIQUE_T]f64,
    n_unique: usize,
    runs: []ModRun,
    allocator: std.mem.Allocator,

    pub fn deinit(self: *TimestepPlan) void {
        self.allocator.free(self.runs);
    }
};

pub const CondNoiseAug = struct {
    visual: f64 = VISUAL_COND_TIMESTEP,
    audio: f64 = AUDIO_COND_TIMESTEP,
};

pub fn buildTimestepPlan(
    allocator: std.mem.Allocator,
    layout: *const PackedLayout,
    sigma_v: f64,
    shift_v: f64,
    shift_a: f64,
    aug: CondNoiseAug,
) !TimestepPlan {
    const t_v = 1.0 - sigma_v;
    const t_a = 1.0 - timeShiftSigma(sigma_v, shift_v, shift_a);

    var uniq: [MAX_UNIQUE_T]f64 = undefined;
    var n: usize = 0;
    const add = struct {
        fn f(buf: *[MAX_UNIQUE_T]f64, cnt: *usize, v: f64) void {
            for (buf[0..cnt.*]) |e| if (e == v) return;
            buf[cnt.*] = v;
            cnt.* += 1;
        }
    }.f;

    var has_vis_cond = false;
    var has_aud_cond = false;
    for (layout.segments) |seg| switch (seg.kind) {
        .cond, .ref_img => has_vis_cond = true,
        .ref_audio => has_aud_cond = true,
        else => {},
    };
    add(&uniq, &n, t_v);
    add(&uniq, &n, t_a);
    if (has_vis_cond) add(&uniq, &n, @max(t_v, aug.visual));
    if (has_aud_cond) add(&uniq, &n, @max(t_a, aug.audio));
    std.mem.sort(f64, uniq[0..n], {}, std.sort.asc(f64));

    const rowOf = struct {
        fn f(buf: []const f64, v: f64) u32 {
            for (buf, 0..) |e, i| if (e == v) return @intCast(i);
            unreachable;
        }
    }.f;

    // One run per segment, EXCEPT a text segment carrying vision blocks: those
    // rows mix modalities, so the reference resolves them into tag runs here.
    // Sized for the worst case (every text row its own run) and trimmed.
    const cap = layout.segments.len + layout.text_tags.len;
    var runs = try allocator.alloc(ModRun, cap);
    errdefer allocator.free(runs);
    var nr: usize = 0;
    for (layout.segments) |seg| {
        const t = switch (seg.kind) {
            .text, .video => t_v,
            .audio => t_a,
            .cond, .ref_img => @max(t_v, aug.visual),
            .ref_audio => @max(t_a, aug.audio),
        };
        // Row = t_row * modalities + tag. The `* 3` is the AdaLN reshape's
        // modality stride, not an arbitrary constant.
        const row_base = rowOf(uniq[0..n], t) * 3;
        if (seg.kind == .text and layout.text_tags.len == seg.end - seg.start) {
            const tags = layout.text_tags;
            var run_start: u32 = 0;
            var i: u32 = 1;
            while (i <= tags.len) : (i += 1) {
                if (i == tags.len or tags[i] != tags[run_start]) {
                    runs[nr] = .{
                        .start = seg.start + run_start,
                        .end = seg.start + i,
                        .mod_row = row_base + tags[run_start],
                    };
                    nr += 1;
                    run_start = i;
                }
            }
            continue;
        }
        runs[nr] = .{ .start = seg.start, .end = seg.end, .mod_row = row_base + seg.kind.modalityTag() };
        nr += 1;
    }
    runs = try allocator.realloc(runs, nr);
    return .{ .unique_t = uniq, .n_unique = n, .runs = runs, .allocator = allocator };
}

// ── Profiling ablation ──────────────────────────────────────────────────────
//
// Phase-0 cost attribution WITHOUT inserting syncs: an arm removes one
// component from the step graph while keeping every shape, so the step-time
// delta against the `.none` baseline prices that component at the loop's own
// eval cadence. The per-phase-eval profiler lesson (MLX_SERVE_DECODE_PROFILE)
// is exactly what this avoids — inserted evals destroy pipelining and inflate
// what they measure.

pub const Ablate = enum {
    /// Full forward — the baseline arm.
    none,
    /// SDPA passes v through: prices the attention KERNEL alone (projections
    /// run) — but q/k become DEAD and lazy-graph pruning removes their norm/
    /// rope/transpose chains too, so this arm OVERSTATES the kernel.
    sdpa,
    /// SDPA replaced by (q+k+v)/3: every input branch stays LIVE, only the
    /// attention kernel itself is removed. The honest SDPA price is
    /// (none - sdpa_dep); (sdpa_dep - sdpa) is the q/k branch cost the plain
    /// arm silently pruned.
    sdpa_dep,
    /// The whole attention block is identity: prices qkv/SDPA/out together.
    attn,
    /// The MLP is identity: prices fc1/SwiGLU/fc2.
    mlp,
    /// Block AdaLN replaced by zero modulation: prices the 13B AdaLN weight
    /// read + its GEMM.
    adaln,
};

pub const AblateMode = union(enum) { off, ladder, fixed: Ablate };

/// MINIMAX_H3_ABLATE: "ladder" cycles arms inside ONE run (one TE+DiT load),
/// a bare arm name pins it, anything else is off. The caller logs a warning on
/// junk — a typo'd env measuring the wrong thing is the silent-flag-eater class.
pub fn ablateModeFrom(raw: ?[]const u8) AblateMode {
    const v = raw orelse return .off;
    if (v.len == 0) return .off;
    if (std.mem.eql(u8, v, "ladder")) return .ladder;
    inline for (@typeInfo(Ablate).@"enum".field_names) |n| {
        if (std.mem.eql(u8, v, n)) return .{ .fixed = @field(Ablate, n) };
    }
    return .off;
}

/// Ladder schedule: 2 warmup steps (graph build + JIT land in step 0), then 3
/// steps per arm starting with a measured `.none` baseline; past the ladder it
/// degrades to `.none` so an over-long STEPS setting stays harmless.
pub fn ladderArmForStep(i: usize) Ablate {
    if (i < 2) return .none;
    const arms = [_]Ablate{ .none, .sdpa, .attn, .mlp, .adaln };
    const idx = (i - 2) / 3;
    return if (idx < arms.len) arms[idx] else .none;
}

/// `buildTimestepPlan`, but with every run's modulation row remapped into a
/// GLOBAL sorted schedule table — the shape AdaLN precompute serves rows from.
/// A timestep missing from the table is a LOUD error, never a wrong row.
pub fn buildTimestepPlanGlobal(
    allocator: std.mem.Allocator,
    layout: *const PackedLayout,
    sigma_v: f64,
    shift_v: f64,
    shift_a: f64,
    aug: CondNoiseAug,
    global_ts: []const f64,
) !TimestepPlan {
    var p = try buildTimestepPlan(allocator, layout, sigma_v, shift_v, shift_a, aug);
    errdefer p.deinit();
    for (p.runs) |*r| {
        const t = p.unique_t[r.mod_row / 3];
        const tag = r.mod_row % 3;
        const gi = for (global_ts, 0..) |g, i| {
            if (g == t) break i;
        } else return error.TimestepNotInSchedule;
        r.mod_row = @as(u32, @intCast(gi)) * 3 + tag;
    }
    return p;
}

/// The union of every step's unique timesteps, sorted ascending — computed by
/// running the SAME per-step plan arithmetic, so the f64s are bit-identical to
/// what the sampling loop will look up.
pub fn collectScheduleTs(
    allocator: std.mem.Allocator,
    layout: *const PackedLayout,
    sigmas: []const f64,
    shift_v: f64,
    shift_a: f64,
    aug: CondNoiseAug,
) ![]f64 {
    var list: std.ArrayList(f64) = .empty;
    errdefer list.deinit(allocator);
    for (sigmas) |sig| {
        var p = try buildTimestepPlan(allocator, layout, sig, shift_v, shift_a, aug);
        defer p.deinit();
        for (p.unique_t[0..p.n_unique]) |t| {
            const seen = for (list.items) |e| {
                if (e == t) break true;
            } else false;
            if (!seen) try list.append(allocator, t);
        }
    }
    const out = try list.toOwnedSlice(allocator);
    std.mem.sort(f64, out, {}, std.sort.asc(f64));
    return out;
}

// ── Sparse video attention (training-free, SVG/STA-style) ───────────────────
//
// Full attention over the packed sequence is O(S²) and ~70% of a 768p step.
// Video-DiT attention mass concentrates in two patterns: SPATIAL (within the
// same frame) and TEMPORAL (same patch across frames). Each video query can
// attend to its pattern's keys plus the GLOBAL STRIP (text/cond/audio rows —
// they are few and carry the conditioning), while strip queries keep full
// attention. Softmax is over the reduced key set — a training-free
// approximation whose quality is judged by clips, not asserted.
//
// Layer policy (`MINIMAX_H3_SPARSE_ATTN`): "mix" alternates spatial/temporal
// per layer with dense anchor layers at the ends and middle; "spatial"/
// "temporal" force one pattern everywhere (debug); unset/"" = off.

pub const SparseMode = enum { dense, spatial, temporal };

pub const SparsePolicy = enum { off, mix, spatial, temporal };

pub fn sparsePolicyFrom(raw: ?[]const u8) SparsePolicy {
    const v = raw orelse return .off;
    if (v.len == 0 or std.mem.eql(u8, v, "0")) return .off;
    if (std.mem.eql(u8, v, "mix")) return .mix;
    if (std.mem.eql(u8, v, "spatial")) return .spatial;
    if (std.mem.eql(u8, v, "temporal")) return .temporal;
    return .off;
}

/// Which pattern a layer runs under a policy. Anchor layers (first two,
/// middle two, last two) stay DENSE under "mix" — they re-integrate global
/// structure the sparse layers cannot see.
pub fn sparseModeForLayer(layer: usize, n_layers: usize, policy: SparsePolicy) SparseMode {
    switch (policy) {
        .off => return .dense,
        .spatial => return .spatial,
        .temporal => return .temporal,
        .mix => {
            const mid = n_layers / 2;
            if (layer < 2 or layer + 2 >= n_layers or layer == mid or layer == mid + 1) return .dense;
            return if (layer % 2 == 0) .spatial else .temporal;
        },
    }
}

/// Geometry the sparse core needs: the video segment is the LAST `t*f` rows
/// of the packed sequence; everything before it is the global strip.
pub const SparseSpec = struct {
    mode: SparseMode,
    /// Latent frames.
    t: u32,
    /// Rows per frame (h/2 * w/2).
    f: u32,
    /// First video row == strip length.
    video_start: u32,
};

// ── Attention broadcast (PAB-style) ─────────────────────────────────────────
//
// Video-DiT attention outputs drift SLOWLY across adjacent mid-schedule steps
// (Pyramid Attention Broadcast's finding, reproduced here by the step-cache's
// own gate statistics), while modulation and the MLP react faster. On
// non-refresh steps every block reuses its cached attention OUTPUT (post
// out-proj) and skips norm1/mod/qkv/SDPA/out entirely — at 768p that branch
// is ~70% of the step. Gating stays per-STEP and deterministic: warmup and
// tail steps always recompute (structure forms early, detail lands late).

pub const AttnBroadcast = struct {
    allocator: std.mem.Allocator,
    /// Per block: the cached attention output [S, hidden]; null ctx = empty.
    blocks: []mlx.mlx_array,

    pub fn init(allocator: std.mem.Allocator, n_blocks: usize) !AttnBroadcast {
        const blocks = try allocator.alloc(mlx.mlx_array, n_blocks);
        for (blocks) |*b| b.* = .{ .ctx = null };
        return .{ .allocator = allocator, .blocks = blocks };
    }
    pub fn deinit(self: *AttnBroadcast) void {
        for (self.blocks) |b| if (b.ctx != null) {
            _ = mlx.mlx_array_free(b);
        };
        self.allocator.free(self.blocks);
    }
};

/// Steps at the head of the schedule that always recompute in full.
/// Scale a gate that is `at_30` steps wide on the 30-step schedule down to
/// short runs, never below 1 and never ABOVE its 30-step width.
///
/// The width has to follow the run length: as literals, warmup 4 + tail 2 are
/// the whole of a 6-step run, so the fast recipe silently did nothing at or
/// below that (live 2026-08-04 — a 4-step 768p run logged "attn-broadcast k=2"
/// and then four identical full steps). Clamping at the 30-step value means no
/// schedule anyone has eyeballed moves: 30 and 50 are bit-identical to the
/// literals, only shorter runs change.
fn scaledGate(steps: u32, at_30: u32) usize {
    return @max(1, @min(at_30, steps * at_30 / 30));
}

fn attnBroadcastWarmup(steps: u32) usize {
    return scaledGate(steps, 4);
}

/// Steps at the tail that always recompute in full.
fn attnBroadcastTail(steps: u32) usize {
    return scaledGate(steps, 2);
}

/// Steps before the velocity cache may reuse a previous forward. Never 0 —
/// step 0 has no previous velocity to reuse.
pub fn stepCacheWarmup(steps: u32) usize {
    return scaledGate(steps, 2);
}

/// Refresh schedule: k<=1 disables broadcast (always refresh); otherwise the
/// warmup and tail steps always recompute, and every k-th step in between.
pub fn attnBroadcastRefresh(i: usize, steps: u32, k: u32) bool {
    if (k <= 1) return true;
    const warm = attnBroadcastWarmup(steps);
    if (i < warm) return true;
    if (i + attnBroadcastTail(steps) >= steps) return true;
    return (i - warm) % k == 0;
}

// ── Model ───────────────────────────────────────────────────────────────────

/// Whole-schedule AdaLN tables: per block, the 6 modulation arrays evaluated
/// at EVERY timestep the sampling schedule will visit ([n_ts*3, hidden] each,
/// rows indexed `global_t_row * 3 + modality`), plus the final layer's pair.
/// ~12 MB/block bf16 at 30 steps — against the 13.04B AdaLN parameters (39%
/// of the model) they replace. A MEMORY lever, not a speed one: the per-step
/// AdaLN cost measured ~0 in the Phase-0 ladder.
pub const AdalnTables = struct {
    allocator: std.mem.Allocator,
    ts: []f64,
    blocks: [][6]mlx.mlx_array,
    final: [2]mlx.mlx_array,

    pub fn deinit(self: *AdalnTables) void {
        for (self.blocks) |*six| {
            for (six) |a2| _ = mlx.mlx_array_free(a2);
        }
        self.allocator.free(self.blocks);
        for (self.final) |a2| _ = mlx.mlx_array_free(a2);
        self.allocator.free(self.ts);
        self.* = undefined;
    }
};

pub const Model = struct {
    allocator: std.mem.Allocator,
    cfg: Config,
    dtype: mlx.mlx_dtype,
    /// Profiling arm for the NEXT forward; `.none` in production (the field is
    /// only ever set by the profile ladder in `generate`).
    ablate: Ablate,
    /// Sparse-attention layer policy (`MINIMAX_H3_SPARSE_ATTN`); `.off` until
    /// `generate` opts in.
    sparse_policy: SparsePolicy,

    video_patch_w: mlx.mlx_array, // fp32 island
    video_patch_b: mlx.mlx_array,
    audio_patch_w: mlx.mlx_array,
    audio_patch_b: mlx.mlx_array,
    condition_proj: MfLinear,
    condition_bias: mlx.mlx_array,

    te_in_w: mlx.mlx_array, // time embedder, fp32 island
    te_in_b: mlx.mlx_array,
    te_out_w: mlx.mlx_array,
    te_out_b: mlx.mlx_array,
    inv_freq: mlx.mlx_array,

    refiner: []RefinerBlockW,
    refiner_final_norm: mlx.mlx_array,
    blocks: []BlockW,

    final_norm: mlx.mlx_array,
    /// Null after AdaLN precompute (folded into `adaln_tables.final`).
    final_adaln: ?AdalnW,
    /// Whole-schedule AdaLN tables (see `precomputeAdaln`); null = per-step
    /// weight-based modulation, the load-time default until generate opts in.
    adaln_tables: ?AdalnTables,
    video_out_w: mlx.mlx_array, // fp32 island
    video_out_b: mlx.mlx_array,
    audio_out_w: mlx.mlx_array,
    audio_out_b: mlx.mlx_array,

    pub fn load(allocator: std.mem.Allocator, w: *const Weights, cfg: Config, dt: mlx.mlx_dtype, s: S) !Model {
        var m: Model = undefined;
        m.allocator = allocator;
        m.cfg = cfg;
        m.dtype = dt;
        m.ablate = .none;
        m.sparse_policy = .off;

        const f32t = mlx.mlx_dtype.float32;
        // These stay fp32 because the CHECKPOINT stores them fp32 — the patch
        // projections and output heads are its dense islands, and narrowing
        // them is the MageFlow precision class.
        m.video_patch_w = try ownWeightAs(w, allocator, "video_patch_proj", ".weight", f32t, s);
        m.video_patch_b = try ownWeightAs(w, allocator, "video_patch_proj", ".bias", f32t, s);
        m.audio_patch_w = try ownWeightAs(w, allocator, "audio_patch_proj", ".weight", f32t, s);
        m.audio_patch_b = try ownWeightAs(w, allocator, "audio_patch_proj", ".bias", f32t, s);
        m.condition_proj = try MfLinear.load(w, allocator, "condition_proj", cfg.text_dim, dt, s);
        m.condition_bias = try ownWeightAs(w, allocator, "condition_proj", ".bias", dt, s);

        m.te_in_w = try ownWeightAs(w, allocator, "time_embedder.proj_in", ".weight", f32t, s);
        m.te_in_b = try ownWeightAs(w, allocator, "time_embedder.proj_in", ".bias", f32t, s);
        m.te_out_w = try ownWeightAs(w, allocator, "time_embedder.proj_out", ".weight", f32t, s);
        m.te_out_b = try ownWeightAs(w, allocator, "time_embedder.proj_out", ".bias", f32t, s);
        m.inv_freq = try ownWeightAs(w, allocator, "rope", ".inv_freq", f32t, s);

        m.refiner = try allocator.alloc(RefinerBlockW, cfg.token_refiner_num_layers);
        for (m.refiner, 0..) |*b, i| b.* = try RefinerBlockW.load(w, allocator, @intCast(i), cfg, dt, s);
        m.refiner_final_norm = try ownWeightAs(w, allocator, "token_refiner.final_norm", ".weight", dt, s);

        m.blocks = try allocator.alloc(BlockW, cfg.num_layers);
        for (m.blocks, 0..) |*b, i| b.* = try BlockW.load(w, allocator, @intCast(i), cfg, dt, s);

        m.final_norm = try ownWeightAs(w, allocator, "final_layer.norm", ".weight", dt, s);
        m.final_adaln = try AdalnW.load(w, allocator, "final_layer.adaln_proj", cfg, 2, 1, dt, s);
        m.adaln_tables = null;
        m.video_out_w = try ownWeightAs(w, allocator, "final_layer.video_out", ".weight", f32t, s);
        m.video_out_b = try ownWeightAs(w, allocator, "final_layer.video_out", ".bias", f32t, s);
        m.audio_out_w = try ownWeightAs(w, allocator, "final_layer.audio_out", ".weight", f32t, s);
        m.audio_out_b = try ownWeightAs(w, allocator, "final_layer.audio_out", ".bias", f32t, s);
        return m;
    }

    pub fn deinit(self: *Model) void {
        for ([_]mlx.mlx_array{
            self.video_patch_w, self.video_patch_b, self.audio_patch_w, self.audio_patch_b,
            self.condition_bias, self.te_in_w,      self.te_in_b,       self.te_out_w,
            self.te_out_b,      self.inv_freq,      self.final_norm,    self.video_out_w,
            self.video_out_b,   self.audio_out_w,   self.audio_out_b,   self.refiner_final_norm,
        }) |a| _ = mlx.mlx_array_free(a);
        self.condition_proj.deinit();
        for (self.refiner) |*b| b.deinit();
        self.allocator.free(self.refiner);
        for (self.blocks) |*b| b.deinit();
        self.allocator.free(self.blocks);
        if (self.final_adaln) |*fa| fa.deinit();
        if (self.adaln_tables) |*t| t.deinit();
    }

    /// Force-materialize every weight in ONE eval. Without this the load is
    /// lazy and the 35-64 GB read lands inside step 1, which both hides the
    /// load phase from any profile and makes the first step read as a
    /// regression. Explicit rather than reflective: a missed field here only
    /// shifts a few ms of attribution, never a budget (unlike the dsv4 case).
    pub fn evalWeights(self: *const Model) !void {
        const vec = mlx.mlx_vector_array_new();
        defer _ = mlx.mlx_vector_array_free(vec);
        const push = struct {
            fn arr(v: mlx.mlx_vector_array, x: mlx.mlx_array) void {
                if (x.ctx != null) _ = mlx.mlx_vector_array_append_value(v, x);
            }
            fn lin(v: mlx.mlx_vector_array, l: *const MfLinear) void {
                arr(v, l.w);
                arr(v, l.scales);
                arr(v, l.biases);
            }
            fn at(v: mlx.mlx_vector_array, w: *const AttnW) void {
                lin(v, &w.qkv);
                arr(v, w.q_norm);
                arr(v, w.k_norm);
                lin(v, &w.out);
                lp(v, w.qkv_lora);
                lp(v, w.out_lora);
            }
            fn ml(v: mlx.mlx_vector_array, w: *const MlpW) void {
                lin(v, &w.fc1);
                lin(v, &w.fc2);
                lp(v, w.fc1_lora);
                lp(v, w.fc2_lora);
            }
            fn lp(v: mlx.mlx_vector_array, slot: LoraSlot) void {
                for (slot.active()) |r| {
                    arr(v, r.at);
                    arr(v, r.bt);
                }
            }
        };
        for ([_]mlx.mlx_array{
            self.video_patch_w, self.video_patch_b, self.audio_patch_w, self.audio_patch_b,
            self.condition_bias, self.te_in_w,      self.te_in_b,       self.te_out_w,
            self.te_out_b,      self.inv_freq,      self.final_norm,    self.video_out_w,
            self.video_out_b,   self.audio_out_w,   self.audio_out_b,   self.refiner_final_norm,
        }) |x| push.arr(vec, x);
        push.lin(vec, &self.condition_proj);
        for (self.refiner) |*b| {
            push.arr(vec, b.norm1);
            push.arr(vec, b.norm2);
            push.at(vec, &b.attn);
            push.ml(vec, &b.mlp);
        }
        for (self.blocks) |*b| {
            push.arr(vec, b.norm1);
            push.arr(vec, b.norm2);
            push.at(vec, &b.attn);
            push.ml(vec, &b.mlp);
            if (b.adaln) |*ad| {
                push.lin(vec, &ad.linear);
                push.arr(vec, ad.bias);
                push.lp(vec, ad.lora);
            }
        }
        if (self.final_adaln) |*fa| {
            push.lin(vec, &fa.linear);
            push.arr(vec, fa.bias);
            push.lp(vec, fa.lora);
        }
        try mlx.check(mlx.mlx_eval(vec));
    }

    /// Every linear a LoRA may target, in ONE list, so attach and the
    /// completeness check below cannot disagree about what "all of them" is.
    /// The 259 modules the Turbo LoRA ships: 50 blocks x (qkv, out, fc1, fc2,
    /// adaln) + 2 refiner blocks x (qkv, out, fc1, fc2) + the final adaln.
    pub const LORA_TARGETS: u32 = 259;

    /// Attach every adapter in `stack` to the module it names, summed at
    /// forward time (`lora.deltaSum`). NON-OWNING: `stack` must outlive the
    /// model. Must run BEFORE `precomputeAdaln` — the adaln delta has to be
    /// in place while the tables are built, since the weights are freed after.
    /// Returns per-file attachment counts (index = position in the stack), so
    /// the caller can hold a file to its own expectation: a Turbo file that
    /// attaches to fewer than `LORA_TARGETS` modules is a broken artifact, not
    /// a smaller speedup, while a style LoRA targeting a subset is ordinary.
    pub fn attachLoras(self: *Model, stack: *const lora_mod.Stack) ![lora_mod.MAX_LORAS]u32 {
        var counts: [lora_mod.MAX_LORAS]u32 = @splat(0);
        var buf: [96]u8 = undefined;
        var rbuf: [lora_mod.MAX_LORAS]lora_mod.Ref = undefined;

        // `Stack.findAll` inlined, because the per-FILE attribution is the
        // point: a whole-stack total cannot tell "the style LoRA matched 40
        // modules" from "the Turbo file is missing 40 of its own".
        const bind = struct {
            fn f(st: *const lora_mod.Stack, key: []const u8, slot: *LoraSlot, rb: *[lora_mod.MAX_LORAS]lora_mod.Ref, cnt: *[lora_mod.MAX_LORAS]u32) void {
                var n: usize = 0;
                for (st.files[0..st.count], st.scales[0..st.count], 0..) |*fl, user_scale, fi| {
                    const e = fl.find(key) orelse continue;
                    rb[n] = .{ .at = e.at, .bt = e.bt, .scale = e.scale * user_scale };
                    n += 1;
                    cnt[fi] += 1;
                }
                if (n > 0) slot.set(rb[0..n]);
            }
        }.f;

        for (self.blocks, 0..) |*b, i| {
            const ad = if (b.adaln) |*ad| ad else return error.LoraAfterAdalnPrecompute;
            bind(stack, try std.fmt.bufPrint(&buf, "blocks.{d}.attn.qkv_proj", .{i}), &b.attn.qkv_lora, &rbuf, &counts);
            bind(stack, try std.fmt.bufPrint(&buf, "blocks.{d}.attn.out_proj", .{i}), &b.attn.out_lora, &rbuf, &counts);
            bind(stack, try std.fmt.bufPrint(&buf, "blocks.{d}.mlp.fc1", .{i}), &b.mlp.fc1_lora, &rbuf, &counts);
            bind(stack, try std.fmt.bufPrint(&buf, "blocks.{d}.mlp.fc2", .{i}), &b.mlp.fc2_lora, &rbuf, &counts);
            bind(stack, try std.fmt.bufPrint(&buf, "blocks.{d}.adaln_proj.linear", .{i}), &ad.lora, &rbuf, &counts);
        }
        for (self.refiner, 0..) |*b, i| {
            bind(stack, try std.fmt.bufPrint(&buf, "token_refiner.blocks.{d}.attn.qkv_proj", .{i}), &b.attn.qkv_lora, &rbuf, &counts);
            bind(stack, try std.fmt.bufPrint(&buf, "token_refiner.blocks.{d}.attn.out_proj", .{i}), &b.attn.out_lora, &rbuf, &counts);
            bind(stack, try std.fmt.bufPrint(&buf, "token_refiner.blocks.{d}.mlp.fc1", .{i}), &b.mlp.fc1_lora, &rbuf, &counts);
            bind(stack, try std.fmt.bufPrint(&buf, "token_refiner.blocks.{d}.mlp.fc2", .{i}), &b.mlp.fc2_lora, &rbuf, &counts);
        }
        const fa = if (self.final_adaln) |*fa| fa else return error.LoraAfterAdalnPrecompute;
        bind(stack, "final_layer.adaln_proj.linear", &fa.lora, &rbuf, &counts);
        return counts;
    }

    /// Materialize AdaLN for the whole schedule and RELEASE the 13B AdaLN
    /// weights. Must run while the trunk is still LAZY (before `evalWeights`):
    /// each block's AdaLN weight materializes only inside its own forward here
    /// and is freed immediately after, so the transient peak is one block's
    /// 260M params — never the 13 GB the weights would cost resident.
    ///
    /// NOT bit-identical to per-step modulation: the AdaLN GEMM runs at
    /// M = n_ts instead of M = 2-3, and kernel selection differs by shape
    /// (the sanctioned qmv-vs-qmm class). Kill: MINIMAX_H3_ADALN_PRECOMPUTE=0.
    pub fn precomputeAdaln(self: *Model, ts: []const f64, s: S) !void {
        std.debug.assert(self.adaln_tables == null);
        const a = self.allocator;
        const t_emb32 = try self.timeEmbed(ts, s);
        defer _ = mlx.mlx_array_free(t_emb32);
        const t_emb = try astype(t_emb32, self.dtype, s);
        defer _ = mlx.mlx_array_free(t_emb);

        var tables = try a.alloc([6]mlx.mlx_array, self.blocks.len);
        errdefer a.free(tables);
        var built: usize = 0;
        errdefer for (tables[0..built]) |*six| {
            for (six) |x| _ = mlx.mlx_array_free(x);
        };
        for (self.blocks) |*b| {
            var mods: [6]mlx.mlx_array = undefined;
            try b.adaln.?.forward(t_emb, self.cfg, true, &mods, s);
            const vec = mlx.mlx_vector_array_new();
            defer _ = mlx.mlx_vector_array_free(vec);
            for (mods) |m2| _ = mlx.mlx_vector_array_append_value(vec, m2);
            try mlx.check(mlx.mlx_eval(vec));
            tables[built] = mods;
            built += 1;
            // Free the weight NOW so only one block's AdaLN is ever resident.
            b.adaln.?.deinit();
            b.adaln = null;
        }
        var fmods: [2]mlx.mlx_array = undefined;
        try self.final_adaln.?.forward(t_emb, self.cfg, true, &fmods, s);
        const fvec = mlx.mlx_vector_array_new();
        defer _ = mlx.mlx_vector_array_free(fvec);
        for (fmods) |m2| _ = mlx.mlx_vector_array_append_value(fvec, m2);
        try mlx.check(mlx.mlx_eval(fvec));
        self.final_adaln.?.deinit();
        self.final_adaln = null;
        _ = mlx.mlx_clear_cache();

        const ts_copy = try a.dupe(f64, ts);
        errdefer a.free(ts_copy);
        self.adaln_tables = .{ .allocator = a, .ts = ts_copy, .blocks = tables, .final = fmods };
    }

    /// Sinusoidal timestep embedding, fp32 throughout, COS BEFORE SIN.
    /// The concat order is not cosmetic: swapping the halves silently shifts
    /// every modulation the model produces.
    fn timeEmbed(self: *const Model, t_vals: []const f64, s: S) !mlx.mlx_array {
        const half = self.cfg.timestep_input_dim / 2;
        const m = t_vals.len;
        const buf = try self.allocator.alloc(f32, m * @as(usize, half) * 2);
        defer self.allocator.free(buf);
        const log10k = @log(10000.0);
        for (t_vals, 0..) |t, i| {
            for (0..half) |j| {
                const freq = @exp(-log10k * @as(f64, @floatFromInt(j)) / @as(f64, @floatFromInt(half)));
                const arg = t * freq;
                buf[i * half * 2 + j] = @floatCast(@cos(arg));
                buf[i * half * 2 + half + j] = @floatCast(@sin(arg));
            }
        }
        const shape = [_]c_int{ @intCast(m), @intCast(half * 2) };
        const emb = mlx.mlx_array_new_data(buf.ptr, &shape, 2, mlx.mlx_dtype.float32);
        defer _ = mlx.mlx_array_free(emb);
        const h1 = try denseLinear(emb, self.te_in_w, self.te_in_b, s);
        defer _ = mlx.mlx_array_free(h1);
        const a1 = try siluA(h1, s);
        defer _ = mlx.mlx_array_free(a1);
        return denseLinear(a1, self.te_out_w, self.te_out_b, s);
    }

    /// Qwen states [L, text_dim] -> refined [L, hidden].
    pub fn refineText(self: *const Model, text_states: mlx.mlx_array, s: S) !mlx.mlx_array {
        const hidden: usize = @intCast(mlx.getShape(text_states)[1]);
        if (hidden == self.cfg.hidden_size) return contig(text_states, s);
        var h = try self.condition_proj.forward(text_states, self.condition_bias, s);
        errdefer _ = mlx.mlx_array_free(h);
        for (self.refiner) |*b| {
            const n1 = try rmsNormLast(h, b.norm1, self.cfg.norm_eps, s);
            defer _ = mlx.mlx_array_free(n1);
            const at = try attnForward(&b.attn, n1, self.cfg, null, .none, null, s);
            defer _ = mlx.mlx_array_free(at);
            const h2 = try addA(h, at, s);
            _ = mlx.mlx_array_free(h);
            h = h2;
            const n2 = try rmsNormLast(h, b.norm2, self.cfg.norm_eps, s);
            defer _ = mlx.mlx_array_free(n2);
            const mo = try mlpForward(&b.mlp, n2, s);
            defer _ = mlx.mlx_array_free(mo);
            const h3 = try addA(h, mo, s);
            _ = mlx.mlx_array_free(h);
            h = h3;
        }
        const out = try rmsNormLast(h, self.refiner_final_norm, self.cfg.final_norm_eps, s);
        _ = mlx.mlx_array_free(h);
        return out;
    }

    pub const Output = struct {
        /// Velocity for the video stream, [n_video_rows, videoPatchDim].
        video: mlx.mlx_array,
        /// Velocity for the audio stream, [n_audio_rows, audio_latents_dim],
        /// ALREADY scaled by d(sigma_a)/d(sigma_v).
        audio: mlx.mlx_array,

        pub fn deinit(self: *Output) void {
            _ = mlx.mlx_array_free(self.video);
            _ = mlx.mlx_array_free(self.audio);
        }
    };

    /// One denoising forward over the packed sequence.
    ///
    /// `video_rows` covers EVERY video-stream row in packed order (condition
    /// rows included), likewise `audio_rows`; the caller composes them from the
    /// noisy latents and the clean conditions using `layout.img_update`.
    pub fn forward(
        self: *const Model,
        layout: *const PackedLayout,
        plan: *const TimestepPlan,
        text_states: mlx.mlx_array, // [text_len, hidden] (already refined)
        video_rows: mlx.mlx_array, // [n_video_rows, videoPatchDim] f32
        audio_rows: mlx.mlx_array, // [n_audio_rows, audio_latents_dim] f32
        rope: RopeTables,
        sigma_v: f64,
        shift_v: f64,
        shift_a: f64,
        attn_bcast: ?*AttnBroadcast,
        attn_refresh: bool,
        s: S,
    ) !Output {
        const a = self.allocator;
        const cfg = self.cfg;

        // Embed the two latent streams through their fp32 patch projections.
        const ve32 = try denseLinear(video_rows, self.video_patch_w, self.video_patch_b, s);
        defer _ = mlx.mlx_array_free(ve32);
        const video_embed = try astype(ve32, self.dtype, s);
        defer _ = mlx.mlx_array_free(video_embed);
        const ae32 = try denseLinear(audio_rows, self.audio_patch_w, self.audio_patch_b, s);
        defer _ = mlx.mlx_array_free(ae32);
        const audio_embed = try astype(ae32, self.dtype, s);
        defer _ = mlx.mlx_array_free(audio_embed);

        // Assemble the packed stream segment by segment. Segments are
        // contiguous and each draws from exactly one embedding stream.
        var pieces = try a.alloc(mlx.mlx_array, layout.segments.len);
        defer a.free(pieces);
        var voff: c_int = 0;
        var aoff: c_int = 0;
        var built: usize = 0;
        errdefer for (pieces[0..built]) |p| {
            _ = mlx.mlx_array_free(p);
        };
        for (layout.segments, 0..) |seg, i| {
            const n: c_int = @intCast(seg.end - seg.start);
            switch (seg.kind.stream()) {
                .text => pieces[i] = try contig(text_states, s),
                .video => {
                    pieces[i] = try sliceRows(video_embed, voff, voff + n, s);
                    voff += n;
                },
                .audio => {
                    pieces[i] = try sliceRows(audio_embed, aoff, aoff + n, s);
                    aoff += n;
                },
            }
            built += 1;
        }
        var h = try concat(pieces, 0, s);
        for (pieces) |p| _ = mlx.mlx_array_free(p);
        errdefer _ = mlx.mlx_array_free(h);

        // t_emb is only needed when modulation still runs from weights; with
        // precomputed tables neither the embedder nor any AdalnW exists.
        var t_emb = mlx.mlx_array{ .ctx = null };
        defer if (t_emb.ctx != null) {
            _ = mlx.mlx_array_free(t_emb);
        };
        if (self.adaln_tables == null) {
            const t_emb32 = try self.timeEmbed(plan.unique_t[0..plan.n_unique], s);
            defer _ = mlx.mlx_array_free(t_emb32);
            t_emb = try astype(t_emb32, self.dtype, s);
        }

        // The `.adaln` profile arm replaces every block's modulation with one
        // shared zero tensor (shift=scale=gate=0, rows cover any mod_row), so
        // the arm's saving is exactly the AdaLN weight read + GEMM.
        var zero_mods = mlx.mlx_array{ .ctx = null };
        defer if (zero_mods.ctx != null) {
            _ = mlx.mlx_array_free(zero_mods);
        };
        if (self.ablate == .adaln) {
            const zrows: c_int = if (self.adaln_tables) |tt| @intCast(tt.ts.len * 3) else @intCast(MAX_UNIQUE_T * 3);
            try mlx.check(mlx.mlx_zeros(&zero_mods, &[_]c_int{ zrows, @intCast(cfg.hidden_size) }, 2, self.dtype, s));
        }

        for (self.blocks, 0..) |*b, bi| {
            var mods: [6]mlx.mlx_array = undefined;
            var mods_owned = true;
            if (self.ablate == .adaln) {
                for (&mods) |*p| p.* = try contig(zero_mods, s);
            } else if (self.adaln_tables) |tt| {
                mods = tt.blocks[bi]; // borrowed from the table
                mods_owned = false;
            } else {
                try b.adaln.?.forward(t_emb, cfg, true, &mods, s);
            }
            defer if (mods_owned) for (&mods) |*p| {
                _ = mlx.mlx_array_free(p.*);
            };
            // 0..5 = shift_msa, scale_msa, gate_msa, shift_mlp, scale_mlp, gate_mlp
            //
            // Attention branch: on a broadcast (non-refresh) step the whole
            // branch — norm1, modulation, qkv, SDPA, out-proj — is replaced by
            // the block's cached output from the last refresh; only the GATE
            // is re-applied at the current timestep (PAB semantics). Profile
            // arms bypass the cache so ablation stays honest.
            var at: mlx.mlx_array = undefined;
            var at_owned = true;
            const cacheable = attn_bcast != null and self.ablate == .none;
            if (cacheable and !attn_refresh and attn_bcast.?.blocks[bi].ctx != null) {
                at = attn_bcast.?.blocks[bi];
                at_owned = false;
            } else {
                const n1 = try rmsNormLast(h, b.norm1, cfg.norm_eps, s);
                defer _ = mlx.mlx_array_free(n1);
                const m1 = try modScaleShift(n1, mods[0], mods[1], plan.runs, a, s);
                defer _ = mlx.mlx_array_free(m1);
                const smode = if (self.ablate == .none) sparseModeForLayer(bi, self.blocks.len, self.sparse_policy) else SparseMode.dense;
                const spec: ?SparseSpec = if (smode == .dense) null else .{
                    .mode = smode,
                    .t = layout.latent_t,
                    .f = (layout.latent_h / PATCH_H) * (layout.latent_w / PATCH_W),
                    .video_start = layout.videoSegment().start,
                };
                at = if (self.ablate == .attn) try contig(m1, s) else try attnForward(&b.attn, m1, cfg, rope, self.ablate, spec, s);
                if (cacheable) {
                    if (attn_bcast.?.blocks[bi].ctx != null) _ = mlx.mlx_array_free(attn_bcast.?.blocks[bi]);
                    attn_bcast.?.blocks[bi] = at;
                    at_owned = false;
                }
            }
            defer if (at_owned) {
                _ = mlx.mlx_array_free(at);
            };
            const h1 = try modGate(h, mods[2], at, plan.runs, a, s);
            _ = mlx.mlx_array_free(h);
            h = h1;

            const n2 = try rmsNormLast(h, b.norm2, cfg.norm_eps, s);
            defer _ = mlx.mlx_array_free(n2);
            const m2 = try modScaleShift(n2, mods[3], mods[4], plan.runs, a, s);
            defer _ = mlx.mlx_array_free(m2);
            const mo = if (self.ablate == .mlp) try contig(m2, s) else try mlpForward(&b.mlp, m2, s);
            defer _ = mlx.mlx_array_free(mo);
            const h2 = try modGate(h, mods[5], mo, plan.runs, a, s);
            _ = mlx.mlx_array_free(h);
            h = h2;
        }
        defer _ = mlx.mlx_array_free(h);

        // Final layer: 1 modality, so the mod row is just the timestep row.
        var fmods: [2]mlx.mlx_array = undefined;
        var fmods_owned = true;
        if (self.adaln_tables) |tt| {
            fmods = tt.final;
            fmods_owned = false;
        } else {
            try self.final_adaln.?.forward(t_emb, cfg, true, &fmods, s);
        }
        defer if (fmods_owned) for (&fmods) |*p| {
            _ = mlx.mlx_array_free(p.*);
        };
        const vseg = layout.videoSegment();
        const aseg = layout.audioSegment();
        const v_row = plan.runs[layout.segments.len - 1].mod_row / 3;
        const a_row = plan.runs[layout.segments.len - 2].mod_row / 3;

        const vout = try self.finalHead(h, fmods[0], fmods[1], vseg, v_row, self.video_out_w, self.video_out_b, s);
        errdefer _ = mlx.mlx_array_free(vout);
        const aout_raw = try self.finalHead(h, fmods[0], fmods[1], aseg, a_row, self.audio_out_w, self.audio_out_b, s);
        defer _ = mlx.mlx_array_free(aout_raw);

        // The sampler integrates a flat ODE on the VIDEO schedule. Scaling the
        // audio velocity by d(sigma_a)/d(sigma_v) makes that equal the audio
        // stream's true ODE on its own schedule. Both are negated: the model
        // predicts velocity, the sampler wants the denoise direction.
        const slope = timeShiftSlope(sigma_v, shift_v, shift_a);
        const negv = try scalarLike(-1.0, vout, s);
        defer _ = mlx.mlx_array_free(negv);
        const video = try mulA(vout, negv, s);
        _ = mlx.mlx_array_free(vout);
        errdefer _ = mlx.mlx_array_free(video);
        const nega = try scalarLike(@floatCast(-slope), aout_raw, s);
        defer _ = mlx.mlx_array_free(nega);
        const audio = try mulA(aout_raw, nega, s);
        return .{ .video = video, .audio = audio };
    }

    fn finalHead(self: *const Model, h: mlx.mlx_array, shift: mlx.mlx_array, scale: mlx.mlx_array, seg: Segment, row: u32, w: mlx.mlx_array, b: mlx.mlx_array, s: S) !mlx.mlx_array {
        const part = try sliceRows(h, @intCast(seg.start), @intCast(seg.end), s);
        defer _ = mlx.mlx_array_free(part);
        const nn = try rmsNormLast(part, self.final_norm, self.cfg.final_norm_eps, s);
        defer _ = mlx.mlx_array_free(nn);
        const sc = try sliceRows(scale, @intCast(row), @intCast(row + 1), s);
        defer _ = mlx.mlx_array_free(sc);
        const sh = try sliceRows(shift, @intCast(row), @intCast(row + 1), s);
        defer _ = mlx.mlx_array_free(sh);
        const one = try scalarLike(1.0, nn, s);
        defer _ = mlx.mlx_array_free(one);
        const sc1 = try addA(sc, one, s);
        defer _ = mlx.mlx_array_free(sc1);
        const m = try mulA(nn, sc1, s);
        defer _ = mlx.mlx_array_free(m);
        const mo = try addA(m, sh, s);
        defer _ = mlx.mlx_array_free(mo);
        // The output heads are fp32 islands; the reference casts here too.
        const f = try astype(mo, mlx.mlx_dtype.float32, s);
        defer _ = mlx.mlx_array_free(f);
        return denseLinear(f, w, b, s);
    }
};

// ── Text encoder (Qwen3-VL-32B, truncated to 50 layers) ─────────────────────
//
// H3's conditioning is the UNNORMALIZED hidden state after LM layer 50. The
// Comfy repack is truncated exactly there and ships no `model.norm`, so "tap
// layer 50" is simply "run every layer present and take the output".
//
// The presentation is NOT chat-templated: for t2va the ids are the raw prompt
// with NO special tokens and no prefix/suffix. Every position carries adaLN
// token tag 1 (text); only vision blocks would carry tag 0, and t2va has none.
//
// For text-only input Qwen3-VL's M-RoPE (mrope_section [24,20,20]) collapses to
// plain 1-D rotate-half RoPE, because all three axes share the running position.

pub const TeConfig = struct {
    hidden: c_int = 5120,
    heads: c_int = 64,
    kv_heads: c_int = 8,
    head_dim: c_int = 128,
    intermediate: c_int = 25600,
    layers: u32 = 50,
    theta: f64 = 5_000_000.0,
    eps: f32 = 1e-6,
};

const TeLayerW = struct {
    input_ln: mlx.mlx_array,
    post_ln: mlx.mlx_array,
    qw: MfLinear,
    kw: MfLinear,
    vw: MfLinear,
    ow: MfLinear,
    q_norm: mlx.mlx_array,
    k_norm: mlx.mlx_array,
    gate_w: MfLinear,
    up_w: MfLinear,
    down_w: MfLinear,

    fn deinit(self: *TeLayerW) void {
        inline for (.{ &self.qw, &self.kw, &self.vw, &self.ow, &self.gate_w, &self.up_w, &self.down_w }) |f| f.deinit();
        inline for (.{ self.input_ln, self.post_ln, self.q_norm, self.k_norm }) |f| _ = mlx.mlx_array_free(f);
    }
};

/// `MINIMAX_H3_VISION_DEEPSTACK=0` drops the DeepStack taps — a BISECT arm for
/// the vision conditioning, since the taps are the one part of it that writes
/// into the LM's own residual stream rather than into its input.
fn deepstackEnabled() bool {
    const raw = std.c.getenv("MINIMAX_H3_VISION_DEEPSTACK") orelse return true;
    return !std.mem.eql(u8, std.mem.sliceTo(raw, 0), "0");
}

/// One 2-frame patch block entering the ViT. A still image repeats itself to
/// fill the temporal patch and a video pair carries two distinct frames — the
/// reference's `process_qwen2vl_images` and `process_video_block` differ ONLY
/// in what fills those two slots, so both arrive here as the same shape.
pub const VisionBlock = struct {
    /// [2, 3, H, W] in [-1, 1], already at the block's Qwen canvas.
    frames: mlx.mlx_array,
    grid: h3v.Grid,
};

/// The Qwen presentation stream: raw token ids interleaved with vision blocks.
/// NOT chat-templated — no special tokens beyond the vision delimiters, which
/// this encoder emits itself so a caller cannot forget one.
pub const PresentItem = union(enum) {
    text: []const i32,
    vision: VisionBlock,
};

pub const EncodedPrompt = struct {
    allocator: std.mem.Allocator,
    /// [seq, hidden] — layer-50 hidden state, deliberately NOT final-normed.
    hidden: mlx.mlx_array,
    /// AdaLN modality tag per row (1 text, 0 vision). Feeds the text segment's
    /// run split in `buildTimestepPlan`.
    tags: []u8,

    pub fn deinit(self: *EncodedPrompt) void {
        _ = mlx.mlx_array_free(self.hidden);
        self.allocator.free(self.tags);
    }
};

pub const TextEncoder = struct {
    allocator: std.mem.Allocator,
    cfg: TeConfig,
    dtype: mlx.mlx_dtype,
    embed_table: mlx.mlx_array,
    layers: []TeLayerW,
    /// Loaded only when a caller intends to present vision blocks — the tower
    /// is 529 tensors of the same file and costs ~1 GB resident.
    vision: ?mage_flow.VisionTower = null,

    pub fn load(allocator: std.mem.Allocator, w: *const Weights, cfg: TeConfig, dt: mlx.mlx_dtype, s: S) !TextEncoder {
        var self: TextEncoder = undefined;
        self.allocator = allocator;
        self.cfg = cfg;
        self.dtype = dt;
        self.vision = null;
        const raw = try ownWeight(w, "model.embed_tokens.weight");
        defer _ = mlx.mlx_array_free(raw);
        self.embed_table = try astype(raw, dt, s);
        errdefer _ = mlx.mlx_array_free(self.embed_table);

        self.layers = try allocator.alloc(TeLayerW, cfg.layers);
        errdefer allocator.free(self.layers);
        const a = allocator;
        for (self.layers, 0..) |*layer, i| {
            const p = try std.fmt.allocPrint(a, "model.layers.{d}", .{i});
            defer a.free(p);
            const names = .{ "self_attn.q_proj", "self_attn.k_proj", "self_attn.v_proj", "self_attn.o_proj", "mlp.gate_proj", "mlp.up_proj", "mlp.down_proj" };
            var lin: [7]MfLinear = undefined;
            const in_dims = [7]c_int{ cfg.hidden, cfg.hidden, cfg.hidden, cfg.heads * cfg.head_dim, cfg.hidden, cfg.hidden, cfg.intermediate };
            inline for (names, 0..) |nm, j| {
                const full = try std.fmt.allocPrint(a, "{s}.{s}", .{ p, nm });
                defer a.free(full);
                lin[j] = try MfLinear.load(w, a, full, @intCast(in_dims[j]), dt, s);
            }
            // Norm weights stay f32: mlx_fast_rms_norm upcasts activations, and
            // a bf16 norm weight reintroduces the late-layer outlier divergence
            // mage_flow.zig documents.
            layer.* = .{
                .input_ln = try ownWeightAs(w, a, p, ".input_layernorm.weight", mlx.mlx_dtype.float32, s),
                .post_ln = try ownWeightAs(w, a, p, ".post_attention_layernorm.weight", mlx.mlx_dtype.float32, s),
                .qw = lin[0],
                .kw = lin[1],
                .vw = lin[2],
                .ow = lin[3],
                .q_norm = try ownWeightAs(w, a, p, ".self_attn.q_norm.weight", mlx.mlx_dtype.float32, s),
                .k_norm = try ownWeightAs(w, a, p, ".self_attn.k_norm.weight", mlx.mlx_dtype.float32, s),
                .gate_w = lin[4],
                .up_w = lin[5],
                .down_w = lin[6],
            };
        }
        return self;
    }

    /// Load the Qwen3-VL vision tower out of the SAME weight map. Separate from
    /// `load` because a t2va request never touches it, and the tower is 529
    /// tensors we would otherwise pay for on every generation.
    pub fn loadVision(self: *TextEncoder, w: *const Weights, s: S) !void {
        if (self.vision != null) return;
        self.vision = try mage_flow.VisionTower.loadFrom(self.allocator, s, w, mage_flow.H3_VIT, self.dtype);
    }

    pub fn deinit(self: *TextEncoder) void {
        _ = mlx.mlx_array_free(self.embed_table);
        for (self.layers) |*l| l.deinit();
        self.allocator.free(self.layers);
        if (self.vision) |*v| v.deinit();
    }

    /// Raw prompt ids (NO special tokens) -> [L, hidden] layer-50 hidden state.
    /// Deliberately NOT final-normed: the checkpoint ships no `model.norm` and
    /// the reference sets `layer_norm_hidden_state=False`.
    pub fn encode(self: *const TextEncoder, ids: []const i32, s: S) !mlx.mlx_array {
        const seq: c_int = @intCast(ids.len);
        const cfg = self.cfg;

        const id_shape = [_]c_int{seq};
        const id_arr = mlx.mlx_array_new_data(ids.ptr, &id_shape, 1, mlx.mlx_dtype.int32);
        defer _ = mlx.mlx_array_free(id_arr);
        var emb = mlx.mlx_array_new();
        try mlx.check(mlx.mlx_take_axis(&emb, self.embed_table, id_arr, 0, s));
        var x = try reshape(emb, &[_]c_int{ 1, seq, cfg.hidden }, s);
        _ = mlx.mlx_array_free(emb);
        errdefer _ = mlx.mlx_array_free(x);

        var rope = try self.buildRope(seq, s);
        defer rope.deinit();
        const mask = try causalMask(seq, self.dtype, s);
        defer _ = mlx.mlx_array_free(mask);

        for (self.layers) |*layer| {
            const nx = try self.layerForward(layer, x, mask, rope, seq, s);
            _ = mlx.mlx_array_free(x);
            x = nx;
        }
        const out = try reshape(x, &[_]c_int{ seq, cfg.hidden }, s);
        _ = mlx.mlx_array_free(x);
        return out;
    }

    /// Raw prompt ids + vision blocks -> [seq, hidden] conditioning + adaLN tags.
    ///
    /// This is the reference presentation (`MiniMaxH3Tokenizer.tokenize_with_weights`
    /// + `Qwen3VL.forward`), which differs from the text-only path in three ways
    /// that all matter and none of which error when missed:
    ///   - the LM positions become INTERLEAVED 3-axis mRoPE (a vision block
    ///     collapses to one t position and shifts everything after it),
    ///   - the tower's three DeepStack taps are ADDED into the LM's first three
    ///     layers at the vision rows, and
    ///   - the vision rows carry adaLN modality tag 0 in the DiT, widened over
    ///     the flanking delimiters.
    pub fn encodeItems(self: *const TextEncoder, allocator: std.mem.Allocator, items: []const PresentItem, s: S) !EncodedPrompt {
        const cfg = self.cfg;
        var n_vision: usize = 0;
        for (items) |it| if (it == .vision) {
            n_vision += 1;
        };
        if (n_vision > 0 and self.vision == null) return error.VisionTowerNotLoaded;

        // 1. Walk the stream once: sequence length and the vision spans.
        var spans: std.ArrayList(h3v.Span) = .empty;
        defer spans.deinit(allocator);
        var seq_u: u32 = 0;
        for (items) |it| switch (it) {
            .text => |ids| seq_u += @intCast(ids.len),
            .vision => |vb| {
                const size = vb.grid.mergedTokens();
                // <|vision_start|> pad… <|vision_end|>: the span index is the
                // FIRST pad row, one past the opener.
                try spans.append(allocator, .{ .index = seq_u + 1, .size = size, .grid = vb.grid });
                seq_u += size + 2;
            },
        };
        const seq: c_int = @intCast(seq_u);

        // 2. Run the tower per block, then assemble embeds by concatenation —
        //    every segment is contiguous, so no scatter is needed.
        var merged: std.ArrayList(mlx.mlx_array) = .empty;
        var ds_blocks: std.ArrayList([3]mlx.mlx_array) = .empty;
        defer {
            for (merged.items) |m| _ = mlx.mlx_array_free(m);
            merged.deinit(allocator);
            for (ds_blocks.items) |d| for (d) |x| {
                _ = mlx.mlx_array_free(x);
            };
            ds_blocks.deinit(allocator);
        }
        for (items) |it| if (it == .vision) {
            const vb = it.vision;
            const rows = try visionPatchRows(vb.frames, vb.grid, s);
            defer _ = mlx.mlx_array_free(rows);
            const g = [3]i64{ vb.grid.t, vb.grid.gh, vb.grid.gw };
            const out = try self.vision.?.forward(rows, &[_][3]i64{g});
            try merged.append(allocator, out.merged);
            try ds_blocks.append(allocator, out.deepstack);
        };

        var pieces: std.ArrayList(mlx.mlx_array) = .empty;
        defer {
            for (pieces.items) |p| _ = mlx.mlx_array_free(p);
            pieces.deinit(allocator);
        }
        var vi: usize = 0;
        for (items) |it| switch (it) {
            .text => |ids| try pieces.append(allocator, try self.embedIds(ids, s)),
            .vision => {
                try pieces.append(allocator, try self.embedIds(&[_]i32{h3v.VISION_START}, s));
                try pieces.append(allocator, try astype(merged.items[vi], self.dtype, s));
                try pieces.append(allocator, try self.embedIds(&[_]i32{h3v.VISION_END}, s));
                vi += 1;
            },
        };
        const flat = if (pieces.items.len == 1) try contig(pieces.items[0], s) else try concat(pieces.items, 0, s);
        defer _ = mlx.mlx_array_free(flat);
        var x = try reshape(flat, &[_]c_int{ 1, seq, cfg.hidden }, s);
        errdefer _ = mlx.mlx_array_free(x);

        // 3. Positions: plain 1-D when text-only, interleaved mRoPE otherwise.
        //    `MINIMAX_H3_VISION_MROPE=0` forces plain 1-D even with vision
        //    blocks present — a BISECT arm, since the mRoPE switch changes the
        //    conditioning of the WHOLE prompt, not just the vision rows.
        const mrope_on = blk2: {
            const raw = std.c.getenv("MINIMAX_H3_VISION_MROPE") orelse break :blk2 true;
            break :blk2 !std.mem.eql(u8, std.mem.sliceTo(raw, 0), "0");
        };
        const positions = if (mrope_on) try h3v.mropePositions(allocator, seq_u, spans.items) else null;
        defer if (positions) |p| allocator.free(p);
        var rope = try self.buildRopeFrom(seq, positions, s);
        defer rope.deinit();
        const mask = try causalMask(seq, self.dtype, s);
        defer _ = mlx.mlx_array_free(mask);

        // 4. Layers, with the DeepStack taps folded in after the first three.
        for (self.layers, 0..) |*layer, li| {
            const nx = try self.layerForward(layer, x, mask, rope, seq, s);
            _ = mlx.mlx_array_free(x);
            x = nx;
            if (li < 3 and spans.items.len > 0 and deepstackEnabled()) {
                const pad = try self.deepstackPadded(allocator, seq_u, spans.items, ds_blocks.items, li, s);
                defer _ = mlx.mlx_array_free(pad);
                const summed = try addA(x, pad, s);
                _ = mlx.mlx_array_free(x);
                x = summed;
            }
        }
        const out = try reshape(x, &[_]c_int{ seq, cfg.hidden }, s);
        _ = mlx.mlx_array_free(x);
        errdefer _ = mlx.mlx_array_free(out);
        return .{
            .allocator = allocator,
            .hidden = out,
            .tags = try h3v.tokenTags(allocator, seq_u, spans.items),
        };
    }

    fn embedIds(self: *const TextEncoder, ids: []const i32, s: S) !mlx.mlx_array {
        const shape = [_]c_int{@intCast(ids.len)};
        const arr = mlx.mlx_array_new_data(ids.ptr, &shape, 1, mlx.mlx_dtype.int32);
        defer _ = mlx.mlx_array_free(arr);
        var emb = mlx.mlx_array_new();
        try mlx.check(mlx.mlx_take_axis(&emb, self.embed_table, arr, 0, s));
        return emb;
    }

    /// [1, seq, hidden] that is ZERO everywhere except the vision rows, where it
    /// carries DeepStack tap `li`. The reference writes it with a boolean mask;
    /// spans are contiguous here, so a concat of zero blocks and tap slices is
    /// the same tensor without a scatter.
    fn deepstackPadded(
        self: *const TextEncoder,
        allocator: std.mem.Allocator,
        seq_u: u32,
        spans: []const h3v.Span,
        ds: []const [3]mlx.mlx_array,
        li: usize,
        s: S,
    ) !mlx.mlx_array {
        var parts: std.ArrayList(mlx.mlx_array) = .empty;
        defer {
            for (parts.items) |p| _ = mlx.mlx_array_free(p);
            parts.deinit(allocator);
        }
        var cursor: u32 = 0;
        for (spans, 0..) |sp, i| {
            if (sp.index > cursor) try parts.append(allocator, try self.zeroRows(sp.index - cursor, s));
            try parts.append(allocator, try astype(ds[i][li], self.dtype, s));
            cursor = sp.end();
        }
        if (cursor < seq_u) try parts.append(allocator, try self.zeroRows(seq_u - cursor, s));
        const cat = if (parts.items.len == 1) try contig(parts.items[0], s) else try concat(parts.items, 0, s);
        defer _ = mlx.mlx_array_free(cat);
        return reshape(cat, &[_]c_int{ 1, @intCast(seq_u), self.cfg.hidden }, s);
    }

    fn zeroRows(self: *const TextEncoder, n: u32, s: S) !mlx.mlx_array {
        const shape = [_]c_int{ @intCast(n), self.cfg.hidden };
        var o = mlx.mlx_array_new();
        try mlx.check(mlx.mlx_zeros(&o, &shape, 2, self.dtype, s));
        return o;
    }

    fn buildRope(self: *const TextEncoder, seq: c_int, s: S) !RopeTables {
        return self.buildRopeFrom(seq, null, s);
    }

    /// `positions` is the axis-major [3 * seq] mRoPE table, or null for the
    /// text-only case where all three axes share the running index and the
    /// interleave collapses to plain 1-D rope (which is what the reference's
    /// own `position_ids.shape[0] > 1` branch says).
    fn buildRopeFrom(self: *const TextEncoder, seq: c_int, positions: ?[]const f64, s: S) !RopeTables {
        const hd: usize = @intCast(self.cfg.head_dim);
        const half = hd / 2;
        const n: usize = @intCast(seq);
        const ang = try h3v.ropeAngles(self.allocator, @intCast(n), positions, hd, self.cfg.theta);
        defer self.allocator.free(ang);
        const buf = try self.allocator.alloc(f32, n * half * 2);
        defer self.allocator.free(buf);
        for (0..n) |i| {
            for (0..half) |j| {
                const a = ang[i * half + j];
                buf[i * half * 2 + j] = @floatCast(@cos(a));
                buf[i * half * 2 + half + j] = @floatCast(@sin(a));
            }
        }
        const shape = [_]c_int{ n_c(n), @intCast(half * 2) };
        const arr = mlx.mlx_array_new_data(buf.ptr, &shape, 2, mlx.mlx_dtype.float32);
        defer _ = mlx.mlx_array_free(arr);
        var parts: [2]mlx.mlx_array = undefined;
        try splitEqual(arr, 2, 1, &parts, s);
        defer for (&parts) |*p| {
            _ = mlx.mlx_array_free(p.*);
        };
        // [1, 1, seq, half] to broadcast against [1, H, seq, head_dim]
        const bshape = [_]c_int{ 1, 1, seq, @intCast(half) };
        const c0 = try reshape(parts[0], &bshape, s);
        defer _ = mlx.mlx_array_free(c0);
        const s0 = try reshape(parts[1], &bshape, s);
        defer _ = mlx.mlx_array_free(s0);
        var r: RopeTables = .{
            .cos = try astype(c0, self.dtype, s),
            .sin = try astype(s0, self.dtype, s),
        };
        errdefer r.deinit();
        return r;
    }

    fn layerForward(self: *const TextEncoder, layer: *const TeLayerW, x: mlx.mlx_array, mask: mlx.mlx_array, rope: RopeTables, seq: c_int, s: S) !mlx.mlx_array {
        const cfg = self.cfg;
        const xn = try rmsNormLast(x, layer.input_ln, cfg.eps, s);
        defer _ = mlx.mlx_array_free(xn);

        var qkv: [3]mlx.mlx_array = undefined;
        const heads = [3]c_int{ cfg.heads, cfg.kv_heads, cfg.kv_heads };
        inline for (.{ &layer.qw, &layer.kw, &layer.vw }, 0..) |lw, i| {
            const p = try lw.forward(xn, null, s);
            defer _ = mlx.mlx_array_free(p);
            const r4 = try reshape(p, &[_]c_int{ 1, seq, heads[i], cfg.head_dim }, s);
            if (i == 2) {
                defer _ = mlx.mlx_array_free(r4);
                const t = try transpose(r4, &[_]c_int{ 0, 2, 1, 3 }, s);
                defer _ = mlx.mlx_array_free(t);
                qkv[i] = try contig(t, s);
            } else {
                defer _ = mlx.mlx_array_free(r4);
                const nw = if (i == 0) layer.q_norm else layer.k_norm;
                const nn = try rmsNormLast(r4, nw, cfg.eps, s);
                defer _ = mlx.mlx_array_free(nn);
                const t = try transpose(nn, &[_]c_int{ 0, 2, 1, 3 }, s);
                defer _ = mlx.mlx_array_free(t);
                const tc = try contig(t, s);
                defer _ = mlx.mlx_array_free(tc);
                qkv[i] = try ropeHalf(tc, rope, cfg.head_dim, s);
            }
        }
        defer for (&qkv) |*p| {
            _ = mlx.mlx_array_free(p.*);
        };

        const scale: f32 = 1.0 / @sqrt(@as(f32, @floatFromInt(cfg.head_dim)));
        var attn = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(attn);
        const null_sink = mlx.mlx_array{ .ctx = null };
        try mlx.check(mlx.mlx_fast_scaled_dot_product_attention(&attn, qkv[0], qkv[1], qkv[2], scale, "array", mask, null_sink, false, s));
        const at = try transpose(attn, &[_]c_int{ 0, 2, 1, 3 }, s);
        defer _ = mlx.mlx_array_free(at);
        const af = try reshape(at, &[_]c_int{ 1, seq, cfg.heads * cfg.head_dim }, s);
        defer _ = mlx.mlx_array_free(af);
        const o = try layer.ow.forward(af, null, s);
        defer _ = mlx.mlx_array_free(o);
        const h1 = try addA(x, o, s);
        defer _ = mlx.mlx_array_free(h1);

        const hn = try rmsNormLast(h1, layer.post_ln, cfg.eps, s);
        defer _ = mlx.mlx_array_free(hn);
        const g = try layer.gate_w.forward(hn, null, s);
        defer _ = mlx.mlx_array_free(g);
        const sg = try siluA(g, s);
        defer _ = mlx.mlx_array_free(sg);
        const u = try layer.up_w.forward(hn, null, s);
        defer _ = mlx.mlx_array_free(u);
        const gu = try mulA(sg, u, s);
        defer _ = mlx.mlx_array_free(gu);
        const d = try layer.down_w.forward(gu, null, s);
        defer _ = mlx.mlx_array_free(d);
        return addA(h1, d, s);
    }
};

inline fn n_c(v: usize) c_int {
    return @intCast(v);
}

/// `[2, 3, H, W]` in [-1, 1] -> `[gh*gw, 1536]` ViT patch rows.
///
/// The reference's reshape+permute verbatim: `(1, temporal=2, C=3, gh/2, 2, 16,
/// gw/2, 2, 16)` then `permute(0,3,6,4,7,2,1,5,8)`. Two things ride on it —
/// rows come out in SPATIAL-MERGE order (so the merger's 4-token grouping and
/// the pos-embed/rotary tables, which are built in that same order, line up),
/// and each row is `[C, T, ph, pw]`-flattened, which is the layout
/// `VisionTower.forward` un-flattens on the way in.
fn visionPatchRows(frames: mlx.mlx_array, grid: h3v.Grid, s: S) !mlx.mlx_array {
    const p: c_int = @intCast(h3v.PATCH);
    const m: c_int = @intCast(h3v.MERGE);
    const gh: c_int = @intCast(grid.gh);
    const gw: c_int = @intCast(grid.gw);
    const x9 = try reshape(frames, &[_]c_int{ 1, @intCast(h3v.TEMPORAL_PATCH), 3, @divExact(gh, m), m, p, @divExact(gw, m), m, p }, s);
    defer _ = mlx.mlx_array_free(x9);
    const tr = try transpose(x9, &[_]c_int{ 0, 3, 6, 4, 7, 2, 1, 5, 8 }, s);
    defer _ = mlx.mlx_array_free(tr);
    const flat = try reshape(tr, &[_]c_int{ gh * gw, @intCast(3 * h3v.TEMPORAL_PATCH * h3v.PATCH * h3v.PATCH) }, s);
    defer _ = mlx.mlx_array_free(flat);
    return contig(flat, s);
}

/// The reference's `pack_audio`: normalized audio latents `[1, C, ch, T]` ->
/// `[ch*T, C]` channel-major rows, i.e. the packed sequence's audio-stream
/// layout. Used for ref2va condition rows; `audioRowsToLatent` is its inverse
/// and unpacks the target stream on the way out.
pub fn audioLatentToRows(z: mlx.mlx_array, s: S) !mlx.mlx_array {
    const shp = mlx.getShape(z);
    const c = shp[1];
    const ch = shp[2];
    const t = shp[3];
    const z3 = try reshape(z, &[_]c_int{ c, ch, t }, s);
    defer _ = mlx.mlx_array_free(z3);
    const tr = try transpose(z3, &[_]c_int{ 1, 2, 0 }, s);
    defer _ = mlx.mlx_array_free(tr);
    const trc = try contig(tr, s);
    defer _ = mlx.mlx_array_free(trc);
    return reshape(trc, &[_]c_int{ ch * t, c }, s);
}

/// The reference's `unpack_audio`: `[ch*T, C]` rows -> `[1, C, ch, T]`.
pub fn audioRowsToLatent(rows: mlx.mlx_array, audio_t: u32, s: S) !mlx.mlx_array {
    const c = mlx.getShape(rows)[1];
    const t: c_int = @intCast(audio_t);
    const a3 = try reshape(rows, &[_]c_int{ 2, t, c }, s);
    defer _ = mlx.mlx_array_free(a3);
    const ap = try transpose(a3, &[_]c_int{ 2, 0, 1 }, s);
    defer _ = mlx.mlx_array_free(ap);
    const apc = try contig(ap, s);
    defer _ = mlx.mlx_array_free(apc);
    return reshape(apc, &[_]c_int{ 1, c, 2, t }, s);
}

/// A still image duplicated into the 2-frame temporal patch: `[1,3,1,H,W]` (the
/// keyframe shape) or `[3,H,W]` -> `[2,3,H,W]`.
pub fn stillAsFramePair(img: mlx.mlx_array, s: S) !mlx.mlx_array {
    const shp = mlx.getShape(img);
    const h = shp[shp.len - 2];
    const w = shp[shp.len - 1];
    const one = try reshape(img, &[_]c_int{ 1, 3, h, w }, s);
    defer _ = mlx.mlx_array_free(one);
    return concat(&[_]mlx.mlx_array{ one, one }, 0, s);
}

/// Standard rotate-half RoPE on [1, H, seq, head_dim].
fn ropeHalf(x: mlx.mlx_array, rope: RopeTables, head_dim: c_int, s: S) !mlx.mlx_array {
    const half = @divExact(head_dim, 2);
    const x1 = try sliceLast4(x, 0, half, s);
    defer _ = mlx.mlx_array_free(x1);
    const x2 = try sliceLast4(x, half, head_dim, s);
    defer _ = mlx.mlx_array_free(x2);
    const a1 = try mulA(x1, rope.cos, s);
    defer _ = mlx.mlx_array_free(a1);
    const a2 = try mulA(x2, rope.sin, s);
    defer _ = mlx.mlx_array_free(a2);
    var o1 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(o1);
    try mlx.check(mlx.mlx_subtract(&o1, a1, a2, s));
    const b1 = try mulA(x2, rope.cos, s);
    defer _ = mlx.mlx_array_free(b1);
    const b2 = try mulA(x1, rope.sin, s);
    defer _ = mlx.mlx_array_free(b2);
    const o2 = try addA(b1, b2, s);
    defer _ = mlx.mlx_array_free(o2);
    return concat(&[_]mlx.mlx_array{ o1, o2 }, 3, s);
}

/// Additive causal mask [1, 1, seq, seq]. Built with `where`, never by
/// multiplying an indicator by -inf: 0 * -inf is NaN, and a NaN mask passes a
/// parity loop that compares before it checks finiteness.
fn causalMask(seq: c_int, dt: mlx.mlx_dtype, s: S) !mlx.mlx_array {
    var rows = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(rows);
    try mlx.check(mlx.mlx_arange(&rows, 0, @floatFromInt(seq), 1, mlx.mlx_dtype.int32, s));
    const r = try reshape(rows, &[_]c_int{ seq, 1 }, s);
    defer _ = mlx.mlx_array_free(r);
    const c = try reshape(rows, &[_]c_int{ 1, seq }, s);
    defer _ = mlx.mlx_array_free(c);
    var keep = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(keep);
    try mlx.check(mlx.mlx_greater_equal(&keep, r, c, s));

    const zero = mlx.mlx_array_new_float(0);
    defer _ = mlx.mlx_array_free(zero);
    const neg = mlx.mlx_array_new_float(-std.math.inf(f32));
    defer _ = mlx.mlx_array_free(neg);
    var m = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(m);
    try mlx.check(mlx.mlx_where(&m, keep, zero, neg, s));
    const m4 = try reshape(m, &[_]c_int{ 1, 1, seq, seq }, s);
    defer _ = mlx.mlx_array_free(m4);
    return astype(m4, dt, s);
}

// ── Sampler ─────────────────────────────────────────────────────────────────

/// Flow-match sigma schedule on the VIDEO shift.
///
/// `sigmas[i] = shift*b / (1 + (shift-1)*b)` for `b = 1 - i/steps`, i.e. the
/// base grid pushed through the same time shift the DiT inverts internally.
/// Caller owns the returned slice (length steps+1, ending at 0).
pub fn sigmaSchedule(allocator: std.mem.Allocator, steps: u32, shift: f64) ![]f64 {
    const out = try allocator.alloc(f64, steps + 1);
    errdefer allocator.free(out);
    for (0..steps + 1) |i| {
        const base = 1.0 - @as(f64, @floatFromInt(i)) / @as(f64, @floatFromInt(steps));
        out[i] = timeShiftSigma(base, 1.0, shift);
    }
    return out;
}

/// A first/last-frame conditioning image for fl2va. `pixels` is
/// [1, 3, 1, H, W] in [-1, 1] at the TARGET canvas (the caller resizes:
/// stretch for `.first` — the geometry anchor — and center-cover for `.last`,
/// per the reference node). Caller owns the array.
pub const Keyframe = struct {
    anchor: KeyframeAnchor,
    pixels: mlx.mlx_array,
    /// The SAME image at the Qwen vision canvas (`h3v.fitCanvas` of the target),
    /// `[1, 3, 1, qh, qw]` in [-1, 1], for the `<Picture i>` block spliced into
    /// the conditioning. Optional only because the two canvases are identical
    /// whenever the target is a /32 multiple above the 3136-pixel floor, which
    /// every servable canvas is; below it they diverge and `pixels` cannot
    /// stand in, so `generate` rejects rather than patchifying the wrong shape.
    vision: ?mlx.mlx_array = null,
};

/// One decoded ref2va reference, paired with the resolution the CALLER made.
///
/// The caller resolves BEFORE it decodes, because a reference's canvas comes
/// out of `resolveRefs` and the server has no image resampler — it decodes AT a
/// size. So `generate` consumes that decision rather than re-deriving it, which
/// keeps ordinals and canvases decided in exactly one place.
pub const RefMedia = struct {
    ref: ResolvedRef,
    /// image `[1,3,1,H,W]` / video `[1,3,T,H,W]` at `ref.canvas`, in [-1, 1].
    /// Null for a standalone audio.
    pixels: ?mlx.mlx_array = null,
    /// What the vision tower sees, at the QWEN canvas (`h3v.fitCanvas` of
    /// `ref.canvas`): an image is `[1,3,1,qh,qw]`, a video is `[n,3,qh,qw]`
    /// with the `qwenSampledFrames(ref.frames)` frames sampled at
    /// `qwenFrameStride()`. Null for a standalone audio.
    vision: ?mlx.mlx_array = null,
    /// 32 kHz stereo `[2, L]`: a standalone audio, or a video's soundtrack.
    waveform: ?mlx.mlx_array = null,

    pub fn deinit(self: *RefMedia) void {
        if (self.pixels) |x| _ = mlx.mlx_array_free(x);
        if (self.vision) |x| _ = mlx.mlx_array_free(x);
        if (self.waveform) |x| _ = mlx.mlx_array_free(x);
        self.* = undefined;
    }
};

pub const GenRequest = struct {
    prompt: []const u8,
    width: u32 = 256,
    height: u32 = 256,
    /// Requested source frames; snapped UP to the 17k+5 ladder.
    frames: u32 = 56,
    steps: u32 = 30,
    seed: u64 = 0,
    shift_video: f64 = SIGMA_SHIFT_VIDEO,
    shift_audio: f64 = SIGMA_SHIFT_AUDIO,
    /// Fast recipe switch: null/true = ON (the default), false = full-quality
    /// per-step compute (every forward, dense attention branch every step).
    fast: ?bool = null,
    /// Turbo distillation LoRA (larryvrh/MiniMax-H3-Turbo-Lora): 4-8 step
    /// sampling instead of ~30. Requires `paths.turbo_lora`; forces the fast
    /// recipe OFF (its slow-drift premise is false at giant steps) and switches
    /// the audio stream to EXACT Δσ_audio integration — see `audioStepFactor`.
    /// Loaded as the FIRST file of the same stack the user's adapters ride —
    /// it is a LoRA, so it gets no private code path.
    turbo: bool = false,
    /// Style LoRAs stacked on the DiT: absolute `.safetensors` paths and their
    /// strengths (parallel arrays; a missing scale is 1.0 at the caller). They
    /// sum with each other and with Turbo, never merge — order is irrelevant
    /// to the result. Loaded and freed with the model, since H3 stages its
    /// weights per generation and keeps nothing resident between requests.
    lora_paths: []const []const u8 = &.{},
    lora_scales: []const f32 = &.{},
    /// Chained-window long clips: N back-to-back `frames`-frame windows, each
    /// conditioned on its predecessor's last decoded frame through the
    /// ordinary fl2va path. `frames` is the PER-WINDOW count; the clip
    /// delivers `chainDeliveredFrames(chain_windows, frames)` frames (the
    /// duplicate join frames are dropped) with a one-frame equal-power audio
    /// cross-fade at each seam. Caps the packed sequence — and so the
    /// attention S² term and the broadcast-cache footprint — at the WINDOW
    /// size regardless of clip length. FL2VA only (a reference has no
    /// keyframe row to chain through).
    chain_windows: u32 = 1,
    /// fl2va keyframes (0-2: first and/or last), conditioned through their VAE
    /// latents as cond rows.
    ///
    /// The reference ALSO splices each into the Qwen encoding as a
    /// `<Picture i>: <vision block>`. That path is built and parity-tested but
    /// DEFAULT-OFF here: it measured worse on this checkpoint (see the A/B
    /// table in `generate`). `MINIMAX_H3_VISION_BLOCKS=1` turns it on.
    keyframes: []const Keyframe = &.{},
    /// ref2va references in `resolveRefs` order, already decoded at the
    /// canvases it resolved. Unlike the fl2va keyframes these DO carry vision
    /// blocks: a reference has no cond row of its own competing with the tower,
    /// and the prompt addresses it as `<Picture i>` / `<Video k>` / `<Audio j>`.
    refs: []const RefMedia = &.{},
};

pub const SpeedConfig = struct { step_cache: f64, bcast_k: u32 };

/// The 2026-08-03 eyeball verdict on the same-seed capstone pair made the
/// fast recipe (velocity cache 0.05 + attention broadcast k=2 — 2.83x at the
/// trained config) DEFAULT-ON, with `"fast": false` on the request as the
/// off switch for final renders ("non fast just a smidge better"). Env vars
/// stay the STRONGEST knob — set means set, including "0" — so every A/B
/// harness keeps its arms.
///
/// Turbo and the fast recipe are ALTERNATIVES, not a stack: at 4-8 steps the
/// velocity cache's slow-drift premise is false (every step is a giant leap)
/// and the broadcast gates cover most of the schedule anyway, so `turbo`
/// forces both off regardless of `fast` — env still wins for A/B harnesses.
pub fn resolveSpeed(fast: ?bool, turbo: bool, env_sc: ?[]const u8, env_bk: ?[]const u8) SpeedConfig {
    const want_fast = !turbo and (fast orelse true);
    var out = SpeedConfig{
        .step_cache = if (want_fast) 0.05 else 0,
        .bcast_k = if (want_fast) 2 else 0,
    };
    if (env_sc) |raw| out.step_cache = std.fmt.parseFloat(f64, raw) catch out.step_cache;
    if (env_bk) |raw| out.bcast_k = std.fmt.parseInt(u32, raw, 10) catch out.bcast_k;
    return out;
}

/// What the audio latent is advanced by this step, per unit of the
/// slope-scaled velocity the forward returns (`Output.audio` carries
/// d(sigma_a)/d(sigma_v) at the CURRENT sigma).
///
/// Default path: `Δσ_video` — first-order in the audio clock, byte-identical
/// to what every ≥30-step render was validated with, where the error is
/// second-order and negligible.
///
/// Turbo path: the EXACT mapped delta `(σa(next) − σa(cur)) / slope(cur)` —
/// the reference node's own arithmetic, and the entire reason its custom
/// sampler exists: at 4 steps the last video leg (0.8 → 0 at shift 12/3) is
/// 0.5 in the audio clock but 1.25 first-order, a 2.5x over-step that is the
/// "audio blown out at low steps" failure its README describes.
pub fn audioStepFactor(turbo: bool, sigma_cur: f64, sigma_next: f64, shift_v: f64, shift_a: f64) f64 {
    if (!turbo) return sigma_next - sigma_cur;
    const sa_c = timeShiftSigma(sigma_cur, shift_v, shift_a);
    const sa_n = timeShiftSigma(sigma_next, shift_v, shift_a);
    return (sa_n - sa_c) / timeShiftSlope(@max(sigma_cur, 1e-6), shift_v, shift_a);
}

pub const GenPaths = struct {
    /// Directory holding tokenizer.json.
    tokenizer_dir: []const u8,
    text_encoder: []const u8,
    dit: []const u8,
    vae: []const u8,
    /// Audio VAE. Optional: absent means the clip is silent rather than
    /// failing, since the video stream is complete without it.
    audio_vae: ?[]const u8 = null,
    /// Turbo LoRA file (`turbo_lora.safetensors` in the pack dir). Optional:
    /// absent just means `turbo` requests fail with a named error — the
    /// handler 400s before generate() ever runs.
    turbo_lora: ?[]const u8 = null,
};

pub const GenResult = struct {
    /// [1, 3, frames, H, W] in [-1, 1].
    pixels: mlx.mlx_array,
    /// Final audio latent [1, 32, 2, audio_t], still in latent space.
    audio_latent: mlx.mlx_array,
    /// Decoded stereo waveform [2, L] at 32 kHz, when an audio VAE was given.
    audio: ?mlx.mlx_array = null,
    frame_count: u32,
    width: u32,
    height: u32,

    pub fn deinit(self: *GenResult) void {
        _ = mlx.mlx_array_free(self.pixels);
        _ = mlx.mlx_array_free(self.audio_latent);
        if (self.audio) |a| _ = mlx.mlx_array_free(a);
    }
};

/// Monotonic lap clock over std.Io (this Zig nightly has no std.time.Timer).
const LapClock = struct {
    io: std.Io,
    start: std.Io.Timestamp,
    mark_ns: u64 = 0,
    fn init(io: std.Io) LapClock {
        return .{ .io = io, .start = std.Io.Timestamp.now(io, .boot) };
    }
    /// ms since the previous lap (or init).
    fn lapMs(self: *LapClock) u64 {
        const cum: u64 = @intCast(self.start.untilNow(self.io, .boot).nanoseconds);
        const d = cum - self.mark_ns;
        self.mark_ns = cum;
        return d / 1_000_000;
    }
};

fn randomNormal(shape: []const c_int, seed: u64, dt: mlx.mlx_dtype, s: S) !mlx.mlx_array {
    var key = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(key);
    try mlx.check(mlx.mlx_random_key(&key, seed));
    var o = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(o);
    try mlx.check(mlx.mlx_random_normal(&o, shape.ptr, shape.len, mlx.mlx_dtype.float32, 0.0, 1.0, key, s));
    return astype(o, dt, s);
}

/// [1, C, T, H, W] -> [T*(H/2)*(W/2), C*1*2*2] rows, (t,h,w)-major, each row
/// [c, pt, ph, pw]-flattened — the reference's `patchify_video` einsum
/// (`nctrhpwq -> nthwcrpq`). Shared by the target latents and the fl2va
/// keyframe condition rows, so both sides patchify identically by construction.
pub fn patchifyVideo(x: mlx.mlx_array, s: S) !mlx.mlx_array {
    const shp = mlx.getShape(x);
    const c = shp[1];
    const t = shp[2];
    const h2 = @divExact(shp[3], @as(c_int, @intCast(PATCH_H)));
    const w2 = @divExact(shp[4], @as(c_int, @intCast(PATCH_W)));
    const x8 = try reshape(x, &[_]c_int{ 1, c, t, 1, h2, @intCast(PATCH_H), w2, @intCast(PATCH_W) }, s);
    defer _ = mlx.mlx_array_free(x8);
    // n c t r h p w q -> n t h w c r p q
    const tr = try transpose(x8, &[_]c_int{ 0, 2, 4, 6, 1, 3, 5, 7 }, s);
    defer _ = mlx.mlx_array_free(tr);
    const trc = try contig(tr, s);
    defer _ = mlx.mlx_array_free(trc);
    return reshape(trc, &[_]c_int{ t * h2 * w2, c * @as(c_int, @intCast(PATCH_H * PATCH_W)) }, s);
}

/// Inverse of `patchifyVideo`: `[T*(H/2)*(W/2), C*2*2]` → `[1, C, T, H, W]`.
fn unpatchifyVideoRows(video_x: mlx.mlx_array, latent_t: u32, lat_h: u32, lat_w: u32, s: S) !mlx.mlx_array {
    const lh2: c_int = @intCast(lat_h / PATCH_H);
    const lw2: c_int = @intCast(lat_w / PATCH_W);
    const c24: c_int = 24;
    const v6 = try reshape(video_x, &[_]c_int{ @intCast(latent_t), lh2, lw2, c24, @intCast(PATCH_H), @intCast(PATCH_W) }, s);
    defer _ = mlx.mlx_array_free(v6);
    const vp = try transpose(v6, &[_]c_int{ 3, 0, 1, 4, 2, 5 }, s);
    defer _ = mlx.mlx_array_free(vp);
    const vpc = try contig(vp, s);
    defer _ = mlx.mlx_array_free(vpc);
    return reshape(vpc, &[_]c_int{ 1, c24, @intCast(latent_t), @intCast(lat_h), @intCast(lat_w) }, s);
}

fn copyArrayF32(allocator: std.mem.Allocator, x: mlx.mlx_array, s: S) ![]f32 {
    const f = try astype(x, mlx.mlx_dtype.float32, s);
    defer _ = mlx.mlx_array_free(f);
    const c = try contig(f, s);
    defer _ = mlx.mlx_array_free(c);
    try mlx.check(mlx.mlx_array_eval(c));
    const n: usize = @intCast(mlx.mlx_array_size(c));
    const raw = mlx.mlx_array_data_float32(c) orelse return error.NoData;
    return allocator.dupe(f32, raw[0..n]);
}

fn sliceLatentT(x: mlx.mlx_array, t: c_int, s: S) !mlx.mlx_array {
    const shp = mlx.getShape(x);
    const start = [_]c_int{ 0, 0, t, 0, 0 };
    const stop = [_]c_int{ shp[0], shp[1], t + 1, shp[3], shp[4] };
    const step = [_]c_int{ 1, 1, 1, 1, 1 };
    var o = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(o);
    try mlx.check(mlx.mlx_slice(&o, x, &start, 5, &stop, 5, &step, 5, s));
    return contig(o, s);
}

/// Predicted clean video x0 = x - sigma * v (rectified-flow, sigma 1→0).
/// Failures fall back to a preview-less progress event so a bad JPEG never
/// kills a 50-minute job.
fn tryEmitH3Preview(
    p: gen_sse.Progress,
    allocator: std.mem.Allocator,
    stage: []const u8,
    step: u32,
    total: u32,
    video_x: mlx.mlx_array,
    velocity: mlx.mlx_array,
    sigma: f64,
    latent_t: u32,
    lat_h: u32,
    lat_w: u32,
    first_frame: bool,
    s: S,
) void {
    if (!p.wantsPreview()) {
        p.emit(stage, step, total);
        return;
    }
    const frame = renderH3Preview(allocator, p.preview_opts, video_x, velocity, sigma, latent_t, lat_h, lat_w, first_frame, s) catch {
        p.emit(stage, step, total);
        return;
    };
    defer allocator.free(frame.jpeg);
    p.emitPreview(stage, step, total, frame);
}

fn renderH3Preview(
    allocator: std.mem.Allocator,
    opts: @import("preview.zig").Opts,
    video_x: mlx.mlx_array,
    velocity: mlx.mlx_array,
    sigma: f64,
    latent_t: u32,
    lat_h: u32,
    lat_w: u32,
    first_frame: bool,
    s: S,
) !@import("preview.zig").Encoded {
    const preview_mod = @import("preview.zig");
    const sv = try scalarLike(@floatCast(sigma), velocity, s);
    defer _ = mlx.mlx_array_free(sv);
    const scaled = try mulA(velocity, sv, s);
    defer _ = mlx.mlx_array_free(scaled);
    const x0 = try subA(video_x, scaled, s);
    defer _ = mlx.mlx_array_free(x0);
    const vol = try unpatchifyVideoRows(x0, latent_t, lat_h, lat_w, s);
    defer _ = mlx.mlx_array_free(vol);

    var idx_buf: [preview_mod.Opts.max_frames]u32 = undefined;
    const idx = preview_mod.temporalIndices(&idx_buf, latent_t, opts.frames, first_frame);
    const n: u32 = @intCast(idx.len);
    const hw: usize = @as(usize, lat_h) * @as(usize, lat_w);
    const c: usize = preview_mod.minimax_h3.channels();
    const packed_lat = try allocator.alloc(f32, c * @as(usize, n) * hw);
    defer allocator.free(packed_lat);
    for (idx, 0..) |ti, fi| {
        const sl = try sliceLatentT(vol, @intCast(ti), s);
        defer _ = mlx.mlx_array_free(sl);
        const cpu = try copyArrayF32(allocator, sl, s);
        defer allocator.free(cpu);
        // sl is [1,24,1,H,W] → C*H*W channel-major.
        if (cpu.len < c * hw) return error.BadLatentShape;
        for (0..c) |ci| {
            @memcpy(packed_lat[ci * @as(usize, n) * hw + fi * hw ..][0..hw], cpu[ci * hw ..][0..hw]);
        }
    }
    return preview_mod.jpegFromLatent(allocator, preview_mod.minimax_h3, packed_lat, n, lat_h, lat_w, .{
        .enabled = true,
        .frames = n,
        .max_side = opts.max_side,
    }, false);
}

/// Text-to-audio-video. Dispatches: `chain_windows > 1` runs N single-window
/// generations chained by fl2va keyframes (`generateChain`); everything else
/// is one window (`generateOne`).
pub fn generate(
    allocator: std.mem.Allocator,
    io: std.Io,
    paths: GenPaths,
    req: GenRequest,
    progress: ?gen_sse.Progress,
    s: S,
) !GenResult {
    if (req.chain_windows > 1) return generateChain(allocator, io, paths, req, progress, s);
    return generateOne(allocator, io, paths, req, progress, s);
}

/// One window, with STAGED residency: the 50-layer text encoder (~48 GB bf16)
/// and the DiT (~62 GB bf16) cannot both be resident on a 128 GB machine, so
/// the encoder is loaded, run, and freed before the DiT loads.
fn generateOne(
    allocator: std.mem.Allocator,
    io: std.Io,
    paths: GenPaths,
    req: GenRequest,
    progress: ?gen_sse.Progress,
    s: S,
) !GenResult {
    const vae_mod = @import("minimax_h3_vae.zig");
    const dt = mlx.mlx_dtype.bfloat16;

    const shape = temporalShape(req.frames);
    const lat_h = req.height / vae_mod.VAE_RATIO;
    const lat_w = req.width / vae_mod.VAE_RATIO;
    log.info("[minimax-h3] {d}x{d} {d} frames ({d} latent, {d} audio), {d} steps\n", .{
        req.width, req.height, shape.frame_count, shape.latent_t, shape.audio_t, req.steps,
    });

    var phase_timer = LapClock.init(io);

    // H3's DiT runs EVERY forward at prefill width (~9K rows at 480p), where
    // the wide-M dequant+GEMM route measured −13%/step on the 8-bit pack
    // (2/2 adjacent pairs, 2026-08-03). Default it ON for THIS backend only —
    // MageFlow keeps its own default until it has its own A/B — and let the
    // env always win (MLX_SERVE_MF_DQ_GEMM=0 kills, =N sets the floor).
    const dq_override_prev = mage_flow.mf_dq_gemm_override;
    if (std.c.getenv("MLX_SERVE_MF_DQ_GEMM") == null)
        mage_flow.mf_dq_gemm_override = @as(?usize, 2048);
    defer mage_flow.mf_dq_gemm_override = dq_override_prev;

    // ── 1. tokenize (raw ids, NO special tokens and no chat template) ──
    const tok_mod = @import("tokenizer.zig");
    var tok = try tok_mod.loadTokenizerAny(io, allocator, paths.tokenizer_dir);
    defer tok.deinit();
    const ids_u32 = try tok.encode(allocator, req.prompt);
    defer allocator.free(ids_u32);
    const ids = try allocator.alloc(i32, ids_u32.len);
    defer allocator.free(ids);
    for (ids_u32, 0..) |v, i| ids[i] = @intCast(v);
    log.info("[minimax-h3] prompt -> {d} tokens ({d} ms)\n", .{ ids.len, phase_timer.lapMs() });

    // ── 1.5 keyframes + ref2va references -> condition rows (both encoders
    //       loaded and FREED before the text encoder, keeping the staged
    //       residency peak at max(TE, DiT) + VAEs rather than the sum) ──
    //
    // Both cond streams are built in SEGMENT order, because that is the order
    // `PackedLayout` fills its `img_update` / `audio_update` false rows in and
    // the forward drops the concatenation straight into them: keyframe conds,
    // then each reference block, then the target. A cond row assembled in
    // REQUEST order instead lands on the wrong reference and the model
    // conditions on a smear with nothing to report it.
    var cond_rows: ?mlx.mlx_array = null;
    defer if (cond_rows) |cr| {
        _ = mlx.mlx_array_free(cr);
    };
    var audio_cond_rows: ?mlx.mlx_array = null;
    defer if (audio_cond_rows) |cr| {
        _ = mlx.mlx_array_free(cr);
    };
    var ref_blocks = try allocator.alloc(RefBlock, req.refs.len);
    defer allocator.free(ref_blocks);
    for (req.refs, 0..) |m, i| ref_blocks[i] = refBlockFor(m.ref);

    var anchors_buf: [2]KeyframeAnchor = undefined;
    var anchors: []const KeyframeAnchor = &.{};
    if (req.keyframes.len > 0 or req.refs.len > 0) {
        if (req.keyframes.len > 2) return error.TooManyKeyframes;
        var rows_list: std.ArrayList(mlx.mlx_array) = .empty;
        defer {
            for (rows_list.items) |r| _ = mlx.mlx_array_free(r);
            rows_list.deinit(allocator);
        }
        var arows_list: std.ArrayList(mlx.mlx_array) = .empty;
        defer {
            for (arows_list.items) |r| _ = mlx.mlx_array_free(r);
            arows_list.deinit(allocator);
        }

        var needs_visual = req.keyframes.len > 0;
        var needs_audio = false;
        for (req.refs) |m| {
            if (m.ref.kind != .audio) needs_visual = true;
            if (m.ref.audio_t > 0) needs_audio = true;
        }

        if (needs_visual) {
            var vw0 = try model_mod.loadWeightsSingleFile(allocator, paths.vae);
            defer vw0.deinit();
            var enc = try vae_mod.Encoder.load(allocator, &vw0, s);
            defer enc.deinit();
            for (req.keyframes, 0..) |kf, ki| {
                anchors_buf[ki] = kf.anchor;
                const lat = try enc.encodeImage(kf.pixels, allocator, s);
                defer _ = mlx.mlx_array_free(lat);
                try rows_list.append(allocator, try patchifyVideo(lat, s));
            }
            anchors = anchors_buf[0..req.keyframes.len];
            for (req.refs) |m| {
                if (m.ref.kind == .audio) continue;
                const px = m.pixels orelse return error.RefMissingPixels;
                // encodeImage IS encodeVideo at T == 1; naming the two apart
                // keeps the call site readable, not the behaviour different.
                const lat = try enc.encodeVideo(px, allocator, s);
                defer _ = mlx.mlx_array_free(lat);
                const got_t: u32 = @intCast(mlx.getShape(lat)[2]);
                const want_t: u32 = if (m.ref.kind == .image) 1 else m.ref.latent_t;
                // The layout budgeted rows from `latent_t`; a VAE that returned
                // a different depth would silently shift every later segment.
                if (got_t != want_t) return error.RefLatentDepthMismatch;
                try rows_list.append(allocator, try patchifyVideo(lat, s));
            }
        }
        if (needs_audio) {
            const apath = paths.audio_vae orelse return error.RefAudioNeedsAudioVae;
            var aw = try model_mod.loadWeightsSingleFile(allocator, apath);
            defer aw.deinit();
            for (req.refs) |m| {
                if (m.ref.audio_t == 0) continue;
                const wav = m.waveform orelse return error.RefMissingAudio;
                const z = try audio_mod.encode(allocator, &aw, wav, s);
                defer _ = mlx.mlx_array_free(z);
                if (@as(u32, @intCast(mlx.getShape(z)[3])) != m.ref.audio_t)
                    return error.RefAudioLengthMismatch;
                try arows_list.append(allocator, try audioLatentToRows(z, s));
            }
            // AUDIO_COND_TIMESTEP is 1.0 and the reference only augments below
            // 1.0, so the audio conditions ride in CLEAN — no noise is drawn.
            audio_cond_rows = if (arows_list.items.len == 1)
                try contig(arows_list.items[0], s)
            else
                try concat(arows_list.items, 0, s);
            try mlx.check(mlx.mlx_array_eval(audio_cond_rows.?));
        }
        if (rows_list.items.len > 0) {
            const cat = if (rows_list.items.len == 1) try contig(rows_list.items[0], s) else try concat(rows_list.items, 0, s);
            defer _ = mlx.mlx_array_free(cat);
            // Condition noise augmentation: r = aug*r + (1-aug)*noise, aug
            // 0.999, CONSTANT for the whole generation (the reference restarts
            // the same RNG stream every forward, which is the same thing). mlx
            // RNG, not torch's — seeds are not portable across implementations,
            // the same class as the initial latents.
            const noise = try randomNormal(mlx.getShape(cat), req.seed, mlx.mlx_dtype.float32, s);
            defer _ = mlx.mlx_array_free(noise);
            const aug = try scalarLike(@floatCast(VISUAL_COND_TIMESTEP), cat, s);
            defer _ = mlx.mlx_array_free(aug);
            const one_m = try scalarLike(@floatCast(1.0 - VISUAL_COND_TIMESTEP), cat, s);
            defer _ = mlx.mlx_array_free(one_m);
            const ra = try mulA(cat, aug, s);
            defer _ = mlx.mlx_array_free(ra);
            const na2 = try mulA(noise, one_m, s);
            defer _ = mlx.mlx_array_free(na2);
            cond_rows = try addA(ra, na2, s);
            try mlx.check(mlx.mlx_array_eval(cond_rows.?));
        }
        _ = mlx.mlx_clear_cache();
        log.info("[minimax-h3] {d} keyframe(s) + {d} reference(s) encoded -> {d} visual / {d} audio cond rows ({d} ms, encoders released)\n", .{
            req.keyframes.len,
            req.refs.len,
            if (cond_rows) |cr| mlx.getShape(cr)[0] else 0,
            if (audio_cond_rows) |cr| mlx.getShape(cr)[0] else 0,
            phase_timer.lapMs(),
        });
    }

    if (progress) |p| p.emit("Encoding prompt", 0, req.steps);

    // ── 2. presentation: "<Picture i>: " + vision block per keyframe, then the
    //       prompt. Frame pairs are built here (outside the encoder) so the
    //       weights map below can be scoped to the encode itself.
    var present: std.ArrayList(PresentItem) = .empty;
    defer present.deinit(allocator);
    var label_ids: std.ArrayList([]i32) = .empty;
    var pairs: std.ArrayList(mlx.mlx_array) = .empty;
    defer {
        for (label_ids.items) |li| allocator.free(li);
        label_ids.deinit(allocator);
        for (pairs.items) |p| _ = mlx.mlx_array_free(p);
        pairs.deinit(allocator);
    }
    // Encode one presentation label and append it as a text item. The label
    // text is the CONTRACT with the checkpoint — the prompt refers to
    // `<Picture 2>` and the conditioning must carry the matching marker.
    const addLabel = struct {
        fn f(
            a: std.mem.Allocator,
            t: *tok_mod.Tokenizer,
            items: *std.ArrayList(PresentItem),
            owned: *std.ArrayList([]i32),
            text: []const u8,
        ) !void {
            const u = try t.encode(a, text);
            defer a.free(u);
            const buf = try a.alloc(i32, u.len);
            errdefer a.free(buf);
            for (u, 0..) |v, i| buf[i] = @intCast(v);
            try owned.append(a, buf);
            try items.append(a, .{ .text = buf });
        }
    }.f;
    // Splicing keyframes into the Qwen encoding is the REFERENCE presentation
    // (`<Picture i>: <vision block>`), and it is DEFAULT-OFF for fl2va because
    // it measured WORSE on this checkpoint. Same-seed 256px A/B, frame-0
    // left/right means against a 20/235 split keyframe:
    //
    //   vision blocks OFF                 16.1 / 231.4   delta +215  <- shipped
    //   ON, plain 1-D rope                43.0 / 119.5   delta  +77
    //   ON, mRoPE, no DeepStack           48.5 / 105.2   delta  +57
    //   ON, mRoPE + DeepStack             150.6 / 53.0   delta  -98 (INVERTED)
    //
    // The port is not the problem: the tower reproduces the reference in both
    // direction AND magnitude (cos 0.999987, rms_ratio 1.0000 — see the vision
    // tower parity test, which asserts the ratio precisely because a cosine
    // cannot see a 40x scale error). What the numbers say is that on the FL2VA
    // checkpoint the VAE cond rows already carry the keyframe, and adding a
    // second conditioning path 41x the norm of a token embedding competes with
    // them rather than reinforcing them.
    //
    // ref2va is different by construction — a reference image has no keyframe
    // cond row to compete with, and the prompt ADDRESSES it as `<Picture i>`,
    // so the tower is the whole mechanism there and stays on.
    // `MINIMAX_H3_VISION_BLOCKS=1` re-enables it for fl2va A/Bs.
    const vision_blocks_on = blk: {
        const raw = std.c.getenv("MINIMAX_H3_VISION_BLOCKS") orelse break :blk false;
        break :blk !std.mem.eql(u8, std.mem.sliceTo(raw, 0), "0");
    };
    var label_buf: [32]u8 = undefined;
    for (req.keyframes, 0..) |kf, ki| {
        if (!vision_blocks_on) break;
        const src = kf.vision orelse kf.pixels;
        const shp = mlx.getShape(src);
        const ph: u32 = @intCast(shp[shp.len - 2]);
        const pw: u32 = @intCast(shp[shp.len - 1]);
        const fit = h3v.fitCanvas(ph, pw);
        // A canvas the vision policy would resize cannot be patchified as-is:
        // the grid and the pixels would describe different images.
        if (fit.h != ph or fit.w != pw) return error.KeyframeCanvasNotVisionReady;
        try addLabel(allocator, &tok, &present, &label_ids, try h3v.labelFor(&label_buf, .image, @intCast(ki + 1)));
        try pairs.append(allocator, try stillAsFramePair(src, s));
        try present.append(allocator, .{ .vision = .{ .frames = pairs.items[pairs.items.len - 1], .grid = h3v.gridFor(ph, pw) } });
    }

    // ref2va references, in `resolveRefs` order. Unlike the keyframes above the
    // vision blocks are unconditional here — see the comment on that switch.
    for (req.refs) |m| {
        switch (m.ref.kind) {
            .audio => try addLabel(allocator, &tok, &present, &label_ids, try h3v.labelFor(&label_buf, .audio, m.ref.ordinal)),
            .image => {
                const src = m.vision orelse return error.RefMissingVision;
                const shp = mlx.getShape(src);
                const ph: u32 = @intCast(shp[shp.len - 2]);
                const pw: u32 = @intCast(shp[shp.len - 1]);
                const fit = h3v.fitCanvas(ph, pw);
                if (fit.h != ph or fit.w != pw) return error.RefCanvasNotVisionReady;
                try addLabel(allocator, &tok, &present, &label_ids, try h3v.labelFor(&label_buf, .image, m.ref.ordinal));
                try pairs.append(allocator, try stillAsFramePair(src, s));
                try present.append(allocator, .{ .vision = .{ .frames = pairs.items[pairs.items.len - 1], .grid = h3v.gridFor(ph, pw) } });
            },
            .video => {
                // A soundtrack is LABELLED like a standalone audio and emitted
                // BEFORE its video's own label — it consumes an `<Audio j>`
                // ordinal, which is why the two counters interleave.
                if (m.ref.audio_t > 0)
                    try addLabel(allocator, &tok, &present, &label_ids, try h3v.labelFor(&label_buf, .audio, m.ref.audio_ordinal));
                try addLabel(allocator, &tok, &present, &label_ids, try h3v.labelFor(&label_buf, .video, m.ref.ordinal));

                const src = m.vision orelse return error.RefMissingVision;
                const vshp = mlx.getShape(src);
                const n: u32 = @intCast(vshp[0]);
                const ph: u32 = @intCast(vshp[vshp.len - 2]);
                const pw: u32 = @intCast(vshp[vshp.len - 1]);
                const fit = h3v.fitCanvas(ph, pw);
                if (fit.h != ph or fit.w != pw) return error.RefCanvasNotVisionReady;
                if (n != qwenSampledFrames(m.ref.frames)) return error.RefVisionFrameCountMismatch;
                const grid = h3v.gridFor(ph, pw);
                // Qwen sees the clip at 2 fps in 2-FRAME blocks, each announced
                // by the midpoint of its own two timestamps. An odd sampled
                // count repeat-pads its last frame (and its timestamp with it),
                // so the final block's midpoint is that frame's own time.
                var i: u32 = 0;
                while (i < n) : (i += 2) {
                    const t0: f64 = @as(f64, @floatFromInt(i)) / 2.0;
                    const t1: f64 = @as(f64, @floatFromInt(@min(i + 1, n - 1))) / 2.0;
                    try addLabel(allocator, &tok, &present, &label_ids, try h3v.timestampLabel(&label_buf, (t0 + t1) / 2.0));
                    const lo: c_int = @intCast(i);
                    const pair = if (i + 1 < n)
                        try sliceAxis0(src, lo, lo + 2, s)
                    else blk: {
                        const last = try sliceAxis0(src, lo, lo + 1, s);
                        defer _ = mlx.mlx_array_free(last);
                        break :blk try concat(&[_]mlx.mlx_array{ last, last }, 0, s);
                    };
                    try pairs.append(allocator, pair);
                    try present.append(allocator, .{ .vision = .{ .frames = pair, .grid = grid } });
                }
            },
        }
    }
    try present.append(allocator, .{ .text = ids });

    // ── 3. text encoder, then FREE it before the DiT loads ──
    var te_active: usize = 0;
    var enc: EncodedPrompt = blk: {
        var tw = try model_mod.loadWeightsSingleFile(allocator, paths.text_encoder);
        defer tw.deinit();
        var te = try TextEncoder.load(allocator, &tw, .{}, dt, s);
        defer te.deinit();
        // The tower is 1.2 GB and only the presentation knows whether anything
        // needs it — a keyframe with vision blocks off, or an audio-only ref
        // set, does not.
        for (present.items) |it| if (it == .vision) {
            try te.loadVision(&tw, s);
            break;
        };
        var e = try te.encodeItems(allocator, present.items, s);
        errdefer e.deinit();
        try mlx.check(mlx.mlx_array_eval(e.hidden));
        // Read while the encoder is still resident: this stage is one term of
        // `gen.h3PeakBytes`, and a bill nobody can check against the running
        // process is how the DiT term stayed 12 GiB wrong for months.
        _ = mlx.mlx_get_active_memory(&te_active);
        break :blk e;
    };
    defer enc.deinit();
    const text_hidden = enc.hidden;
    _ = mlx.mlx_clear_cache();
    const te_len: u32 = @intCast(mlx.getShape(text_hidden)[0]);
    const te_ms = phase_timer.lapMs();
    log.info("[minimax-h3] text encoded ({d} rows, {d} vision), encoder resident {d:.2} GB, released ({d} ms load+encode)\n", .{
        te_len,
        te_len - @as(u32, @intCast(ids.len)),
        @as(f64, @floatFromInt(te_active)) / (1024.0 * 1024.0 * 1024.0),
        te_ms,
    });

    // ── 4. DiT sampling ──
    var layout = try PackedLayout.initFull(allocator, te_len, shape.latent_t, lat_h, lat_w, shape.audio_t, anchors, shape.frame_count, ref_blocks);
    defer layout.deinit();
    // BORROWED from `enc`, which outlives the layout. Empty for a pure t2va
    // prompt; non-empty makes the text segment split into modality runs.
    layout.text_tags = enc.tags;

    const n_video_rows: c_int = @intCast(shape.latent_t * (lat_h / PATCH_H) * (lat_w / PATCH_W));
    const n_audio_rows: c_int = @intCast(shape.audio_t * 2);

    const vpatch: c_int = @intCast((Config{}).videoPatchDim());
    var video_x = try randomNormal(&[_]c_int{ n_video_rows, vpatch }, req.seed, mlx.mlx_dtype.float32, s);
    defer _ = mlx.mlx_array_free(video_x);
    var audio_x = try randomNormal(&[_]c_int{ n_audio_rows, 32 }, req.seed +% 1, mlx.mlx_dtype.float32, s);
    defer _ = mlx.mlx_array_free(audio_x);

    const sigmas = try sigmaSchedule(allocator, req.steps, req.shift_video);
    defer allocator.free(sigmas);

    // Profiling arms: never set by any server path; the live-test harness and
    // profile drivers own the env. A non-empty junk value is LOUDLY off.
    const abl_raw = envStr("MINIMAX_H3_ABLATE");
    const abl_mode = ablateModeFrom(abl_raw);
    if (abl_raw != null and std.meta.activeTag(abl_mode) == .off)
        log.warn("[minimax-h3] MINIMAX_H3_ABLATE='{s}' not recognized; profiling arms OFF\n", .{abl_raw.?});

    {
        // Adapters are loaded BEFORE the DiT and outlive it (declared first ⇒
        // its `defer` runs last), because every attached `Ref` points into
        // this stack. Turbo is file 0 when asked for, then the user's, so a
        // style LoRA and the distillation sum on the same linears.
        var stack: lora_mod.Stack = .{ .allocator = allocator };
        defer stack.deinit();
        if (req.turbo) {
            const tp = paths.turbo_lora orelse return error.TurboLoraMissing;
            stack.files[stack.count] = try lora_mod.loadFile(allocator, tp, .minimax_h3);
            stack.paths[stack.count] = try allocator.dupe(u8, tp);
            stack.scales[stack.count] = 1.0; // the file's alpha == rank
            stack.count += 1;
        }
        if (req.lora_paths.len + stack.count > lora_mod.MAX_LORAS) return error.TooManyLoras;
        for (req.lora_paths, 0..) |p, i| {
            stack.files[stack.count] = try lora_mod.loadFile(allocator, p, .minimax_h3);
            stack.paths[stack.count] = try allocator.dupe(u8, p);
            stack.scales[stack.count] = if (i < req.lora_scales.len) req.lora_scales[i] else 1.0;
            stack.count += 1;
        }

        // The weights MAP must not outlive Model.load: it holds +1 refs on
        // every raw file-backed array, so anything the model later FREES (the
        // 13 GB of AdaLN under precompute) would stay resident until scope
        // end. Lazy graphs keep their inputs alive internally, so dropping
        // the map right away is safe — caught live by the `dit resident` log
        // reading 33.4 GB where ~22 was expected.
        var model = blk: {
            var dw = try model_mod.loadWeightsSingleFile(allocator, paths.dit);
            defer dw.deinit();
            break :blk try Model.load(allocator, &dw, .{}, dt, s);
        };
        defer model.deinit();
        if (stack.count > 0) {
            // Attach BEFORE precomputeAdaln so the adaln delta folds into the
            // tables (after it, the modulation weights are gone).
            const counts = try model.attachLoras(&stack);
            for (stack.paths[0..stack.count], stack.scales[0..stack.count], counts[0..stack.count], 0..) |p, sc, n, i| {
                const is_turbo = req.turbo and i == 0;
                // Engagement is COUNTED and logged per file: a rejected or
                // half-matching adapter is otherwise a silent no-op that looks
                // exactly like a working one.
                log.info("[minimax-h3] lora {d}/{d}: {d}/{d} modules, scale {d:.2}{s} — {s}\n", .{
                    i + 1,          stack.count, n, Model.LORA_TARGETS, sc,
                    if (is_turbo) " (turbo)" else "", std.fs.path.basename(p),
                });
                // The Turbo file names every target; anything less is a broken
                // artifact, not a smaller speedup. A style LoRA legitimately
                // targets a subset, but matching NOTHING means the file is for
                // another architecture and the user would wait an hour for an
                // unchanged render.
                if (is_turbo and n < Model.LORA_TARGETS) return error.TurboLoraIncomplete;
                if (n == 0) return error.LoraNoMatch;
            }
        }
        // AdaLN precompute must run while the trunk is still lazy — see
        // precomputeAdaln. Default ON: it is what keeps the DiT residency at
        // ~22 GB instead of ~35 on the 8-bit pack.
        if (adalnPrecomputeOn()) {
            const ts = try collectScheduleTs(allocator, &layout, sigmas[0..req.steps], req.shift_video, req.shift_audio, .{});
            defer allocator.free(ts);
            try model.precomputeAdaln(ts, s);
            log.info("[minimax-h3] adaln precomputed for {d} timesteps; 13B modulation weights released\n", .{ts.len});
        }
        try model.evalWeights();
        var active_bytes: usize = 0;
        _ = mlx.mlx_get_active_memory(&active_bytes);
        const load_ms = phase_timer.lapMs();
        log.info("[minimax-h3] dit resident: {d:.2} GB mlx-active\n", .{@as(f64, @floatFromInt(active_bytes)) / (1024.0 * 1024.0 * 1024.0)});

        const refined = try model.refineText(text_hidden, s);
        defer _ = mlx.mlx_array_free(refined);

        var rope = try buildRope(allocator, &layout, model.inv_freq, dt, s);
        defer rope.deinit();
        try mlx.check(mlx.mlx_array_eval(refined));
        log.info("[minimax-h3] dit loaded in {d} ms, text refined in {d} ms\n", .{ load_ms, phase_timer.lapMs() });

        // ── sparse attention (OPT-IN) ──
        model.sparse_policy = sparsePolicyFrom(envStr("MINIMAX_H3_SPARSE_ATTN"));
        if (model.sparse_policy != .off)
            log.info("[minimax-h3] sparse attention policy: {s}\n", .{@tagName(model.sparse_policy)});

        // ── attention broadcast (PAB-style, OPT-IN) ──
        // MINIMAX_H3_ATTN_BCAST=<k> recomputes every block's attention branch
        // only on every k-th mid-schedule step and reuses the cached output
        // between — the branch is ~70% of a 768p step. Cache cost: one
        // [S, hidden] bf16 per block (~20 GB at 768p, ~1.4 GB at 256px).
        const speed = resolveSpeed(req.fast, req.turbo, envStr("MINIMAX_H3_STEP_CACHE"), envStr("MINIMAX_H3_ATTN_BCAST"));
        log.info("[minimax-h3] speed recipe: step-cache {d:.3}, attn-broadcast k={d} (fast={any}, turbo={})\n", .{ speed.step_cache, speed.bcast_k, req.fast, req.turbo });
        const bcast_k: u32 = speed.bcast_k;
        var attn_bcast: ?AttnBroadcast = if (bcast_k > 1) try AttnBroadcast.init(allocator, model.blocks.len) else null;
        defer if (attn_bcast) |*ab| ab.deinit();
        var bcast_reused: u32 = 0;

        // ── step cache (TeaCache-style velocity reuse, OPT-IN) ──
        // Adjacent steps at high sigma produce highly-correlated velocities
        // (the shift-12 schedule clusters steps near sigma 1). When the
        // ACCUMULATED relative input change since the last real forward stays
        // under the threshold, reuse the previous velocity instead of running
        // the 50-block DiT. The audio velocity is re-scaled to the current
        // sigma's slope so the reuse stays on the audio stream's true ODE.
        // MINIMAX_H3_STEP_CACHE=<thresh> opts in (0.08 is a sane start);
        // never skips the first two or the last step, caps consecutive skips.
        const sc_thresh: f64 = speed.step_cache;
        var sc_v_video: ?mlx.mlx_array = null;
        defer if (sc_v_video) |x| {
            _ = mlx.mlx_array_free(x);
        };
        var sc_a_raw: ?mlx.mlx_array = null; // audio velocity DIVIDED by its slope
        defer if (sc_a_raw) |x| {
            _ = mlx.mlx_array_free(x);
        };
        var sc_acc: f64 = 0;
        var sc_consec: u32 = 0;
        var sc_skipped: u32 = 0;

        // I2V / chain windows pin the first temporal slice; T2V uses mid-clip.
        var preview_first_frame = false;
        for (req.keyframes) |kf| {
            if (kf.anchor == .first) {
                preview_first_frame = true;
                break;
            }
        }

        for (0..req.steps) |i| {
            model.ablate = switch (abl_mode) {
                .off => .none,
                .ladder => ladderArmForStep(i),
                .fixed => |f| f,
            };
            var step_timer = LapClock.init(io);
            const sigma = sigmas[i];
            const dsigma = sigmas[i + 1] - sigmas[i];

            // Step-cache gate: the relative input move this step would make
            // with the CACHED velocity is known without any forward.
            var sc_skip = false;
            if (sc_thresh > 0 and sc_v_video != null and i >= stepCacheWarmup(req.steps) and i + 1 < req.steps and sc_consec < 2) {
                const vmag = try meanAbs(sc_v_video.?, s);
                const xmag = try meanAbs(video_x, s);
                const rel = @abs(dsigma) * @as(f64, vmag) / @max(@as(f64, xmag), 1e-8);
                if (sc_acc + rel < sc_thresh) {
                    sc_acc += rel;
                    sc_skip = true;
                }
            }
            if (sc_skip) {
                const dv = try scalarLike(@floatCast(dsigma), sc_v_video.?, s);
                defer _ = mlx.mlx_array_free(dv);
                const stepv = try mulA(sc_v_video.?, dv, s);
                defer _ = mlx.mlx_array_free(stepv);
                const nv = try addA(video_x, stepv, s);
                _ = mlx.mlx_array_free(video_x);
                video_x = nv;
                // `sc_a_raw` is the RAW audio-clock velocity (already divided
                // by its forward's slope), so its exact advance is the mapped
                // Δσa itself; the non-turbo arm keeps the validated
                // first-order form (this path is only reachable under turbo
                // when the env forces the cache back on).
                const askip = if (req.turbo)
                    timeShiftSigma(sigmas[i + 1], req.shift_video, req.shift_audio) - timeShiftSigma(sigma, req.shift_video, req.shift_audio)
                else
                    dsigma * timeShiftSlope(sigma, req.shift_video, req.shift_audio);
                const da = try scalarLike(@floatCast(askip), sc_a_raw.?, s);
                defer _ = mlx.mlx_array_free(da);
                const stepa = try mulA(sc_a_raw.?, da, s);
                defer _ = mlx.mlx_array_free(stepa);
                const na = try addA(audio_x, stepa, s);
                _ = mlx.mlx_array_free(audio_x);
                audio_x = na;
                try mlx.check(mlx.mlx_array_eval(video_x));
                try mlx.check(mlx.mlx_array_eval(audio_x));
                sc_consec += 1;
                sc_skipped += 1;
                if (progress) |p| {
                    if (p.cancelled()) return error.Cancelled;
                    p.emit("Generating", @intCast(i + 1), req.steps);
                }
                log.info("[minimax-h3] step {d}/{d} sigma {d:.4} (cached velocity, {d} ms)\n", .{ i + 1, req.steps, sigma, step_timer.lapMs() });
                continue;
            }
            var plan = if (model.adaln_tables) |tt|
                try buildTimestepPlanGlobal(allocator, &layout, sigma, req.shift_video, req.shift_audio, .{}, tt.ts)
            else
                try buildTimestepPlan(allocator, &layout, sigma, req.shift_video, req.shift_audio, .{});
            defer plan.deinit();

            // The forward consumes EVERY video-stream row in packed order:
            // constant condition rows first (fl2va keyframes), then the noisy
            // target — the reference's `all_video_rows[~img_update] = cond`.
            const video_in = if (cond_rows) |cr|
                try concat(&[_]mlx.mlx_array{ cr, video_x }, 0, s)
            else
                video_x;
            defer if (cond_rows != null) {
                _ = mlx.mlx_array_free(video_in);
            };
            // Same contract on the AUDIO stream, which only ref2va exercises:
            // the reference audio rows sit at `~audio_update`, ahead of the
            // target's.
            const audio_in = if (audio_cond_rows) |cr|
                try concat(&[_]mlx.mlx_array{ cr, audio_x }, 0, s)
            else
                audio_x;
            defer if (audio_cond_rows != null) {
                _ = mlx.mlx_array_free(audio_in);
            };

            const refresh = attnBroadcastRefresh(i, req.steps, bcast_k);
            if (attn_bcast != null and !refresh) bcast_reused += 1;
            var out = try model.forward(&layout, &plan, refined, video_in, audio_in, rope, sigma, req.shift_video, req.shift_audio, if (attn_bcast) |*ab| ab else null, refresh, s);
            defer out.deinit();

            // Per-step JPEG from predicted clean x0 = x - σ·v, using the
            // pre-Euler noisy latent. Cached-velocity steps already continued
            // above without a preview. A failed JPEG never fails the job.
            if (progress) |p| {
                if (p.cancelled()) return error.Cancelled;
                tryEmitH3Preview(p, allocator, "Generating", @intCast(i + 1), req.steps, video_x, out.video, sigma, shape.latent_t, lat_h, lat_w, preview_first_frame, s);
            }

            // Euler on the flat ODE: x += model_output * dsigma. The audio
            // velocity already carries d(sigma_a)/d(sigma_v), so both streams
            // integrate against the SAME video-schedule step — except under
            // turbo, where the audio advance is the EXACT mapped Δσa
            // (`audioStepFactor`): at 4-8 steps the first-order form
            // over-steps the audio clock by up to 2.5x on the last leg.
            const dv = try scalarLike(@floatCast(dsigma), out.video, s);
            defer _ = mlx.mlx_array_free(dv);
            const stepv = try mulA(out.video, dv, s);
            defer _ = mlx.mlx_array_free(stepv);
            const nv = try addA(video_x, stepv, s);
            _ = mlx.mlx_array_free(video_x);
            video_x = nv;

            const da = try scalarLike(@floatCast(audioStepFactor(req.turbo, sigma, sigmas[i + 1], req.shift_video, req.shift_audio)), out.audio, s);
            defer _ = mlx.mlx_array_free(da);
            const stepa = try mulA(out.audio, da, s);
            defer _ = mlx.mlx_array_free(stepa);
            const na = try addA(audio_x, stepa, s);
            _ = mlx.mlx_array_free(audio_x);
            audio_x = na;

            if (sc_thresh > 0) {
                const slope_f = timeShiftSlope(sigma, req.shift_video, req.shift_audio);
                if (slope_f > 1e-9) {
                    if (sc_v_video) |x| _ = mlx.mlx_array_free(x);
                    sc_v_video = try contig(out.video, s);
                    const inv_slope = try scalarLike(@floatCast(1.0 / slope_f), out.audio, s);
                    defer _ = mlx.mlx_array_free(inv_slope);
                    if (sc_a_raw) |x| _ = mlx.mlx_array_free(x);
                    sc_a_raw = try mulA(out.audio, inv_slope, s);
                }
                sc_acc = 0;
                sc_consec = 0;
            }

            try mlx.check(mlx.mlx_array_eval(video_x));
            try mlx.check(mlx.mlx_array_eval(audio_x));
            if (progress) |p| {
                if (p.cancelled()) return error.Cancelled;
            }
            // Every denoise loop owes a periodic cache clear: MLX's pool is
            // unbounded and these shapes repeat, so without it the process
            // footprint ratchets across steps.
            _ = mlx.mlx_clear_cache();
            const step_ms = step_timer.lapMs();
            if (std.meta.activeTag(abl_mode) != .off) {
                log.info("[h3-prof] arm={s} step={d} ms={d}\n", .{ @tagName(model.ablate), i, step_ms });
            } else {
                log.info("[minimax-h3] step {d}/{d} sigma {d:.4} ({d} ms)\n", .{ i + 1, req.steps, sigma, step_ms });
            }
        }
        if (sc_skipped > 0)
            log.info("[minimax-h3] step-cache reused velocity on {d}/{d} steps (thresh {d:.3})\n", .{ sc_skipped, req.steps, sc_thresh });
        if (bcast_reused > 0)
            log.info("[minimax-h3] attn-broadcast reused attention on {d}/{d} steps (k={d})\n", .{ bcast_reused, req.steps, bcast_k });
    }
    _ = mlx.mlx_clear_cache();
    log.info("[minimax-h3] sampling done in {d} ms, DiT released\n", .{phase_timer.lapMs()});

    // ── 4. VAE decode ──
    // Unpatchify the video rows back to a latent volume: rows are
    // (t, h/2, w/2) major with C*2*2 per row.
    const zlat = try unpatchifyVideoRows(video_x, shape.latent_t, lat_h, lat_w, s);
    defer _ = mlx.mlx_array_free(zlat);

    if (progress) |p| p.emit("Decoding video", req.steps, req.steps);
    _ = phase_timer.lapMs();
    var vw = try model_mod.loadWeightsSingleFile(allocator, paths.vae);
    defer vw.deinit();
    var dec = try vae_mod.Decoder.load(allocator, &vw, .{}, dt, s);
    defer dec.deinit();
    const pixels = try vae_mod.decode(&dec, zlat, allocator, s);
    errdefer _ = mlx.mlx_array_free(pixels);
    try mlx.check(mlx.mlx_array_eval(pixels));
    _ = mlx.mlx_clear_cache();
    log.info("[minimax-h3] video decoded in {d} ms (load+decode)\n", .{phase_timer.lapMs()});

    const audio_latent = try audioRowsToLatent(audio_x, shape.audio_t, s);
    errdefer _ = mlx.mlx_array_free(audio_latent);

    // ── 5. audio VAE (optional) ──
    var audio_wave: ?mlx.mlx_array = null;
    if (paths.audio_vae) |apath| {
        if (progress) |p| p.emit("Decoding audio", req.steps, req.steps);
        var aw = try model_mod.loadWeightsSingleFile(allocator, apath);
        defer aw.deinit();
        const wave = try audio_mod.decode(allocator, &aw, audio_latent, dt, s);
        try mlx.check(mlx.mlx_array_eval(wave));
        audio_wave = wave;
        _ = mlx.mlx_clear_cache();
        log.info("[minimax-h3] audio decoded: {d} samples/ch at {d} Hz ({d} ms)\n", .{ mlx.getShape(wave)[1], audio_mod.SAMPLE_RATE, phase_timer.lapMs() });
    }

    const pshape = mlx.getShape(pixels);
    return .{
        .pixels = pixels,
        .audio_latent = audio_latent,
        .audio = audio_wave,
        .frame_count = @intCast(pshape[2]),
        .height = @intCast(pshape[3]),
        .width = @intCast(pshape[4]),
    };
}

// ── Chained windows ─────────────────────────────────────────────────────────

/// Unique frames a chained clip delivers: each seam drops the duplicate frame
/// (window N+1's frame 0 reproduces its conditioning keyframe).
pub fn chainDeliveredFrames(windows: u32, window_frames: u32) u32 {
    return windows * window_frames - (windows - 1);
}

/// One video frame of audio — the cross-fade width at each seam.
pub const CHAIN_OVERLAP_SAMPLES: usize = audio_mod.SAMPLE_RATE / FPS;

/// [1,3,F,H,W] -> [1,3,hi-lo,H,W]. The frame slice is never row-contiguous
/// (channel planes are strided across it), so `contig` materializes a REAL
/// copy and the window's 0.7 GB pixel buffer is not pinned by a view.
fn sliceFrames(x: mlx.mlx_array, lo: c_int, hi: c_int, s: S) !mlx.mlx_array {
    const shp = mlx.getShape(x);
    const start = [_]c_int{ 0, 0, lo, 0, 0 };
    const stop = [_]c_int{ shp[0], shp[1], hi, shp[3], shp[4] };
    const step = [_]c_int{ 1, 1, 1, 1, 1 };
    var o = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(o);
    try mlx.check(mlx.mlx_slice(&o, x, &start, 5, &stop, 5, &step, 5, s));
    return contig(o, s);
}

/// Equal-power cross-fade join of mono sample runs: `out` is seg0, then each
/// later segment fades in over `overlap` samples of what was already written
/// (weights cos/sin at t=(j+0.5)/ov·π/2) and appends its remainder. Pure host
/// math so the seam is unit-testable; the caller applies it per channel.
pub fn crossfadeJoin(allocator: std.mem.Allocator, segs: []const []const f32, overlap: usize) ![]f32 {
    var total: usize = 0;
    for (segs, 0..) |sg, i| {
        total += sg.len;
        if (i > 0) total -= @min(overlap, sg.len);
    }
    var out = try allocator.alloc(f32, total);
    errdefer allocator.free(out);
    var pos: usize = 0;
    for (segs, 0..) |sg, i| {
        if (i == 0) {
            @memcpy(out[0..sg.len], sg);
            pos = sg.len;
            continue;
        }
        const ov = @min(overlap, @min(sg.len, pos));
        const base = pos - ov;
        for (0..ov) |j| {
            const t = (@as(f32, @floatFromInt(j)) + 0.5) / @as(f32, @floatFromInt(ov)) * (std.math.pi / 2.0);
            out[base + j] = out[base + j] * @cos(t) + sg[j] * @sin(t);
        }
        @memcpy(out[pos .. pos + (sg.len - ov)], sg[ov..]);
        pos += sg.len - ov;
    }
    std.debug.assert(pos == total);
    return out;
}

/// Stereo [2, L] waves -> one [2, L_total] f32 array joined per channel with
/// `crossfadeJoin`. Waves are pulled to the host (the PCM writer does the same
/// pull later; a seam is a few thousand samples of scalar math).
fn joinWavesCrossfade(allocator: std.mem.Allocator, waves: []const mlx.mlx_array, overlap: usize, s: S) !mlx.mlx_array {
    var planes = try allocator.alloc([]f32, waves.len);
    var built: usize = 0;
    defer {
        for (planes[0..built]) |p| allocator.free(p);
        allocator.free(planes);
    }
    var lens = try allocator.alloc(usize, waves.len);
    defer allocator.free(lens);
    for (waves, 0..) |wv, i| {
        const c = try contig(wv, s);
        defer _ = mlx.mlx_array_free(c);
        const f = try astype(c, mlx.mlx_dtype.float32, s);
        defer _ = mlx.mlx_array_free(f);
        try mlx.check(mlx.mlx_array_eval(f));
        const n: usize = @intCast(mlx.mlx_array_size(f));
        const raw = mlx.mlx_array_data_float32(f) orelse return error.NoAudioData;
        planes[i] = try allocator.dupe(f32, raw[0..n]);
        built += 1;
        lens[i] = n / 2;
    }
    var ch_out: [2][]f32 = undefined;
    var ch_built: usize = 0;
    defer for (ch_out[0..ch_built]) |p| allocator.free(p);
    for (0..2) |ch| {
        var segs = try allocator.alloc([]const f32, waves.len);
        defer allocator.free(segs);
        for (planes, 0..) |p, i| segs[i] = p[ch * lens[i] .. (ch + 1) * lens[i]];
        ch_out[ch] = try crossfadeJoin(allocator, segs, overlap);
        ch_built += 1;
    }
    const lt = ch_out[0].len;
    std.debug.assert(ch_out[1].len == lt);
    const buf = try allocator.alloc(f32, 2 * lt);
    defer allocator.free(buf);
    @memcpy(buf[0..lt], ch_out[0]);
    @memcpy(buf[lt..], ch_out[1]);
    const shp = [_]c_int{ 2, @intCast(lt) };
    return mlx.mlx_array_new_data(buf.ptr, &shp, 2, mlx.mlx_dtype.float32);
}

/// Progress adapter: prefixes the stage with "Window w/n" and remaps
/// determinate bars onto the whole chain so the client's meter is monotone
/// across windows instead of restarting at every seam.
const ChainProgress = struct {
    inner: gen_sse.Progress,
    window: u32,
    windows: u32,

    fn cb(ptr: *anyopaque, stage: []const u8, step: u32, total: u32) void {
        const self: *ChainProgress = @ptrCast(@alignCast(ptr));
        var buf: [96]u8 = undefined;
        const label = std.fmt.bufPrint(&buf, "Window {d}/{d}: {s}", .{ self.window + 1, self.windows, stage }) catch stage;
        if (total > 0)
            self.inner.emit(label, self.window * total + step, self.windows * total)
        else
            self.inner.emit(label, step, 0);
    }
    fn cancelledCb(ptr: *anyopaque) bool {
        const self: *ChainProgress = @ptrCast(@alignCast(ptr));
        return self.inner.cancelled();
    }
    fn previewCb(ptr: *anyopaque, stage: []const u8, step: u32, total: u32, frame: @import("preview.zig").Encoded) void {
        const self: *ChainProgress = @ptrCast(@alignCast(ptr));
        var buf: [96]u8 = undefined;
        const label = std.fmt.bufPrint(&buf, "Window {d}/{d}: {s}", .{ self.window + 1, self.windows, stage }) catch stage;
        if (total > 0)
            self.inner.emitPreview(label, self.window * total + step, self.windows * total, frame)
        else
            self.inner.emitPreview(label, step, 0, frame);
    }
    fn progress(self: *ChainProgress) gen_sse.Progress {
        return .{
            .ctx = self,
            .cb = cb,
            .cancelled_cb = cancelledCb,
            .preview_cb = if (self.inner.preview_cb != null) previewCb else null,
            .preview_opts = self.inner.preview_opts,
        };
    }
};

/// N single-window generations chained by fl2va keyframes: window N's last
/// decoded frame is VAE-encoded as window N+1's `.first` keyframe (the
/// ordinary conditioning path), the duplicate frame is dropped at the join and
/// the pieces butt-join in pixel space with a one-frame equal-power audio
/// cross-fade. The user's own `.first` keyframe applies to window 0, their
/// `.last` to the final window. v1 reloads the staged pipeline per window —
/// the whole validated single-window path runs byte-for-byte unchanged, at the
/// cost of the TE/DiT load time once per window.
fn generateChain(
    allocator: std.mem.Allocator,
    io: std.Io,
    paths: GenPaths,
    req: GenRequest,
    progress: ?gen_sse.Progress,
    s: S,
) !GenResult {
    const n = req.chain_windows;
    std.debug.assert(n >= 2);
    // A reference has no keyframe row to chain through; the handler rejects
    // this by name, the engine refuses to silently produce it.
    if (req.refs.len > 0) return error.ChainWithRefs;

    var user_first: ?Keyframe = null;
    var user_last: ?Keyframe = null;
    for (req.keyframes) |kf| switch (kf.anchor) {
        .first => user_first = kf,
        .last => user_last = kf,
    };

    var pixel_segs: std.ArrayList(mlx.mlx_array) = .empty;
    defer {
        for (pixel_segs.items) |x| _ = mlx.mlx_array_free(x);
        pixel_segs.deinit(allocator);
    }
    var waves: std.ArrayList(mlx.mlx_array) = .empty;
    defer {
        for (waves.items) |x| _ = mlx.mlx_array_free(x);
        waves.deinit(allocator);
    }
    var have_audio = true;
    var final_latent: ?mlx.mlx_array = null;
    errdefer if (final_latent) |x| {
        _ = mlx.mlx_array_free(x);
    };
    var prev_last: ?mlx.mlx_array = null;
    defer if (prev_last) |x| {
        _ = mlx.mlx_array_free(x);
    };
    var out_w: u32 = 0;
    var out_h: u32 = 0;

    for (0..n) |w| {
        var kfs: [2]Keyframe = undefined;
        var nk: usize = 0;
        if (w == 0) {
            if (user_first) |kf| {
                kfs[nk] = kf;
                nk += 1;
            }
        } else {
            kfs[nk] = .{ .anchor = .first, .pixels = prev_last.?, .vision = null };
            nk += 1;
        }
        if (w == n - 1) {
            if (user_last) |kf| {
                kfs[nk] = kf;
                nk += 1;
            }
        }

        var wreq = req;
        wreq.chain_windows = 1;
        // Window 0 must reproduce the single-window generation exactly (same
        // seed); later windows shift by 2 because generateOne draws seed and
        // seed+1 (video/audio).
        wreq.seed = req.seed +% 2 * @as(u64, @intCast(w));
        wreq.keyframes = kfs[0..nk];

        var cp: ChainProgress = undefined;
        var wprog: ?gen_sse.Progress = null;
        if (progress) |p| {
            cp = .{ .inner = p, .window = @intCast(w), .windows = n };
            wprog = cp.progress();
        }

        const res = try generateOne(allocator, io, paths, wreq, wprog, s);
        // Deconstructed rather than deinit'd: the join takes the parts. `rp`
        // nulls out as ownership moves so no error path can double-free.
        const rframes: c_int = @intCast(res.frame_count);
        out_w = res.width;
        out_h = res.height;
        var rp: ?mlx.mlx_array = res.pixels;
        errdefer if (rp) |x| {
            _ = mlx.mlx_array_free(x);
        };
        if (res.audio) |wave| {
            waves.append(allocator, wave) catch |e| {
                _ = mlx.mlx_array_free(wave);
                _ = mlx.mlx_array_free(res.audio_latent);
                return e;
            };
        } else have_audio = false;
        if (w == n - 1) {
            final_latent = res.audio_latent;
        } else {
            _ = mlx.mlx_array_free(res.audio_latent);
        }

        if (w + 1 < n) {
            if (prev_last) |x| _ = mlx.mlx_array_free(x);
            prev_last = try sliceFrames(rp.?, rframes - 1, rframes, s);
            try mlx.check(mlx.mlx_array_eval(prev_last.?));
        }
        // Drop the duplicate join frame: window w>0's frame 0 reproduces the
        // keyframe that conditioned it, which the previous window already
        // delivered as its last frame.
        const seg = if (w == 0) blk: {
            const p = rp.?;
            rp = null;
            break :blk p;
        } else blk: {
            const sl = try sliceFrames(rp.?, 1, rframes, s);
            errdefer _ = mlx.mlx_array_free(sl);
            try mlx.check(mlx.mlx_array_eval(sl));
            _ = mlx.mlx_array_free(rp.?);
            rp = null;
            break :blk sl;
        };
        pixel_segs.append(allocator, seg) catch |e| {
            _ = mlx.mlx_array_free(seg);
            return e;
        };
        _ = mlx.mlx_clear_cache();
        log.info("[minimax-h3] chain window {d}/{d} done ({d} frames{s})\n", .{ w + 1, n, res.frame_count, if (w > 0) " — join frame dropped" else "" });
    }

    const joined = blk: {
        const vec = mlx.mlx_vector_array_new();
        defer _ = mlx.mlx_vector_array_free(vec);
        for (pixel_segs.items) |p| _ = mlx.mlx_vector_array_append_value(vec, p);
        var o = mlx.mlx_array_new();
        errdefer _ = mlx.mlx_array_free(o);
        try mlx.check(mlx.mlx_concatenate_axis(&o, vec, 2, s));
        try mlx.check(mlx.mlx_array_eval(o));
        break :blk o;
    };
    errdefer _ = mlx.mlx_array_free(joined);

    var audio_joined: ?mlx.mlx_array = null;
    if (have_audio and waves.items.len == n) {
        audio_joined = try joinWavesCrossfade(allocator, waves.items, CHAIN_OVERLAP_SAMPLES, s);
    }
    errdefer if (audio_joined) |x| {
        _ = mlx.mlx_array_free(x);
    };
    _ = mlx.mlx_clear_cache();

    const pshape = mlx.getShape(joined);
    log.info("[minimax-h3] chain joined: {d} windows -> {d} frames, audio {s}\n", .{ n, pshape[2], if (audio_joined != null) "cross-faded" else "absent" });
    return .{
        .pixels = joined,
        .audio_latent = final_latent orelse return error.ChainNoWindows,
        .audio = audio_joined,
        .frame_count = @intCast(pshape[2]),
        .height = out_h,
        .width = out_w,
    };
}

// ── Output conversion ───────────────────────────────────────────────────────

/// [1,3,F,H,W] in [-1,1] -> tightly packed [F,H,W,3] u8. Caller owns.
pub fn pixelsToRgb8(allocator: std.mem.Allocator, res: *const GenResult, s: S) ![]u8 {
    const p = try transpose(res.pixels, &[_]c_int{ 0, 2, 3, 4, 1 }, s);
    defer _ = mlx.mlx_array_free(p);
    const pc = try contig(p, s);
    defer _ = mlx.mlx_array_free(pc);
    const one = try scalarLike(1.0, pc, s);
    defer _ = mlx.mlx_array_free(one);
    const shifted = try addA(pc, one, s);
    defer _ = mlx.mlx_array_free(shifted);
    const k = try scalarLike(127.5, shifted, s);
    defer _ = mlx.mlx_array_free(k);
    const scaled = try mulA(shifted, k, s);
    defer _ = mlx.mlx_array_free(scaled);
    const u8a = try astype(scaled, mlx.mlx_dtype.uint8, s);
    defer _ = mlx.mlx_array_free(u8a);
    try mlx.check(mlx.mlx_array_eval(u8a));
    const n: usize = @intCast(mlx.mlx_array_size(u8a));
    const raw = mlx.mlx_array_data_uint8(u8a) orelse return error.NoPixelData;
    return allocator.dupe(u8, raw[0..n]);
}

/// Stereo [2, L] f32 -> interleaved little-endian 16-bit PCM. Caller owns.
pub fn audioToPcm16(allocator: std.mem.Allocator, wave: mlx.mlx_array, s: S) ![]u8 {
    const t = try transpose(wave, &[_]c_int{ 1, 0 }, s);
    defer _ = mlx.mlx_array_free(t);
    const tc = try contig(t, s);
    defer _ = mlx.mlx_array_free(tc);
    const f = try astype(tc, mlx.mlx_dtype.float32, s);
    defer _ = mlx.mlx_array_free(f);
    try mlx.check(mlx.mlx_array_eval(f));
    const n: usize = @intCast(mlx.mlx_array_size(f));
    const raw = mlx.mlx_array_data_float32(f) orelse return error.NoAudioData;
    const out = try allocator.alloc(u8, n * 2);
    errdefer allocator.free(out);
    for (0..n) |i| {
        // The vocoder already clamps to [-1,1]; clamp again so a future change
        // upstream cannot wrap a sample to the opposite rail.
        const v = std.math.clamp(raw[i], -1.0, 1.0);
        const q: i16 = @intFromFloat(v * 32767.0);
        std.mem.writeInt(i16, out[i * 2 ..][0..2], q, .little);
    }
    return out;
}

// ── Tests ───────────────────────────────────────────────────────────────────

const testing = std.testing;

/// Golden values produced by ComfyUI's own reference implementation. Hermetic:
/// no weights, no network, no env gate.
const layout_fixture = @embedFile("fixtures/minimax_h3_layout.json");

fn loadFixture(allocator: std.mem.Allocator) !std.json.Parsed(std.json.Value) {
    return std.json.parseFromSlice(std.json.Value, allocator, layout_fixture, .{});
}

fn jsonF64(v: std.json.Value) f64 {
    return switch (v) {
        .float => |f| f,
        .integer => |i| @floatFromInt(i),
        else => std.math.nan(f64),
    };
}

fn jsonU32(v: std.json.Value) u32 {
    return switch (v) {
        .integer => |i| @intCast(i),
        else => 0,
    };
}

// Live end-to-end generation. Env-gated like the other weight-dependent
// oracles in this repo (DSV4_TEST_MODEL, MAGEFLOW_*), because it needs ~115 GB
// of checkpoints staged on disk and takes minutes.
//
//   MINIMAX_H3_DIR=~/claude-tmp/h3-build \
//   MINIMAX_H3_OUT=~/claude-tmp/h3-build/out \
//   MINIMAX_H3_STEPS=30 MINIMAX_H3_FRAMES=56 MINIMAX_H3_SIZE=256 \
//   zig build test -Doptimize=ReleaseFast -Dtest-filter="minimax h3 live"
//
// Writes a PNG per frame. The mp4 mux lives in the Swift app (AVAssetWriter),
// matching how the LTX path already delivers video.
test "minimax h3 live: generates a clip" {
    const dir = envStr("MINIMAX_H3_DIR") orelse return error.SkipZigTest;
    log.enableStderr(); // the phase/step lines are this harness's output
    const a = testing.allocator;
    const io = std.Io.Threaded.global_single_threaded.io();
    const s = mlx.gpuStream();

    const size = envU32("MINIMAX_H3_SIZE", 256);
    const frames = envU32("MINIMAX_H3_FRAMES", 56);
    const steps = envU32("MINIMAX_H3_STEPS", 30);
    const out_dir = envStr("MINIMAX_H3_OUT") orelse "/tmp/h3out";

    // Two layouts are accepted so the SAME test covers both: the raw staging
    // tree of upstream bf16 files, and a converted model dir from
    // tests/convert_minimax_h3_weights.py (which is also what the app will
    // ship). Both load through MfLinear's one geometry solve — running the
    // quantized dir here is what proves that.
    const converted = envStr("MINIMAX_H3_MODEL");
    const te = if (converted) |m|
        try std.fmt.allocPrint(a, "{s}/text_encoder.safetensors", .{m})
    else
        try std.fmt.allocPrint(a, "{s}/src/text_encoders/qwen3vl_32b_minimax_h3_bf16.safetensors", .{dir});
    defer a.free(te);
    const dit = if (converted) |m|
        try std.fmt.allocPrint(a, "{s}/transformer.safetensors", .{m})
    else
        try std.fmt.allocPrint(a, "{s}/src/diffusion_models/minimax_h3_fl2va_bf16.safetensors", .{dir});
    defer a.free(dit);
    const vae = if (converted) |m|
        try std.fmt.allocPrint(a, "{s}/video_vae.safetensors", .{m})
    else
        try std.fmt.allocPrint(a, "{s}/src/vae/minimax_h3_video_vae_fp16.safetensors", .{dir});
    defer a.free(vae);
    const avae = if (converted) |m|
        try std.fmt.allocPrint(a, "{s}/audio_vae.safetensors", .{m})
    else
        try std.fmt.allocPrint(a, "{s}/src/vae/minimax_h3_audio_vae_fp32.safetensors", .{dir});
    defer a.free(avae);
    const tokdir = if (converted) |m|
        try std.fmt.allocPrint(a, "{s}", .{m})
    else
        try std.fmt.allocPrint(a, "{s}/src_orig/FL2VA/processor", .{dir});
    defer a.free(tokdir);

    const prompt = envStr("MINIMAX_H3_PROMPT") orelse
        "A calico cat sits on a sunlit windowsill, slowly blinking as it watches rain streak down the glass. " ++
        "The camera holds steady in a close medium shot. Warm afternoon light rims the cat's fur against the cool grey outside. " ++
        "overall_soundscape: steady rainfall against glass with a soft room tone and the cat's quiet purring.";

    var res = try generate(a, io, .{
        .tokenizer_dir = tokdir,
        .text_encoder = te,
        .dit = dit,
        .vae = vae,
        .audio_vae = avae,
    }, .{
        .prompt = prompt,
        .width = envU32("MINIMAX_H3_WIDTH", size),
        .height = size,
        .frames = frames,
        .steps = steps,
    }, null, s);
    defer res.deinit();

    // The pipeline can produce a plausible-looking tensor full of NaN; a
    // finiteness check has to come BEFORE anything that inspects values.
    const finite = try allFinite(res.pixels, s);
    try testing.expect(finite);
    try testing.expectEqual(alignFrameCount(@max(5, frames)), res.frame_count);
    try testing.expectEqual(envU32("MINIMAX_H3_WIDTH", size), res.width);
    try testing.expectEqual(size, res.height);

    try writeFrames(a, io, &res, out_dir, s);

    // Audio must be finite AND non-silent: an all-zero waveform passes every
    // shape assertion and is exactly what a broken vocoder produces.
    const wave = res.audio orelse return error.MissingAudio;
    try testing.expect(try allFinite(wave, s));
    const peak = try absMax(wave, s);
    std.debug.print("[minimax-h3] audio peak {d:.4}\n", .{peak});
    try testing.expect(peak > 0.001);
    try testing.expect(peak <= 1.0); // the vocoder clamps
    try writeWav(a, io, wave, out_dir, s);

    std.debug.print("[minimax-h3] wrote {d} frames {d}x{d} to {s}\n", .{ res.frame_count, res.width, res.height, out_dir });
}

/// libc getenv, matching generate.zig's allocator-free env idiom.
fn envStr(name: [:0]const u8) ?[]const u8 {
    const raw = std.c.getenv(name.ptr) orelse return null;
    const slice = std.mem.sliceTo(raw, 0);
    return if (slice.len == 0) null else slice;
}

fn envU32(name: [:0]const u8, dflt: u32) u32 {
    const v = envStr(name) orelse return dflt;
    return std.fmt.parseInt(u32, v, 10) catch dflt;
}

/// Whether `generate` will table and free the DiT's AdaLN weights. Shared with
/// `gen.estimatePeakResidentBytes`: a residency bill computed against the OTHER
/// answer is either an OOM (billed shed, ran full) or a refused load.
pub fn adalnPrecomputeOn() bool {
    const raw = envStr("MINIMAX_H3_ADALN_PRECOMPUTE") orelse return true;
    return !std.mem.eql(u8, raw, "0");
}

fn allFinite(x: mlx.mlx_array, s: S) !bool {
    var isf = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(isf);
    try mlx.check(mlx.mlx_isfinite(&isf, x, s));
    var allv = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(allv);
    try mlx.check(mlx.mlx_all(&allv, isf, false, s));
    try mlx.check(mlx.mlx_array_eval(allv));
    var b: bool = false;
    try mlx.check(mlx.mlx_array_item_bool(&b, allv));
    return b;
}

/// [-1,1] pixels -> 8-bit RGB frames on disk (raw + PNG).
fn writeFrames(a: std.mem.Allocator, io: std.Io, res: *const GenResult, out_dir: []const u8, s: S) !void {
    const png = @import("png.zig");
    // [1,3,F,H,W] -> [F,H,W,3] u8
    const p = try transpose(res.pixels, &[_]c_int{ 0, 2, 3, 4, 1 }, s);
    defer _ = mlx.mlx_array_free(p);
    const pc = try contig(p, s);
    defer _ = mlx.mlx_array_free(pc);
    const half = try scalarLike(0.5, pc, s);
    defer _ = mlx.mlx_array_free(half);
    const shifted = try addA(pc, try oneLike(pc, s), s);
    defer _ = mlx.mlx_array_free(shifted);
    const unit = try mulA(shifted, half, s);
    defer _ = mlx.mlx_array_free(unit);
    const c255 = try scalarLike(255.0, unit, s);
    defer _ = mlx.mlx_array_free(c255);
    const scaled = try mulA(unit, c255, s);
    defer _ = mlx.mlx_array_free(scaled);
    const u8a = try astype(scaled, mlx.mlx_dtype.uint8, s);
    defer _ = mlx.mlx_array_free(u8a);
    try mlx.check(mlx.mlx_array_eval(u8a));

    const n = res.frame_count * res.height * res.width * 3;
    const raw = mlx.mlx_array_data_uint8(u8a) orelse return error.NoPixelData;

    std.Io.Dir.cwd().createDirPath(io, out_dir) catch {};
    var d = try std.Io.Dir.cwd().openDir(io, out_dir, .{});
    defer d.close(io);

    const frame_bytes = res.height * res.width * 3;
    for (0..res.frame_count) |f| {
        const slice = raw[f * frame_bytes ..][0..frame_bytes];
        const bytes = try png.encodeRgb(a, slice, res.width, res.height);
        defer a.free(bytes);
        const name = try std.fmt.allocPrint(a, "frame_{d:0>4}.png", .{f});
        defer a.free(name);
        var fh = try d.createFile(io, name, .{});
        defer fh.close(io);
        var wbuf: [4096]u8 = undefined;
        var w = fh.writer(io, &wbuf);
        try w.interface.writeAll(bytes);
        try w.interface.flush();
    }
    _ = n;
}

fn oneLike(like: mlx.mlx_array, s: S) !mlx.mlx_array {
    return scalarLike(1.0, like, s);
}

fn meanAbs(x: mlx.mlx_array, s: S) !f32 {
    var ab = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(ab);
    try mlx.check(mlx.mlx_abs(&ab, x, s));
    var mv = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(mv);
    try mlx.check(mlx.mlx_mean(&mv, ab, false, s));
    try mlx.check(mlx.mlx_array_eval(mv));
    var v: f32 = 0;
    try mlx.check(mlx.mlx_array_item_float32(&v, mv));
    return v;
}

fn absMax(x: mlx.mlx_array, s: S) !f32 {
    var ab = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(ab);
    try mlx.check(mlx.mlx_abs(&ab, x, s));
    var mx = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(mx);
    try mlx.check(mlx.mlx_max(&mx, ab, false, s));
    try mlx.check(mlx.mlx_array_eval(mx));
    var v: f32 = 0;
    try mlx.check(mlx.mlx_array_item_float32(&v, mx));
    return v;
}

/// Stereo [2, L] f32 -> interleaved 16-bit WAV at 32 kHz.
fn writeWav(a: std.mem.Allocator, io: std.Io, wave: mlx.mlx_array, out_dir: []const u8, s: S) !void {
    const wav = @import("wav.zig");
    // [2, L] -> [L, 2] interleaved, which is what encodePcm16 expects.
    const t = try transpose(wave, &[_]c_int{ 1, 0 }, s);
    defer _ = mlx.mlx_array_free(t);
    const tc = try contig(t, s);
    defer _ = mlx.mlx_array_free(tc);
    const f = try astype(tc, mlx.mlx_dtype.float32, s);
    defer _ = mlx.mlx_array_free(f);
    try mlx.check(mlx.mlx_array_eval(f));
    const n: usize = @intCast(mlx.mlx_array_size(f));
    const raw = mlx.mlx_array_data_float32(f) orelse return error.NoAudioData;
    const bytes = try wav.encodePcm16(a, raw[0..n], audio_mod.SAMPLE_RATE, 2);
    defer a.free(bytes);

    var d = try std.Io.Dir.cwd().openDir(io, out_dir, .{});
    defer d.close(io);
    var fh = try d.createFile(io, "audio.wav", .{});
    defer fh.close(io);
    var wbuf: [4096]u8 = undefined;
    var w = fh.writer(io, &wbuf);
    try w.interface.writeAll(bytes);
    try w.interface.flush();
}

test "minimax h3: patchifyVideo matches the reference einsum order" {
    const s = mlx.gpuStream();
    // [1, C=2, T=1, H=2, W=2] with v[c,y,x] = c*100 + y*10 + x. One row of 8,
    // ordered [c, pt, ph, pw]-flattened per the reference's
    // `nctrhpwq -> nthwcrpq`: c0 quad then c1 quad, row-major within the patch.
    var buf: [8]f32 = .{ 0, 1, 10, 11, 100, 101, 110, 111 };
    const sh = [_]c_int{ 1, 2, 1, 2, 2 };
    const x = mlx.mlx_array_new_data(&buf, &sh, 5, mlx.mlx_dtype.float32);
    defer _ = mlx.mlx_array_free(x);
    const rows = try patchifyVideo(x, s);
    defer _ = mlx.mlx_array_free(rows);
    const rshp = mlx.getShape(rows);
    try testing.expectEqual(@as(c_int, 1), rshp[0]);
    try testing.expectEqual(@as(c_int, 8), rshp[1]);
    try mlx.check(mlx.mlx_array_eval(rows));
    const data = mlx.mlx_array_data_float32(rows).?;
    const want = [_]f32{ 0, 1, 10, 11, 100, 101, 110, 111 };
    for (want, 0..) |v, i| try testing.expectEqual(v, data[i]);
}

test "minimax h3: audio latents pack to the rows the DiT unpacks back" {
    // The reference's `pack_audio` is `latent[0].permute(1,2,0)` and its
    // `unpack_audio` is the inverse. We already SHIPPED the unpack (the target
    // audio latent at the end of `generate`); the ref2va cond rows need the
    // other direction, and a wrong permutation there produces a plausibly
    // shaped array that silently interleaves the stereo channels.
    const s = mlx.gpuStream();
    // [1, C=2, ch=2, T=3], v[c, ch, t] = c*100 + ch*10 + t.
    var buf: [12]f32 = .{ 0, 1, 2, 10, 11, 12, 100, 101, 102, 110, 111, 112 };
    const sh = [_]c_int{ 1, 2, 2, 3 };
    const z = mlx.mlx_array_new_data(&buf, &sh, 4, mlx.mlx_dtype.float32);
    defer _ = mlx.mlx_array_free(z);

    const rows = try audioLatentToRows(z, s);
    defer _ = mlx.mlx_array_free(rows);
    // ch-major: (ch0 t0, ch0 t1, ch0 t2, ch1 t0, …), each row [C].
    const rshp = mlx.getShape(rows);
    try testing.expectEqual(@as(c_int, 6), rshp[0]);
    try testing.expectEqual(@as(c_int, 2), rshp[1]);
    try mlx.check(mlx.mlx_array_eval(rows));
    const rd = mlx.mlx_array_data_float32(rows).?;
    const want = [_]f32{ 0, 100, 1, 101, 2, 102, 10, 110, 11, 111, 12, 112 };
    for (want, 0..) |v, i| try testing.expectEqual(v, rd[i]);

    // …and round-trips through the shipped unpack, which is what the target
    // audio latent is built with.
    const back = try audioRowsToLatent(rows, 3, s);
    defer _ = mlx.mlx_array_free(back);
    try mlx.check(mlx.mlx_array_eval(back));
    const bd = mlx.mlx_array_data_float32(back).?;
    for (buf, 0..) |v, i| try testing.expectEqual(v, bd[i]);
}

test "minimax h3: a ref block is DERIVED from its resolved reference" {
    // `resolveRefs` hands back refs and blocks as parallel arrays, and the
    // generation path needs to go from one to the other (it encodes per ref and
    // must lay out per block). Deriving the block from the ref through the ONE
    // function `resolveRefs` itself uses is what keeps the two from drifting —
    // a second hand-rolled mapping is the class that put the dsv4 exclusion in
    // three places.
    const a = testing.allocator;
    const images = [_]RefInput{.{ .kind = .image, .w = 1024, .h = 768 }};
    const videos = [_]RefInput{
        .{ .kind = .video, .w = 640, .h = 480, .frames = 39 },
        .{ .kind = .video, .w = 1920, .h = 1080, .frames = 56, .soundtrack_samples = 48000 },
    };
    const audios = [_]RefInput{.{ .kind = .audio, .audio_samples = 32000 }};
    var res = switch (try resolveRefs(a, &images, &videos, &audios, 864, 480, .match)) {
        .ok => |r| r,
        .reject => return error.UnexpectedReject,
    };
    defer res.deinit();
    try testing.expectEqual(res.refs.len, res.blocks.len);
    for (res.refs, res.blocks) |r, b| try testing.expectEqual(b, refBlockFor(r));
}

test "minimax h3: timestep plan can index a GLOBAL schedule table" {
    // AdaLN precompute materializes modulations for the WHOLE schedule up
    // front, so per-step runs must index rows of the global sorted t table,
    // not the forward's own 2-3 element set.
    const a = testing.allocator;
    var layout = try PackedLayout.init(a, 4, 2, 4, 4, 3, &.{}, 5);
    defer layout.deinit();

    const sigma = 0.5;
    var local = try buildTimestepPlan(a, &layout, sigma, 12.0, 3.0, .{});
    defer local.deinit();

    // A global table containing the step's ts plus others, sorted.
    const t_v = 1.0 - sigma;
    const t_a = 1.0 - timeShiftSigma(sigma, 12.0, 3.0);
    const global = [_]f64{ 0.1, t_a, 0.3, t_v, 0.9 };
    var g = try buildTimestepPlanGlobal(a, &layout, sigma, 12.0, 3.0, .{}, &global);
    defer g.deinit();

    // Same runs, but rows resolve into the GLOBAL table: t_a sits at global
    // index 1, t_v at 3 (the layout has text/audio/video segments only).
    try testing.expectEqual(local.runs.len, g.runs.len);
    for (g.runs, local.runs) |gr, lr| {
        try testing.expectEqual(lr.start, gr.start);
        try testing.expectEqual(lr.end, gr.end);
        const tag = lr.mod_row % 3;
        const local_t = local.unique_t[lr.mod_row / 3];
        try testing.expectEqual(tag, gr.mod_row % 3);
        try testing.expectEqual(local_t, global[gr.mod_row / 3]);
    }
}

test "minimax h3: schedule t-set collects every step's unique timesteps" {
    const a = testing.allocator;
    var layout = try PackedLayout.init(a, 4, 2, 4, 4, 3, &.{}, 5);
    defer layout.deinit();
    const sigmas = try sigmaSchedule(a, 4, 12.0);
    defer a.free(sigmas);
    const ts = try collectScheduleTs(a, &layout, sigmas[0..4], 12.0, 3.0, .{});
    defer a.free(ts);
    // 4 steps x 2 timesteps (video, audio) minus the sigma=1 step, where both
    // schedules coincide at t=0: 7 distinct values, sorted ascending.
    try testing.expectEqual(@as(usize, 7), ts.len);
    for (1..ts.len) |i| try testing.expect(ts[i] > ts[i - 1]);
    // Every step's plan resolves inside the collected set.
    for (0..4) |i| {
        var p = try buildTimestepPlanGlobal(a, &layout, sigmas[i], 12.0, 3.0, .{}, ts);
        defer p.deinit();
        for (p.runs) |r| try testing.expect(r.mod_row / 3 < ts.len);
    }
}

test "minimax h3: profile ladder arm schedule" {
    // Steps 0-1 are warmup (graph build + JIT land in step 0), then each arm
    // gets 3 consecutive steps; past the ladder the run degrades to .none so a
    // too-long STEPS setting stays harmless.
    try testing.expectEqual(Ablate.none, ladderArmForStep(0));
    try testing.expectEqual(Ablate.none, ladderArmForStep(1));
    try testing.expectEqual(Ablate.none, ladderArmForStep(2)); // measured baseline arm
    try testing.expectEqual(Ablate.none, ladderArmForStep(4));
    try testing.expectEqual(Ablate.sdpa, ladderArmForStep(5));
    try testing.expectEqual(Ablate.sdpa, ladderArmForStep(7));
    try testing.expectEqual(Ablate.attn, ladderArmForStep(8));
    try testing.expectEqual(Ablate.mlp, ladderArmForStep(11));
    try testing.expectEqual(Ablate.adaln, ladderArmForStep(14));
    try testing.expectEqual(Ablate.adaln, ladderArmForStep(16));
    try testing.expectEqual(Ablate.none, ladderArmForStep(17));
    try testing.expectEqual(Ablate.none, ladderArmForStep(100));
}

test "minimax h3: ablate mode parses off / ladder / fixed arms" {
    try testing.expectEqual(AblateMode.off, ablateModeFrom(null));
    try testing.expectEqual(AblateMode.off, ablateModeFrom(""));
    try testing.expectEqual(AblateMode.ladder, ablateModeFrom("ladder"));
    try testing.expectEqual(AblateMode{ .fixed = .sdpa }, ablateModeFrom("sdpa"));
    try testing.expectEqual(AblateMode{ .fixed = .adaln }, ablateModeFrom("adaln"));
    // Junk must not silently become an arm — a profile run with a typo'd env
    // measuring the WRONG thing is the silent-flag-eater class.
    try testing.expectEqual(AblateMode.off, ablateModeFrom("bogus"));
}

