test "minimax h3: canvas normalizes to the 768 short edge under the area cap" {
    const a = testing.allocator;
    var parsed = try loadFixture(a);
    defer parsed.deinit();

    for (parsed.value.object.get("adapt_canvas").?.array.items) |item| {
        const o = item.object;
        const got = adaptCanvas(jsonU32(o.get("in_w").?), jsonU32(o.get("in_h").?));
        try testing.expectEqual(jsonU32(o.get("out_w").?), got.w);
        try testing.expectEqual(jsonU32(o.get("out_h").?), got.h);
        try testing.expectEqual(@as(u32, 0), got.w % CANVAS_MULTIPLE);
        try testing.expectEqual(@as(u32, 0), got.h % CANVAS_MULTIPLE);
        try testing.expect(got.w >= CANVAS_MULTIPLE and got.h >= CANVAS_MULTIPLE);
        // No area invariant is asserted here on purpose. The cap binds the
        // NOMINAL canvas and each axis is then rounded to a 32 multiple, so the
        // result can overshoot (2560x1080 -> 1568x672 = 1.05 Mpx against a
        // 1.03 Mpx cap); and a square request never reaches the cap at all
        // (1024x1024 -> 768x768 = 0.59 Mpx), so it cannot be bounded from
        // below either. The reference values above are the contract.
    }
}

test "minimax h3: dual sigma schedule and velocity slope" {
