        );
        try testing.expectApproxEqRel(
            jsonF64(o.get("slope").?),
            timeShiftSlope(sv, SIGMA_SHIFT_VIDEO, SIGMA_SHIFT_AUDIO),
            1e-9,
        );
    }
    // Round trip: mapping there and back is the identity on the base grid.
    for ([_]f64{ 0.9, 0.5, 0.1, 0.01 }) |sv| {
        const sa = timeShiftSigma(sv, SIGMA_SHIFT_VIDEO, SIGMA_SHIFT_AUDIO);
